item.content:encoded:
html , body {overflow-x:hidden;}
@media only screen and (min-width: 720px) {
  .rfd {
    display:none !important;
  }
}
/* FOOTER SUBSCRIBE */
.footer-subscribe{
  margin-top: 15px;
}

/* label */
.footer-subscribe label{
  display: block;
  font-size: 14px;
  color: #ccc;
  margin-bottom: 8px;
}

/* input */
.footer-subscribe input[type="email"]{
  width: 100%;
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.05);
  color: #fff;
  font-size: 14px;
  outline: none;
  transition: 0.3s;
}

/* focus */
.footer-subscribe input[type="email"]:focus{
  border-color: #00c3ff;
  background: rgba(255,255,255,0.08);
}

/* button */
.footer-subscribe input[type="submit"]{
  margin-top: 10px;
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  border: none;
  background: #00c3ff;
  color: #071726;
  font-weight: 600;
  cursor: pointer;
  transition: 0.3s;
}

/* hover */
.footer-subscribe input[type="submit"]:hover{
  background: #00a8d9;
}

.etriple-contact-form{
  width: 100%;
}

.etriple-form-title{
  color: #ffffff;
  font-size: 34px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 28px;
}

.etriple-contact-form .etriple-form-group{
  margin-bottom: 14px;
}

.etriple-contact-form .wpcf7-form-control-wrap{
  display: block;
  width: 100%;
}

.etriple-contact-form input[type="text"],
.etriple-contact-form input[type="email"],
.etriple-contact-form textarea{
  width: 100%;
  background: #f1f1f1;
  border: 1px solid transparent;
  border-radius: 8px;
  color: #1a1a1a;
  font-size: 18px;
  font-weight: 400;
  padding: 18px 22px;
  box-sizing: border-box;
  outline: none;
  transition: all 0.3s ease;
  box-shadow: none;
}

.etriple-contact-form input[type="text"],
.etriple-contact-form input[type="email"]{
  height: 72px;
}

.etriple-contact-form textarea{
  min-height: 230px;
  resize: vertical;
  padding-top: 20px;
}

.etriple-contact-form input::placeholder,
.etriple-contact-form textarea::placeholder{
  color: #8a8a8a;
  opacity: 1;
}

.etriple-contact-form input:focus,
.etriple-contact-form textarea:focus{
  border-color: #184a9c;
  background: #ffffff;
}

.etriple-contact-form .etriple-submit-wrap{
  margin-top: 16px;
}

.etriple-contact-form input[type="submit"]{
  width: 100%;
  height: 64px;
  border: none;
  border-radius: 999px;
  background: #123f92;
  color: #ffffff;
  font-size: 20px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: none;
}

.etriple-contact-form input[type="submit"]:hover{
  background: #0f3478;
  transform: translateY(-1px);
}

.etriple-contact-form input[type="submit"]:active{
  transform: translateY(0);
}

.etriple-contact-form .wpcf7-spinner{
  margin: 12px 0 0;
}

.etriple-contact-form .wpcf7-not-valid-tip{
  font-size: 13px;
  margin-top: 6px;
  color: #ffb3b3;
}

.etriple-contact-form .wpcf7-response-output{
  margin: 16px 0 0 !important;
  padding: 12px 16px !important;
  border-radius: 8px;
  color: #ffffff;
}

/* mobile */
@media (max-width: 767px){
  .etriple-form-title{
    font-size: 28px;
    margin-bottom: 22px;
  }

  .etriple-contact-form input[type="text"],
  .etriple-contact-form input[type="email"]{
    height: 60px;
    font-size: 16px;
    padding: 14px 18px;
  }

  .etriple-contact-form textarea{
    min-height: 180px;
    font-size: 16px;
    padding: 16px 18px;
  }

  .etriple-contact-form input[type="submit"]{
    height: 58px;
    font-size: 18px;
  }
}
h1,h2,h3{line-height:4.2 rem ! important;}

