 <!-- LEFT -->
 <div class="etriple-footer-copy">
 E Triple Soft, 2026 © All Rights Reserved
 </div>

 <!-- CENTER (SOCIAL) -->
 <div class="etriple-footer-social">
 <a href="https://www.facebook.com/share/1Dca6xTt2i/?mibextid=wwXIfr" target="_blank">
 <svg viewBox="0 0 24 24" fill="currentColor">
 <path d="M22 12.07C22 6.51 17.52 2 12 2S2 6.51 2 12.07C2 17.09 5.66 21.24 10.44 22v-7.03H7.9v-2.9h2.54V9.85c0-2.52 1.49-3.92 3.78-3.92 1.1 0 2.25.2 2.25.2v2.48h-1.27c-1.25 0-1.64.78-1.64 1.58v1.88h2.8l-.45 2.9h-2.35V22C18.34 21.24 22 17.09 22 12.07z"/>
 </svg>
 </a>
 <a href="https://www.instagram.com/etriplesoft?igsh=MWJ6bjRnNXN2ZGRycA==" target="_blank" aria-label="Instagram">
 <svg viewBox="0 0 24 24" fill="currentColor">
 <path d="M7.75 2h8.5A5.75 5.75 0 0 1 22 7.75v8.5A5.75 5.75 0 0 1 16.25 22h-8.5A5.75 5.75 0 0 1 2 16.25v-8.5A5.75 5.75 0 0 1 7.75 2zm0 1.8A3.95 3.95 0 0 0 3.8 7.75v8.5a3.95 3.95 0 0 0 3.95 3.95h8.5a3.95 3.95 0 0 0 3.95-3.95v-8.5a3.95 3.95 0 0 0-3.95-3.95h-8.5zm8.95 1.35a1.1 1.1 0 1 1 0 2.2 1.1 1.1 0 0 1 0-2.2zM12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10zm0 1.8A3.2 3.2 0 1 0 12 15.2 3.2 3.2 0 0 0 12 8.8z"/>
 </svg>
 </a>

 <a href="https://www.linkedin.com/company/etriplesoft/?originalSubdomain=ae" target="_blank">
 <svg viewBox="0 0 24 24" fill="currentColor">
 <path d="M6.94 8.5A1.56 1.56 0 1 1 6.94 5.38 1.56 1.56 0 0 1 6.94 8.5zM5.5 9.75h2.88V18.5H5.5V9.75zm4.68 0h2.76v1.19h.04c.38-.73 1.32-1.5 2.72-1.5 2.91 0 3.45 1.91 3.45 4.39v4.67h-2.88v-4.14c0-.99-.02-2.27-1.38-2.27-1.39 0-1.6 1.08-1.6 2.2v4.21h-2.88V9.75z"/>
