 <!-- RIGHT -->
 <div class="etriple-footer-links">
 <a href="https://etriplesoft.com/terms-conditions/" target="_blank">Terms &amp; Conditions</a>
 <a href="https://etriplesoft.com/privacy-policy/" target="_blank">Privacy Policy</a>
 <a href="https://etriplesoft.com/wp-content/uploads/2025/10/E-TripleSoft-Company-Profile.pdf" target="_blank">Company Profile</a>
 </div>

 </div>
</footer>

<style>

/* MAIN FOOTER */
.etriple-footer{
 width: 100%;
 background: linear-gradient(135deg, #071726, #0b2235);
 padding: 22px 0;
}

/* GRID LAYOUT */
.etriple-footer-inner{
 max-width: 1400px;
 margin: auto;
 padding: 0 30px;

 display: grid;
 grid-template-columns: 1fr auto 1fr;
 align-items: center;
}

/* LEFT */
.etriple-footer-copy{
 color: #aaa;
 font-size: 14px;
 justify-self: start;
}

/* CENTER SOCIAL */
.etriple-footer-social{
 display: flex;
 gap: 12px;
 justify-self: center;
}

.etriple-footer-social a{
 width: 40px;
 height: 40px;
 border-radius: 10px;
 background: rgba(255,255,255,0.06);
 border: 1px solid rgba(255,255,255,0.1);

 display: flex;
 align-items: center;
 justify-content: center;

 color: #fff;
 transition: 0.3s;
}

.etriple-footer-social a:hover{
 background: #00c3ff;
 color: #071726;
 transform: translateY(-2px);
}

/* ICON SIZE */
.etriple-footer-social svg{
 width: 18px;
 height: 18px;
}

/* RIGHT LINKS */
.etriple-footer-links{
 display: flex;
 gap: 20px;
 justify-self: end;
}

.etriple-footer-links a{
 color: #ccc;
 text-decoration: none;
 font-size: 14px;
 position: relative;
 transition: 0.3s;
}

/* separator */
.etriple-footer-links a:not(:last-child)::after{
 content: "|";
 position: absolute;
 right: -12px;
 color: #444;
}

/* hover */
.etriple-footer-links a:hover{
 color: #00c3ff;
}

/* MOBILE */
@media(max-width:768px){
 .etriple-footer-inner{
 display: flex;
 flex-direction: column;
 gap: 15px;
 text-align: center;
 }

 .etriple-footer-links{
 justify-content: center;
 flex-wrap: wrap;
 }

 .etriple-footer-links a::after{
 display: none;
 }
}

</style>"},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"f7cccd9","elType":"container","settings":[],"elements":[{"id":"6f1fc9c","elType":"widget","settings":{"html":"<!-- Floating Download Button -->
<a class="amr-floating-download" href="https://etriplesoft.com/wp-content/uploads/2026/04/Etriplesoft_COA-generator.html" download>
 <span class="amr-download-icon">⬇</span>
 <span class="amr-download-text">Download Chart of accounts generator
</span>
</a>

<style>
.amr-floating-download{
 position: fixed;
 right: 14px;
 bottom: 90px;
 z-index: 99999;
 display: flex;
 align-items: center;
 justify-content: center;
 width: 55px;
 height: 55px;
 background: #0d6efd;
 color: #fff !important;
 border-radius: 50%;
 text-decoration: none !important;
 box-shadow: 0 10px 25px rgba(0,0,0,0.25);
 transition: all 0.3s ease;

 /* 🔥 IMPORTANT FIX */
 overflow: visible;
}

/* ICON */
.amr-download-icon{
 font-size: 22px; /* 👈 fix size (50px was too big) */
 transition: all 0.3s ease;
}

/* TEXT */
.amr-download-text{
 position: absolute;
 right: 70px;
 background: #0d6efd;
 padding: 8px 14px;
 border-radius: 30px;
 font-size: 14px;
 white-space: nowrap;

 opacity: 0;
 transform: translateX(20px);
 pointer-events: none;
 transition: all 0.3s ease;
}

/* HOVER */
.amr-floating-download:hover{
 background: #084298;
 transform: scale(1.05);
}

.amr-floating-download:hover .amr-download-text{
 opacity: 1;
 transform: translateX(0);
}

/* MOBILE */
@media (max-width: 767px){
 .amr-download-text{
 display: none;
 }
}
</style>"},"elements":[],"widgetType":"html"}],"isInner":false}]

