<style>

/* MAIN FOOTER */
.etriple-footer{
  width: 100%;
  background: linear-gradient(135deg, #071726, #0b2235);
  padding: 22px 0;
}

/* GRID LAYOUT */
.etriple-footer-inner{
  max-width: 1400px;
  margin: auto;
  padding: 0 30px;

  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
}

/* LEFT */
.etriple-footer-copy{
  color: #aaa;
  font-size: 14px;
  justify-self: start;
}

/* CENTER SOCIAL */
.etriple-footer-social{
  display: flex;
  gap: 12px;
  justify-self: center;
}

.etriple-footer-social a{
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);

  display: flex;
  align-items: center;
  justify-content: center;

  color: #fff;
  transition: 0.3s;
}

.etriple-footer-social a:hover{
  background: #00c3ff;
  color: #071726;
  transform: translateY(-2px);
}

/* ICON SIZE */
.etriple-footer-social svg{
  width: 18px;
  height: 18px;
}

/* RIGHT LINKS */
.etriple-footer-links{
  display: flex;
  gap: 20px;
  justify-self: end;
}

.etriple-footer-links a{
  color: #ccc;
  text-decoration: none;
  font-size: 14px;
  position: relative;
  transition: 0.3s;
}

/* separator */
.etriple-footer-links a:not(:last-child)::after{
  content: "|";
  position: absolute;
  right: -12px;
  color: #444;
}

/* hover */
.etriple-footer-links a:hover{
  color: #00c3ff;
}

/* MOBILE */
@media(max-width:768px){
  .etriple-footer-inner{
    display: flex;
    flex-direction: column;
    gap: 15px;
    text-align: center;
  }

  .etriple-footer-links{
    justify-content: center;
    flex-wrap: wrap;
  }

  .etriple-footer-links a::after{
    display: none;
  }
}

</style>				</div>
