<style>
.amr-floating-download{
  position: fixed;
  right: 14px;
  bottom: 90px;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 55px;
  height: 55px;
  background: #0d6efd;
  color: #fff !important;
  border-radius: 50%;
  text-decoration: none !important;
  box-shadow: 0 10px 25px rgba(0,0,0,0.25);
  transition: all 0.3s ease;

  /* 🔥 IMPORTANT FIX */
  overflow: visible;
}

/* ICON */
.amr-download-icon{
  font-size: 22px; /* 👈 fix size (50px was too big) */
  transition: all 0.3s ease;
}

/* TEXT */
.amr-download-text{
  position: absolute;
  right: 70px;
  background: #0d6efd;
  padding: 8px 14px;
  border-radius: 30px;
  font-size: 14px;
  white-space: nowrap;

  opacity: 0;
  transform: translateX(20px);
  pointer-events: none;
  transition: all 0.3s ease;
}

/* HOVER */
.amr-floating-download:hover{
  background: #084298;
  transform: scale(1.05);
}

.amr-floating-download:hover .amr-download-text{
  opacity: 1;
  transform: translateX(0);
}

/* MOBILE */
@media (max-width: 767px){
  .amr-download-text{
    display: none;
  }
}
