O:8:"stdClass":10:{s:5:"title";s:15:"country widget ";s:4:"icon";s:9:"eicon-cog";s:10:"categories";a:1:{i:0;s:5:"basic";}s:7:"push_id";s:5:"16057";s:6:"markup";s:1649:"<div id="country-popup-overlay" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:99999;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:16px;padding:2rem;max-width:400px;width:90%;text-align:center;font-family:Arial,sans-serif;">
    <h2 style="margin:0 0 8px;font-size:20px;color:#111;">Where are you located?</h2>
    <p style="color:#888;font-size:14px;margin:0 0 1.5rem;">We'll show you the right contact number.</p>
    <div style="display:flex;flex-direction:column;gap:12px;">

      <button class="country-btn" data-phone="+20 XX XXXX XXXX"
        style="display:flex;align-items:center;gap:14px;padding:14px 18px;border:1.5px solid #ddd;border-radius:10px;background:#fff;cursor:pointer;font-size:15px;font-family:Arial;">
        <span style="font-size:26px;">🇪🇬</span><strong>Egypt</strong>
      </button>

      <button class="country-btn" data-phone="+966 XX XXX XXXX"
        style="display:flex;align-items:center;gap:14px;padding:14px 18px;border:1.5px solid #ddd;border-radius:10px;background:#fff;cursor:pointer;font-size:15px;font-family:Arial;">
        <span style="font-size:26px;">🇸🇦</span><strong>Saudi Arabia</strong>
      </button>

      <button class="country-btn" data-phone="+971 XX XXX XXXX"
        style="display:flex;align-items:center;gap:14px;padding:14px 18px;border:1.5px solid #ddd;border-radius:10px;background:#fff;cursor:pointer;font-size:15px;font-family:Arial;">
        <span style="font-size:26px;">🇦🇪</span><strong>United Arab Emirates</strong>
      </button>

    </div>
  </div>
</div>";s:3:"css";s:0:"";s:2:"js";s:1266:"document.addEventListener('DOMContentLoaded', function () {

  function getCookie(name) {
    var v = document.cookie.match('(^|;) ?' + name + '=([^;]*)(;|$)');
    return v ? v[2] : null;
  }

  function setCookie(name, value, days) {
    var d = new Date();
    d.setTime(d.getTime() + 24 * 60 * 60 * 1000 * days);
    document.cookie = name + '=' + value + ';expires=' + d.toGMTString() + ';path=/';
  }

  function applyPhone(phone) {
    document.querySelectorAll('.phone-number').forEach(function (el) {
      el.textContent = phone;
    });
  }

  // If visitor already chose a country, apply it silently
  var saved = getCookie('site_phone');
  if (saved) {
    applyPhone(saved);
  } else {
    // Show the popup
    var overlay = document.getElementById('country-popup-overlay');
    if (overlay) overlay.style.display = 'flex';
  }

  // Handle button clicks
  document.querySelectorAll('.country-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var phone = this.getAttribute('data-phone');
      setCookie('site_phone', phone, 30);  // Remember for 30 days
      document.getElementById('country-popup-overlay').style.display = 'none';
      applyPhone(phone);
    });
  });

});";s:12:"css_includes";s:0:"";s:11:"js_includes";s:0:"";s:4:"tabs";O:8:"stdClass":3:{s:7:"content";a:0:{}s:5:"style";a:0:{}s:8:"advanced";a:0:{}}}

