<script>
/* ── Office data ─────────────────────────────────────────────────── */
const offices = {
  egypt: {
    title: '🇪🇬  Egypt Office — New Cairo',
    addr:  'Villa 350, South Academy B, New Cairo, Egypt',
    lat:   30.0335488,
    lng:   31.426572,
    zoom:  16,
    gmaps: 'https://www.google.com/maps/place/EtripleSoft/@30.0294462,31.4268472,16z/data=!4m6!3m5!1s0x14583d005962316d:0xbcf56af6e9c62adc!8m2!3d30.0335488!4d31.426572!16s%2Fg%2F11wppnmvj2?entry=ttu'
  },
  ksa: {
    title: '🇸🇦  Saudi Arabia Office — Riyadh',
    addr:  'As Sulimaniyah, Al Olaya, Riyadh 12214, Saudi Arabia',
    lat:   24.7071886,
    lng:   46.6759664,
    zoom:  16,
    gmaps: 'https://www.google.com/maps/place/As+Sulimaniyah,+Riyadh+12214,+Saudi+Arabia/@24.7077195,46.6710347,16z/data=!3m1!4b1!4m6!3m5!1s0x3e2f02d61363122f:0xd7b40857d2c92562!8m2!3d24.7071886!4d46.6759664!16s%2Fg%2F1tgplhpc?entry=ttu'
  },
  uae: {
    title: '🇦🇪  UAE Office — Dubai',
    addr:  'Latifa Tower, West Wing, Office 103, Sheikh Zayed Rd, Dubai, UAE',
    lat:   25.221958,
    lng:   55.28125,
    zoom:  16,
    gmaps: 'https://www.google.com/maps/place/Latifa+Tower/@25.221958,55.2786751,17z/data=!3m1!4b1!4m6!3m5!1s0x3e5f42ed8748e289:0x7d86ed2d819cf802!8m2!3d25.221958!4d55.28125!16s%2Fm%2F03czxh2?entry=ttu'
  }
};

/* ── OSM embed URL builder ──────────────────────────────────────── */
function osmEmbedUrl(lat, lng, zoom) {
  // OpenStreetMap embed — free, no API key, no connection issues
  const bbox = 0.008;
  const left   = lng - bbox;
  const bottom = lat - bbox;
  const right  = lng + bbox;
  const top    = lat + bbox;
  return `https://www.openstreetmap.org/export/embed.html?bbox=${left}%2C${bottom}%2C${right}%2C${top}&layer=mapnik&marker=${lat}%2C${lng}`;
}

/* ── Modal open ─────────────────────────────────────────────────── */
function openModal(key) {
  const o = offices[key];
  document.getElementById('modalTitleText').textContent = o.title;
  document.getElementById('modalAddrText').textContent  = o.addr;
  document.getElementById('modalGmapsLink').href        = o.gmaps;
  document.getElementById('modalMapFrame').src          = osmEmbedUrl(o.lat, o.lng, o.zoom);
  document.getElementById('mapModal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

/* ── Modal close ────────────────────────────────────────────────── */
function closeModal() {
  document.getElementById('mapModal').classList.remove('open');
  document.getElementById('modalMapFrame').src = ''; // stop tile loading
  document.body.style.overflow = '';
}

function closeOnOverlay(e) {
  if (e.target === document.getElementById('mapModal')) closeModal();
}

/* Keyboard ESC to close */
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* ── Static map thumbnails via OpenStreetMap tile ───────────────── */
/* Replace broken img fallback with a reliable OSM static-looking canvas */
document.querySelectorAll('.map-thumb img').forEach(img => {
  img.addEventListener('error', function() {
    // If the img fails, replace with an OSM iframe thumbnail
    const wrap = this.closest('.map-thumb');
    const btn  = wrap.querySelector('.map-open-btn');
    const onclick = btn.getAttribute('onclick');
    // Extract key from onclick="openModal('xxx')"
    const key = onclick.match(/'(\w+)'/)[1];
    const o = offices[key];
    const osmSrc = osmEmbedUrl(o.lat, o.lng, o.zoom);
    const frame = document.createElement('iframe');
    frame.src = osmSrc;
    frame.style.cssText = 'width:100%;height:100%;border:none;display:block;pointer-events:none;';
    frame.loading = 'lazy';
    this.replaceWith(frame);
  });
});
</script>
