{"timeout":1789887908,"value":{"content":"<div class="elementor-element elementor-element-4d45fb5 e-con-full e-flex e-con e-parent" data-id="4d45fb5" data-element_type="container" data-e-type="container">
				<div class="elementor-element elementor-element-f883b8f elementor-widget__width-inherit elementor-widget elementor-widget-html" data-id="f883b8f" data-element_type="widget" data-e-type="widget" data-widget_type="html.default">
					<!DOCTYPE html>
<html lang="en">
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet"/>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
  font-family:'Plus Jakarta Sans',sans-serif;
  background:#07132E;
  color:#fff;
  line-height:1.65;
  overflow-x:hidden;
  width:100%;
}

/* ─── CSS VARS ─────────────────────── */
:root{
  --navy:#07132E;
  --navy2:#091a42;
  --navy-card:rgba(17,36,88,0.58);
  --accent:#2563EB;
  --accent-lt:#3B82F6;
  --gold:#F59E0B;
  --muted:#7B91C4;
  --body-c:#C2CFEA;
  --border:rgba(59,130,246,0.15);
  --r:16px;
  --r-sm:10px;
}

/* ─── HERO ─────────────────────────── */
.hero{
  width:100%;
  min-height:100vh;
  display:flex;align-items:center;justify-content:center;
  text-align:center;
  padding:90px 10vw 80px;
  position:relative;overflow:hidden;
}
.hero-bg{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse 70% 55% at 50% 18%,rgba(37,99,235,.22) 0%,transparent 65%),
    radial-gradient(ellipse 40% 35% at 80% 85%,rgba(245,158,11,.06) 0%,transparent 58%),
    linear-gradient(160deg,#07132E 0%,#091a42 55%,#07132E 100%);
}
.hero-grid{
  position:absolute;inset:0;
  background-image:
    linear-gradient(rgba(59,130,246,.055) 1px,transparent 1px),
    linear-gradient(90deg,rgba(59,130,246,.055) 1px,transparent 1px);
  background-size:54px 54px;
  mask-image:radial-gradient(ellipse 80% 60% at 50% 40%,black 20%,transparent 75%);
}
.hero-content{position:relative;z-index:2;max-width:820px;width:100%;}
.hero-badge{
  display:inline-flex;align-items:center;gap:8px;
  background:rgba(37,99,235,.13);border:1px solid rgba(59,130,246,.30);
  border-radius:50px;padding:5px 18px;
  font-size:.72rem;font-weight:600;color:var(--accent-lt);
  letter-spacing:.10em;text-transform:uppercase;margin-bottom:26px;
}
.hero-badge::before{
  content:'';width:6px;height:6px;border-radius:50%;
  background:var(--accent-lt);animation:blink 2s infinite;
}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.22}}

h1{
  font-size:clamp(3rem,7vw,5.5rem);
  font-weight:800;line-height:1.06;
  letter-spacing:-.035em;color:#fff;margin-bottom:20px;
}
h1 .grad{
  display:block;
  background:linear-gradient(90deg,var(--accent-lt) 0%,#93C5FD 58%,var(--gold) 100%);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
.hero-sub{
  font-size:1.1rem;font-weight:300;color:var(--body-c);
  max-width:520px;margin:0 auto 40px;line-height:1.76;
}
.hero-ctas{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;}
.btn-primary{
  background:var(--accent);color:#fff;
  padding:14px 34px;border-radius:50px;
  font-size:.93rem;font-weight:600;text-decoration:none;
  transition:all .25s;box-shadow:0 4px 20px rgba(37,99,235,.35);
}
.btn-primary:hover{background:var(--accent-lt);transform:translateY(-2px);box-shadow:0 8px 28px rgba(37,99,235,.5);}
.btn-ghost{
  background:transparent;color:#fff;
  padding:14px 34px;border-radius:50px;
  font-size:.93rem;font-weight:400;text-decoration:none;
  border:1px solid rgba(255,255,255,.18);transition:all .25s;
}
.btn-ghost:hover{border-color:rgba(255,255,255,.44);background:rgba(255,255,255,.05);}
.scroll-hint{
  position:absolute;bottom:30px;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:6px;
  color:var(--muted);font-size:.7rem;letter-spacing:.1em;text-transform:uppercase;
}
.scroll-bar{
  width:1px;height:38px;
  background:linear-gradient(to bottom,var(--accent),transparent);
  animation:grow 2s ease-in-out infinite;
}
@keyframes grow{
  0%{transform:scaleY(0);transform-origin:top}
  50%{transform:scaleY(1);transform-origin:top}
  51%{transform:scaleY(1);transform-origin:bottom}
  100%{transform:scaleY(0);transform-origin:bottom}
}

/* ─── SHARED SECTION ──────────────── */
section{width:100%;padding:90px 8vw;}
.label{
  font-size:.72rem;font-weight:700;letter-spacing:.13em;
  text-transform:uppercase;color:var(--accent-lt);margin-bottom:10px;
}
h2{
  font-size:clamp(1.8rem,3.5vw,2.6rem);
  font-weight:800;letter-spacing:-.025em;line-height:1.15;color:#fff;
}

/* ─── ABOUT ───────────────────────── */
.about{
  background:linear-gradient(135deg,rgba(17,36,88,.40) 0%,rgba(7,19,46,.88) 100%);
  border-top:1px solid var(--border);border-bottom:1px solid var(--border);
}
.about-inner{
  width:100%;
  display:grid;grid-template-columns:1fr 1.2fr;gap:80px;align-items:center;
}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:36px;}
.stat{
  background:var(--navy-card);border:1px solid var(--border);
  border-radius:var(--r-sm);padding:22px 18px;
  backdrop-filter:blur(12px);transition:border-color .25s,transform .25s;
}
.stat:hover{border-color:rgba(59,130,246,.46);transform:translateY(-3px);}
.stat-n{font-size:2rem;font-weight:800;color:var(--accent-lt);line-height:1;}
.stat-l{font-size:.78rem;color:var(--muted);margin-top:5px;}
.about-text p{color:var(--body-c);font-size:.98rem;font-weight:300;line-height:1.8;margin-bottom:14px;}
.tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:20px;}
.tag{
  background:rgba(37,99,235,.11);border:1px solid rgba(59,130,246,.24);
  color:var(--body-c);padding:4px 14px;border-radius:50px;font-size:.77rem;
}

/* ─── LOCATIONS ───────────────────── */
.locations{background:#07132E;}
.loc-header{text-align:center;margin-bottom:56px;}
.loc-header .sub{color:var(--muted);margin-top:12px;font-size:.97rem;}
.loc-grid{
  width:100%;
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:28px;
}
.loc-card{
  background:var(--navy-card);border:1px solid var(--border);
  border-radius:var(--r);overflow:hidden;
  display:flex;flex-direction:column;
  transition:border-color .3s,transform .3s,box-shadow .3s;
}
.loc-card:hover{
  border-color:rgba(59,130,246,.52);transform:translateY(-5px);
  box-shadow:0 20px 54px rgba(0,0,0,.4);
}

/* ── Static map thumbnail (OpenStreetMap) ── */
.map-thumb{
  width:100%;height:220px;
  position:relative;overflow:hidden;
  background:#0c1a3a;
  display:block;
}
.map-thumb img{
  width:100%;height:100%;
  object-fit:cover;object-position:center;
  display:block;
  transition:transform .4s;
}
.loc-card:hover .map-thumb img{transform:scale(1.04);}

/* Open in Map button overlaid on thumbnail */
.map-open-btn{
  position:absolute;
  bottom:12px;right:12px;
  background:rgba(7,19,46,.85);
  border:1px solid rgba(59,130,246,.45);
  color:#fff;
  padding:7px 14px;
  border-radius:50px;
  font-size:.75rem;font-weight:600;
  display:flex;align-items:center;gap:6px;
  cursor:pointer;
  backdrop-filter:blur(8px);
  transition:background .2s,border-color .2s,transform .15s;
  z-index:2;
}
.map-open-btn:hover{background:var(--accent);border-color:var(--accent-lt);transform:translateY(-1px);}
.map-open-btn svg{width:12px;height:12px;flex-shrink:0;}

/* Card body */
.loc-body{padding:22px 24px 26px;flex:1;display:flex;flex-direction:column;}
.loc-flag{font-size:1.5rem;margin-bottom:8px;}
h3{font-size:1.08rem;font-weight:700;color:#fff;margin-bottom:14px;letter-spacing:-.01em;}
.loc-items{list-style:none;display:flex;flex-direction:column;gap:10px;flex:1;}
.loc-row{display:flex;align-items:flex-start;gap:9px;color:var(--body-c);font-size:.84rem;line-height:1.5;}
.ico{
  width:26px;height:26px;border-radius:6px;
  background:rgba(37,99,235,.15);display:flex;align-items:center;
  justify-content:center;flex-shrink:0;color:var(--accent-lt);
}
.ico svg{width:12px;height:12px;}
.loc-row a{color:var(--body-c);text-decoration:none;transition:color .2s;}
.loc-row a:hover{color:var(--accent-lt);}

/* ─── MAP MODAL ───────────────────── */
.modal-overlay{
  display:none;
  position:fixed;inset:0;z-index:1000;
  background:rgba(5,12,30,.88);
  backdrop-filter:blur(6px);
  align-items:center;justify-content:center;
  padding:20px;
}
.modal-overlay.open{display:flex;}
.modal-box{
  width:100%;max-width:1000px;
  background:#0c1a3a;
  border:1px solid rgba(59,130,246,.35);
  border-radius:20px;
  overflow:hidden;
  box-shadow:0 30px 80px rgba(0,0,0,.6);
  position:relative;
  animation:popIn .25s ease;
}
@keyframes popIn{from{opacity:0;transform:scale(.95)}to{opacity:1;transform:scale(1)}}
.modal-header{
  display:flex;align-items:center;justify-content:space-between;
  padding:16px 22px;
  border-bottom:1px solid var(--border);
  background:rgba(17,36,88,.5);
}
.modal-title{font-size:.95rem;font-weight:700;color:#fff;display:flex;align-items:center;gap:8px;}
.modal-title span{color:var(--muted);font-weight:400;}
.modal-actions{display:flex;align-items:center;gap:10px;}
.modal-gmaps-btn{
  display:inline-flex;align-items:center;gap:6px;
  background:var(--accent);color:#fff;
  padding:7px 16px;border-radius:50px;
  font-size:.78rem;font-weight:600;text-decoration:none;
  transition:background .2s,transform .15s;
}
.modal-gmaps-btn:hover{background:var(--accent-lt);transform:translateY(-1px);}
.modal-gmaps-btn svg{width:13px;height:13px;}
.modal-close{
  width:32px;height:32px;border-radius:50%;
  background:rgba(255,255,255,.08);border:none;
  color:#fff;font-size:1rem;cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:background .2s;
}
.modal-close:hover{background:rgba(255,255,255,.18);}
.modal-addr{
  padding:10px 22px;font-size:.82rem;color:var(--muted);
  border-bottom:1px solid var(--border);display:flex;align-items:center;gap:7px;
}
.modal-addr svg{width:13px;height:13px;color:var(--accent-lt);flex-shrink:0;}
/* OSM iframe inside modal — this works without API key */
.modal-map-frame{
  width:100%;
  height:clamp(320px,50vh,520px);
  border:none;display:block;
}

/* ─── PARTNERS ────────────────────── */
.partners{
  background:rgba(17,36,88,.20);
  border-top:1px solid var(--border);border-bottom:1px solid var(--border);
  padding:28px 8vw;width:100%;
}
.partners-inner{
  width:100%;
  display:flex;align-items:center;justify-content:center;gap:44px;flex-wrap:wrap;
}
.p-badge{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:.8rem;font-weight:500;}
.p-ico{width:32px;height:32px;border-radius:7px;background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;font-size:.9rem;}
.divider{width:1px;height:28px;background:var(--border);}

/* ─── FORM ────────────────────────── */
.form-sec{
  background:linear-gradient(135deg,rgba(17,36,88,.30),rgba(7,19,46,.94));
  border-top:1px solid var(--border);
}
.form-wrap{
  width:100%;
  display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:start;
}
.form-left h2{margin-bottom:14px;}
.form-left > p{color:var(--muted);font-size:.97rem;line-height:1.74;margin-bottom:32px;}
.methods{display:flex;flex-direction:column;gap:13px;}
.method{
  display:flex;align-items:center;gap:13px;
  padding:13px 16px;background:var(--navy-card);border:1px solid var(--border);
  border-radius:var(--r-sm);text-decoration:none;transition:border-color .25s,transform .25s;
}
.method:hover{border-color:rgba(59,130,246,.48);transform:translateX(4px);}
.m-ico{
  width:36px;height:36px;border-radius:9px;
  background:linear-gradient(135deg,var(--accent),#112458);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;
}
.m-ico svg{width:15px;height:15px;color:#fff;}
.m-text strong{display:block;color:#fff;font-size:.83rem;font-weight:600;}
.m-text span{color:var(--muted);font-size:.78rem;}
.form-card{
  background:var(--navy-card);border:1px solid var(--border);
  border-radius:var(--r);padding:38px 36px;backdrop-filter:blur(16px);
}
.form-title{font-size:1.25rem;font-weight:800;margin-bottom:4px;}
.form-sub{color:var(--muted);font-size:.85rem;margin-bottom:26px;}
.f-row{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:14px;}
label{font-size:.76rem;font-weight:600;color:var(--muted);letter-spacing:.03em;}
input,textarea,select{
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.09);
  border-radius:var(--r-sm);color:#fff;
  font-family:'Plus Jakarta Sans',sans-serif;font-size:.9rem;
  padding:11px 14px;outline:none;width:100%;transition:border-color .2s,background .2s;
}
input::placeholder,textarea::placeholder{color:rgba(123,145,196,.42);}
input:focus,textarea:focus,select:focus{border-color:var(--accent);background:rgba(37,99,235,.06);}
textarea{resize:vertical;min-height:114px;}
select option{background:#0c1a3a;}
.submit-btn{
  width:100%;background:linear-gradient(135deg,var(--accent),var(--accent-lt));
  color:#fff;border:none;padding:14px;
  border-radius:var(--r-sm);font-family:'Plus Jakarta Sans',sans-serif;
  font-size:.92rem;font-weight:700;cursor:pointer;
  transition:opacity .2s,transform .15s,box-shadow .2s;
  box-shadow:0 4px 18px rgba(37,99,235,.38);margin-top:3px;
}
.submit-btn:hover{opacity:.9;transform:translateY(-2px);box-shadow:0 8px 26px rgba(37,99,235,.52);}
.trust{
  display:flex;align-items:center;gap:7px;
  margin-top:12px;color:var(--muted);font-size:.75rem;justify-content:center;
}
.trust svg{color:var(--gold);flex-shrink:0;}

/* ─── RESPONSIVE ──────────────────── */
@media(max-width:1024px){
  .loc-grid{grid-template-columns:1fr 1fr;}
}
@media(max-width:900px){
  .about-inner{grid-template-columns:1fr;gap:40px;}
  .form-wrap{grid-template-columns:1fr;gap:48px;}
  .f-row{grid-template-columns:1fr;}
  .loc-grid{grid-template-columns:1fr;max-width:560px;margin:0 auto;}
}
@media(max-width:600px){
  section{padding:64px 5vw;}
  .stats{grid-template-columns:1fr 1fr;}
  .form-card{padding:26px 18px;}
  .hero{padding:80px 6vw 70px;}
}

/* ─── HERO ANIMATIONS ─────────────── */
@keyframes up{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}
.hero-badge{animation:up .55s ease both;}
h1{animation:up .65s .08s ease both;}
.hero-sub{animation:up .65s .16s ease both;}
.hero-ctas{animation:up .65s .24s ease both;}
</style>
</head>

<!-- ════════════════ HERO ════════════════ -->
<section class="hero">
  <div class="hero-bg"></div>
  <div class="hero-grid"></div>
  <div class="hero-content">
    <div class="hero-badge">Offices in 3 Countries</div>
    <h1>
      Contact Us
      <span class="grad">We're Here to Help</span>
    </h1>
    <p class="hero-sub">Have a question or a project in mind? Our teams in Egypt, Saudi Arabia, and the UAE are ready to connect with you.</p>
    <div class="hero-ctas">
      <a href="#form" class="btn-primary">Send a Message</a>
      <a href="#locations" class="btn-ghost">Our Locations</a>
    </div>
  </div>
  <div class="scroll-hint">
    <div class="scroll-bar"></div>
    <span>Scroll</span>
  </div>
</section>

<!-- ════════════════ ABOUT ════════════════ -->
