.ets-app-feature,
.ets-app-step{
  padding:28px;
}
.ets-app-card:hover,
.ets-app-feature:hover,
.ets-app-step:hover{
  transform:translateY(-6px);
  border-color:rgba(0,195,255,0.4);
  box-shadow:0 18px 40px rgba(0,0,0,0.18);
}
.ets-app-icon{
  width:62px;
  height:62px;
  border-radius:18px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:rgba(0,195,255,0.12);
  font-size:28px;
  margin-bottom:18px;
}
.ets-app-card h3,
.ets-app-feature h3,
.ets-app-step h3,
.ets-app-panel-box h3{
  font-size:23px;
  margin:0 0 14px;
  color:#fff;
}
.ets-app-card p,
.ets-app-feature p,
.ets-app-step p{
  font-size:16px;
  line-height:1.8;
  color:rgba(255,255,255,0.75);
  margin:0;
}
.ets-app-two-col{
  display:grid;
  grid-template-columns:1.1fr .9fr;
  gap:34px;
  align-items:start;
}
.ets-app-text h2{
  font-size:42px;
  line-height:1.18;
  margin:0 0 18px;
}
.ets-app-text p{
  font-size:17px;
  line-height:1.85;
  color:rgba(255,255,255,0.75);
  margin:0 0 24px;
}
.ets-app-list{
  list-style:none;
  padding:0;
  margin:0;
}
.ets-app-list li{
  position:relative;
  padding-left:30px;
  margin-bottom:14px;
  font-size:16px;
  line-height:1.8;
  color:rgba(255,255,255,0.82);
}
.ets-app-list li::before{
  content:"✓";
  position:absolute;
  left:0;
  top:0;
  color:#00c3ff;
  font-weight:700;
}
.ets-app-panel-box{
  padding:30px;
}
.ets-app-panel-item{
  padding:18px 0;
  border-bottom:1px solid rgba(255,255,255,0.08);
}
.ets-app-panel-item:last-child{
  border-bottom:none;
}
.ets-app-panel-item strong{
  display:block;
  font-size:18px;
  color:#fff;
  margin-bottom:6px;
}
.ets-app-panel-item span{
  display:block;
  font-size:15px;
  line-height:1.7;
  color:rgba(255,255,255,0.72);
}
.ets-app-step-no{
  display:inline-block;
  font-size:32px;
  font-weight:700;
  color:#00c3ff;
  margin-bottom:16px;
}
.ets-app-cta-wrap{
  padding-top:20px;
  padding-bottom:110px;
}
.ets-app-cta{
  text-align:center;
  padding:60px 30px;
  border-radius:28px;
  background:linear-gradient(135deg, #0b2444, #123c6d);
  border:1px solid rgba(255,255,255,0.08);
  max-width:1100px;
  margin:0 auto;
}
.ets-app-cta h2{
  font-size:46px;
  line-height:1.15;
  margin:0 0 18px;
}
.ets-app-cta p{
  font-size:17px;
  line-height:1.8;
  max-width:720px;
  margin:0 auto 26px;
  color:rgba(255,255,255,0.82);
}
@media (max-width:1200px){
  .ets-app-grid-3,
  .ets-app-grid-4{
    grid-template-columns:repeat(2,1fr);
  }
  .ets-app-strip{
    grid-template-columns:repeat(3,1fr);
  }
  .ets-app-hero h1{
    font-size:54px;
  }
}
@media (max-width:991px){
  .ets-app-two-col,
  .ets-app-grid-2{
    grid-template-columns:1fr;
  }
  .ets-app-hero{
    min-height:auto;
    padding-top:90px;
    padding-bottom:90px;
  }
  .ets-app-hero h1{
    font-size:46px;
  }
  .ets-app-head h2,
  .ets-app-text h2,
  .ets-app-cta h2{
    font-size:36px;
  }
}
@media (max-width:767px){
  .ets-app-hero,
  .ets-app-section{
    padding-left:20px;
    padding-right:20px;
  }
  .ets-app-hero h1{
    font-size:36px;
  }
  .ets-app-hero p{
    font-size:16px;
  }
  .ets-app-head h2,
  .ets-app-text h2,
  .ets-app-cta h2{
    font-size:30px;
  }
  .ets-app-grid-3,
  .ets-app-grid-4,
  .ets-app-strip{
    grid-template-columns:1fr;
  }
  .ets-app-card,
  .ets-app-feature,
  .ets-app-step,
  .ets-app-panel-box{
    border-radius:18px;
  }
  .ets-app-btn{
    width:100%;
  }
  .ets-app-cta{
    padding:40px 20px;
  }
}
</style>"},"elements":[],"widgetType":"html"}],"isInner":false}]

