[{"id":"0d3c789","elType":"container","settings":{"content_width":"full","boxed_width":{"unit":"px","size":1600,"sizes":[]}},"elements":[{"id":"d748ba9","elType":"widget","settings":{"html":"


<!--
╔══════════════════════════════════════════════════════════════╗
║  ETRIPLESOFT — AI AUTOMATION SERVICES PAGE                   ║
║  Image: ai.png injected in Section 3 (Introduction)          ║
║  Alt text: "Etriplesoft AI Automation in Egypt, KSA and UAE" ║
║  SEO: <figure>/<figcaption> + schema.org ImageObject         ║
╚══════════════════════════════════════════════════════════════╝
-->

<!-- Primary SEO -->
<title>AI Automation &amp; Workflow Automation Software | Etriplesoft</title>

<!-- ImageObject schema for the banner image -->
<script type="application/ld+json">
{
  "@context":"https://schema.org",
  "@type":"ImageObject",
  "name":"Etriplesoft AI Automation in Egypt, KSA and UAE",
  "description":"Etriplesoft AI Automation Services — Intelligent Processing, Smart Automation, Increased Productivity for businesses in Egypt, UAE and Saudi Arabia",
  "contentUrl":"https://etriplesoft.com/wp-content/uploads/ai-automation-etriplesoft.png",
  "author":{"@type":"Organization","name":"Etriplesoft","url":"https://etriplesoft.com"},
  "representativeOfPage":true
}
</script>

<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet"/>
<style>
:root{
  --dark:#071020;--dark2:#0A1628;--dark3:#0D2240;--dark4:#112B4E;
  --blue:#1B6FE4;--blue-lt:#3B8AF5;--cyan:#00C4CC;--cyan-dk:#009AA0;
  --purple:#7C3AED;--purple-lt:#A78BFA;--bg:#071020;--bg2:#0A1628;
  --surface:#0F1E35;--border:#1A3050;--text:#E8F0FF;--muted:#7A9DC8;
  --green:#22C55E;--red:#F87171;--orange:#FB923C;
  --r:12px;--rl:18px;
  --sh:0 4px 24px rgba(0,0,0,.45);
  --glow:0 0 40px rgba(27,111,228,.20);
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Plus Jakarta Sans',-apple-system,sans-serif;background:var(--bg);color:var(--text);font-size:16px;line-height:1.7;overflow-x:hidden}
a{color:var(--cyan);text-decoration:none;transition:color .2s}
a:hover{color:#fff}
h2{font-size:clamp(24px,3.5vw,38px);font-weight:800;color:#E8F0FF;line-height:1.2;margin-bottom:16px}
h3{font-size:19px;font-weight:700;color:#C8DEFF;margin-bottom:10px}
p{color:var(--muted);margin-bottom:14px;line-height:1.8}
strong{color:#E8F0FF}
ul{list-style:none}
.wrap{max-width:1160px;margin:0 auto;padding:0 24px}
.sec{padding:80px 0}
.sec-sm{padding:52px 0}
.eye{display:inline-block;font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--cyan);background:rgba(0,196,204,.10);padding:5px 16px;border-radius:100px;margin-bottom:16px;border:1px solid rgba(0,196,204,.20)}
.hr{height:1px;background:var(--border)}
.btn{display:inline-flex;align-items:center;gap:8px;background:var(--blue);color:#fff;padding:14px 32px;border-radius:9px;font-weight:700;font-size:15px;transition:all .2s;cursor:pointer;border:none}
.btn:hover{background:var(--blue-lt);transform:translateY(-2px);box-shadow:0 8px 24px rgba(27,111,228,.35);color:#fff}
.btn-cyan{background:var(--cyan)}
.btn-cyan:hover{background:var(--cyan-dk);box-shadow:0 8px 24px rgba(0,196,204,.35)}
.btn-outline{background:transparent;border:1.5px solid var(--border);color:var(--muted)}
.btn-outline:hover{border-color:var(--blue);color:#E8F0FF;background:rgba(27,111,228,.08)}
.grid-bg{position:absolute;inset:0;pointer-events:none;overflow:hidden;background-image:linear-gradient(rgba(27,111,228,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(27,111,228,.04) 1px,transparent 1px);background-size:60px 60px;mask-image:radial-gradient(ellipse at 50% 50%,black 30%,transparent 80%)}
.hero{position:relative;background:linear-gradient(135deg,#040C1A 0%,#071020 35%,#0A1A32 65%,#0D2240 100%);padding:100px 0 80px;overflow:hidden}
.hero-orb{position:absolute;border-radius:50%;filter:blur(80px);pointer-events:none}
.orb-1{width:500px;height:500px;background:rgba(27,111,228,.18);top:-100px;right:-80px}
.orb-2{width:350px;height:350px;background:rgba(0,196,204,.12);bottom:-60px;left:-60px}
.orb-3{width:200px;height:200px;background:rgba(124,58,237,.15);top:40%;left:30%}
.hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
@media(max-width:780px){.hero-grid{grid-template-columns:1fr}}
.hero-eyebrow{display:inline-flex;align-items:center;gap:8px;background:rgba(27,111,228,.12);border:1px solid rgba(27,111,228,.25);border-radius:100px;padding:6px 16px;font-size:12px;color:#90B8F0;margin-bottom:24px;font-weight:600}
.hero-eyebrow .pulse{width:7px;height:7px;border-radius:50%;background:var(--cyan);animation:pulse 2s infinite}
@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.4;transform:scale(.8)}}
.hero-title{font-size:clamp(34px,5.5vw,58px);font-weight:800;color:#fff;line-height:1.1;margin-bottom:20px;letter-spacing:-.5px}
.hero-title .accent{background:linear-gradient(135deg,#1B6FE4 0%,#00C4CC 50%,#7C3AED 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero-sub{font-size:17px;color:#8AAFD8;max-width:540px;margin-bottom:36px;line-height:1.75}
.hero-sub strong{color:#fff}
.hero-btns{display:flex;gap:14px;flex-wrap:wrap}
.hero-chips{display:flex;gap:12px;flex-wrap:wrap;margin-top:40px}
.chip{background:#0F1E35;border:1px solid #1A3050;border-radius:100px;padding:8px 18px;font-size:12px;font-weight:600;color:#90B8F0;display:inline-flex;align-items:center;gap:7px}
.chip .ci{font-size:16px}
.hero-visual{position:relative;display:flex;align-items:center;justify-content:center}
.hero-visual-inner{background:linear-gradient(135deg,#0D2240 0%,#112B4E 100%);border:1px solid #1A3A5C;border-radius:20px;padding:28px;box-shadow:var(--glow),var(--sh);width:100%;max-width:440px}
.ribbon{background:#0D2240;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
.rib-in{display:grid;grid-template-columns:repeat(4,1fr)}
@media(max-width:600px){.rib-in{grid-template-columns:repeat(2,1fr)}}
.rsc{padding:28px 24px;text-align:center;border-right:1px solid rgba(255,255,255,.06)}
.rsc:last-child{border:none}
.rsn{font-size:36px;font-weight:800;background:linear-gradient(135deg,var(--blue),var(--cyan));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;line-height:1}
.rsl{font-size:12px;color:var(--muted);margin-top:5px}
.chg{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-top:32px}
.chc{background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:26px 24px;position:relative;overflow:hidden;transition:border-color .2s,box-shadow .2s}
.chc::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--blue),var(--cyan));opacity:0;transition:opacity .2s}
.chc:hover{border-color:rgba(27,111,228,.4);box-shadow:var(--glow)}
.chc:hover::before{opacity:1}
.ch-icon{font-size:32px;margin-bottom:12px}
.solve-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px;align-items:center;margin-top:32px}
@media(max-width:720px){.solve-grid{grid-template-columns:1fr}}
.solve-steps{display:flex;flex-direction:column;gap:16px}
.sstep{display:flex;align-items:flex-start;gap:16px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:20px;transition:border-color .2s}
.sstep:hover{border-color:var(--cyan)}
.sstep-num{width:34px;height:34px;flex-shrink:0;background:linear-gradient(135deg,var(--blue),var(--cyan));border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:800;color:#fff}
.sstep-body h4{font-size:14px;font-weight:700;color:#C8DEFF;margin-bottom:4px}
.sstep-body p{font-size:13px;color:var(--muted);margin:0;line-height:1.6}
.solve-vis{background:linear-gradient(135deg,#0D2240,#112B4E);border:1px solid #1A3A5C;border-radius:var(--rl);padding:28px;box-shadow:var(--sh);display:flex;flex-direction:column;gap:12px}
.sv-row{display:flex;align-items:center;gap:12px;background:#091525;border-radius:10px;padding:12px 16px;border:1px solid #1A3050}
.sv-icon{font-size:22px;flex-shrink:0}
.sv-label{font-size:12px;font-weight:700;color:#C8DEFF}
.sv-sub{font-size:11px;color:var(--muted)}
.sv-badge{margin-left:auto;padding:3px 10px;border-radius:100px;font-size:10px;font-weight:700}
.sv-badge.on{background:rgba(34,197,94,.15);color:#4ADE80}
.sv-badge.run{background:rgba(27,111,228,.15);color:#60A5FA}
.sv-badge.ai{background:rgba(124,58,237,.15);color:#A78BFA}
.feat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px;margin-top:32px}
.feat-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:36px 30px;transition:transform .2s,box-shadow .2s,border-color .2s;position:relative;overflow:hidden}
.feat-card::after{content:'';position:absolute;bottom:0;left:0;right:0;height:3px;background:linear-gradient(90deg,var(--blue),var(--cyan),var(--purple));opacity:0;transition:opacity .2s}
.feat-card:hover{transform:translateY(-4px);box-shadow:var(--glow);border-color:rgba(27,111,228,.35)}
.feat-card:hover::after{opacity:1}
.feat-icon{width:52px;height:52px;border-radius:14px;background:linear-gradient(135deg,rgba(27,111,228,.2),rgba(0,196,204,.2));border:1px solid rgba(27,111,228,.25);display:flex;align-items:center;justify-content:center;font-size:24px;margin-bottom:20px}
.feat-card h3{font-size:16px;font-weight:700;color:#C8DEFF;margin-bottom:12px;letter-spacing:.3px;line-height:1.4}
.feat-card p{font-size:14px;color:var(--muted);margin:0;line-height:1.85;letter-spacing:.15px}
.ben-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:32px}
.ben-card{border-radius:var(--r);padding:28px 22px;text-align:center;background:linear-gradient(135deg,#0D2240 0%,#112B4E 100%);border:1px solid #1A3A5C;transition:box-shadow .2s}
.ben-card:hover{box-shadow:var(--glow)}
.ben-num{font-size:40px;font-weight:800;background:linear-gradient(135deg,var(--cyan),var(--blue-lt));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;line-height:1;margin-bottom:8px}
.ben-label{font-size:14px;font-weight:700;color:#C8DEFF;margin-bottom:8px}
.ben-desc{font-size:12px;color:var(--muted);line-height:1.5;margin:0}
.why-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px;margin-top:32px}
.why-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:32px 26px;border-top:3px solid var(--blue);transition:box-shadow .2s}
.why-card:hover{box-shadow:var(--glow)}
.why-icon{font-size:30px;margin-bottom:16px}
.why-card h3{font-size:15px;font-weight:700;color:#C8DEFF;margin-bottom:10px;letter-spacing:.3px;line-height:1.4}
.why-card p{font-size:13px;color:var(--muted);margin:0;line-height:1.85;letter-spacing:.15px}
.svc-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:28px}
.svc-link{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:16px 18px;font-size:13px;font-weight:600;color:#90B8F0;transition:all .2s;text-decoration:none}
.svc-link:hover{background:#112B4E;border-color:var(--blue);color:#E8F0FF;transform:translateY(-2px);box-shadow:0 4px 16px rgba(27,111,228,.15)}
.svc-link-icon{font-size:20px;flex-shrink:0}
.svc-link-arrow{margin-left:auto;color:var(--border);font-size:12px;transition:color .2s}
.svc-link:hover .svc-link-arrow{color:var(--cyan)}
.faqlist{margin-top:32px;display:flex;flex-direction:column;gap:10px}
.faqitem{background:var(--surface);border:1px solid var(--border);border-radius:var(--r);overflow:hidden}
.faqq{padding:18px 22px;font-weight:700;font-size:15px;color:#C8DEFF;cursor:pointer;display:flex;justify-content:space-between;align-items:center;user-select:none;transition:background .15s;gap:12px}
.faqq:hover{background:#112B4E}
.faqq-icon{width:22px;height:22px;border-radius:50%;border:1.5px solid var(--cyan);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:14px;color:var(--cyan);font-weight:300;transition:transform .2s,background .2s}
.faqq.open .faqq-icon{background:var(--cyan);color:#071020;transform:rotate(45deg)}
.faqa{padding:0 22px 18px;font-size:14px;color:var(--muted);line-height:1.75;display:none;border-top:1px solid var(--border)}
.faqa.open{display:block;padding-top:14px}
.cta-sec{position:relative;overflow:hidden;background:linear-gradient(135deg,#040C1A 0%,#071B38 40%,#0D2240 70%,#1A3A5C 100%);padding:96px 0;text-align:center}
.cta-sec::before{content:'';position:absolute;inset:0;background-image:radial-gradient(ellipse at 50% 0%,rgba(27,111,228,.30) 0%,transparent 60%),radial-gradient(ellipse at 80% 100%,rgba(0,196,204,.15) 0%,transparent 50%),radial-gradient(ellipse at 10% 50%,rgba(124,58,237,.12) 0%,transparent 50%);pointer-events:none}
.cta-tag{display:inline-flex;align-items:center;gap:8px;background:rgba(0,196,204,.10);border:1px solid rgba(0,196,204,.25);border-radius:100px;padding:6px 18px;font-size:12px;color:var(--cyan);margin-bottom:24px;font-weight:600}
.cta-sec h2{color:#fff;font-size:clamp(28px,4vw,46px);margin-bottom:14px;position:relative}
.cta-sec p{color:#8AAFD8;max-width:560px;margin:0 auto 36px;font-size:17px;position:relative}
.cta-sub{color:rgba(255,255,255,.30);font-size:13px;margin-top:18px;position:relative}
.cta-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;position:relative}
.text-gradient{background:linear-gradient(135deg,var(--blue-lt),var(--cyan));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.mono{font-family:'DM Mono',monospace}
@media(max-width:600px){.sec{padding:56px 0}.hero{padding:70px 0 56px}}
.fade-up{opacity:0;transform:translateY(24px);transition:opacity .55s ease,transform .55s ease}
.fade-up.visible{opacity:1;transform:translateY(0)}
</style>
</head>

