<script>
document.querySelectorAll('.faqq').forEach(q=>{
  q.addEventListener('click',()=>{
    const item=q.closest('.faqitem');
    const a=item.querySelector('.faqa');
    const open=q.classList.contains('open');
    document.querySelectorAll('.faqq').forEach(x=>x.classList.remove('open'));
    document.querySelectorAll('.faqa').forEach(x=>x.classList.remove('open'));
    if(!open){q.classList.add('open');a.classList.add('open')}
  });
});
const obs=new IntersectionObserver(entries=>{
  entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible')}})
},{threshold:.12});
document.querySelectorAll('.chc,.feat-card,.ben-card,.why-card,.sstep,.sv-row').forEach(el=>{
  el.classList.add('fade-up');obs.observe(el);
});
</script>				</div>
