  width:62px;
  height:62px;
  border-radius:18px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:rgba(0,195,255,0.12);
  font-size:28px;
  margin-bottom:18px;
}
.ets-app-card h3,
.ets-app-feature h3,
.ets-app-step h3,
.ets-app-panel-box h3{
