<style>
/* ── تأمين تحميل الخط قبل الرسم ── */
body::before{content:'';font-family:'Cairo','Tajawal';position:absolute;visibility:hidden}

/* ══════════════════════════════════════
   SCOPE: كل شيء تحت #etp-ws
   يضمن عدم تأثر أي ثيم WordPress
══════════════════════════════════════ */
#etp-ws{
  background:#031327 !important;
  color:#fff !important;
  font-family:'Cairo','Tajawal',sans-serif !important;
  overflow:hidden !important;
  direction:rtl !important;
  text-align:right !important;
  font-size:15px !important;
  line-height:1.8 !important;
}
#etp-ws *{
  box-sizing:border-box !important;
  font-family:'Cairo','Tajawal',sans-serif !important;
}
#etp-ws a{color:#7ddcff !important;text-decoration:none !important;transition:color .2s}
#etp-ws a:hover{color:#fff !important}
#etp-ws strong{color:#E8F0FF !important}
#etp-ws ul{list-style:none !important}

/* ══ الهيرو ══ */
#etp-ws .ets-ws-hero{
  min-height:90vh;display:flex;align-items:center;
  padding:100px 7%;
  background:linear-gradient(135deg,rgba(3,19,39,.94),rgba(7,34,67,.90)),
    url("https://images.unsplash.com/photo-1467232004584-a241de8bcf5d?auto=format&fit=crop&w=1600&q=80") center/cover no-repeat;
  position:relative;
}
#etp-ws .ets-ws-hero::after{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at top left,rgba(0,195,255,.18),transparent 28%);
  pointer-events:none;
}
#etp-ws .ets-ws-hero-content{max-width:760px;position:relative;z-index:2;}

#etp-ws .ets-ws-badge,
#etp-ws .ets-ws-mini{
  display:inline-block !important;
  font-size:12px !important;
  font-weight:700 !important;
  letter-spacing:.5px !important;
  color:#7ddcff !important;
  margin-bottom:16px !important;
}
#etp-ws .ets-ws-hero h1{
  font-size:clamp(20px,3vw,34px) !important;
  line-height:1.4 !important;
  font-weight:700 !important;
  margin:0 0 20px !important;
  color:#fff !important;
  letter-spacing:-.01em !important;
}
#etp-ws .ets-ws-hero h1 span{
  background:linear-gradient(135deg,#00c3ff,#7ddcff);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
#etp-ws .ets-ws-hero p{
  font-size:14px !important;line-height:1.85 !important;
  color:rgba(255,255,255,.82) !important;margin:0 0 28px !important;
  max-width:660px !important;
}

/* ══ الأزرار ══ */
#etp-ws .ets-ws-buttons{display:flex;flex-wrap:wrap;gap:14px;}
#etp-ws .center-btns{justify-content:center;}
#etp-ws .ets-ws-btn{
  display:inline-flex !important;align-items:center;justify-content:center;
  padding:13px 26px !important;border-radius:999px;text-decoration:none !important;
  font-size:14px !important;font-weight:700 !important;transition:all .3s ease;
}
#etp-ws .ets-ws-btn-primary{background:#00c3ff !important;color:#031327 !important;}
#etp-ws .ets-ws-btn-primary:hover{transform:translateY(-2px);background:#19cdfd !important;}
#etp-ws .ets-ws-btn-secondary{
  border:1px solid rgba(255,255,255,.2) !important;
  color:#fff !important;background:rgba(255,255,255,.04) !important;
}
#etp-ws .ets-ws-btn-secondary:hover{border-color:#00c3ff !important;color:#00c3ff !important;transform:translateY(-2px);}

/* ══ شريط الثقة ══ */
#etp-ws .ets-ws-strip{
  display:grid;grid-template-columns:repeat(5,1fr);gap:14px;
  padding:20px 7%;background:#08203a;
  border-top:1px solid rgba(255,255,255,.06);
  border-bottom:1px solid rgba(255,255,255,.06);
}
#etp-ws .ets-ws-strip-item{
  text-align:center;padding:14px 10px;border-radius:12px;
  background:rgba(255,255,255,.03);color:rgba(255,255,255,.88);
  font-size:13px !important;font-weight:600 !important;
}

/* ══ الأقسام ══ */
#etp-ws .ets-ws-section{padding:72px 7%;}
#etp-ws .ets-ws-head{max-width:720px;margin-bottom:40px;}
#etp-ws .ets-ws-head.center{text-align:center;margin-left:auto;margin-right:auto;}
#etp-ws .ets-ws-head h2{
  font-size:clamp(15px,2vw,22px) !important;
  line-height:1.4 !important;margin:0 0 14px !important;
  color:#fff !important;font-weight:700 !important;
}
#etp-ws .ets-ws-head p{
  font-size:14px !important;line-height:1.8 !important;
  color:rgba(255,255,255,.7) !important;margin:0 !important;
}

/* ══ الشبكات ══ */
#etp-ws .ets-ws-grid{display:grid;gap:20px;}
#etp-ws .ets-ws-grid-3{grid-template-columns:repeat(3,1fr);}
#etp-ws .ets-ws-grid-4{grid-template-columns:repeat(4,1fr);}
#etp-ws .ets-ws-grid-2{grid-template-columns:repeat(2,1fr);}

/* ══ البطاقات ══ */
#etp-ws .ets-ws-card{
  background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.03));
  border:1px solid rgba(255,255,255,.08);border-radius:20px;
  padding:26px 22px;cursor:pointer;position:relative;transition:all .3s ease;
}
#etp-ws .ets-ws-card:hover,#etp-ws .ets-ws-card.active{
  border-color:rgba(0,195,255,.4);
  background:linear-gradient(180deg,rgba(0,195,255,.08),rgba(0,195,255,.03));
  transform:translateY(-5px);box-shadow:0 18px 40px rgba(0,0,0,.2);
}
#etp-ws .ets-ws-icon{
  width:56px;height:56px;border-radius:14px;
  background:rgba(0,195,255,.12);display:flex;align-items:center;
  justify-content:center;font-size:24px;margin-bottom:14px;
}
