  font-size:13px !important;line-height:1.75 !important;
  color:rgba(255,255,255,.7) !important;margin:0 !important;
}
#etp-ws .ets-ws-expand-hint{
  display:block;margin-top:12px;font-size:11px !important;
  font-weight:700 !important;color:#00c3ff !important;opacity:.7;
}
#etp-ws .ets-ws-card.active .ets-ws-expand-hint{opacity:1;}

/* ملخص الخدمة */
#etp-ws .ets-ws-service-summary{
  display:none;margin-top:16px;padding-top:16px;
  border-top:1px solid rgba(0,195,255,.2);animation:etpFadeIn .3s ease;
}
#etp-ws .ets-ws-card.active .ets-ws-service-summary{display:block;}
#etp-ws .ets-ws-service-summary p{
  font-size:13px !important;line-height:1.8 !important;
  color:rgba(255,255,255,.78) !important;margin:0 0 10px !important;
}
#etp-ws .ets-ws-service-list{list-style:none !important;padding:0 !important;margin:0 !important;}
#etp-ws .ets-ws-service-list li{
  font-size:12px !important;color:rgba(255,255,255,.72) !important;
  padding:5px 0 !important;border-bottom:1px solid rgba(255,255,255,.06) !important;
}
#etp-ws .ets-ws-service-list li:last-child{border:none !important;}
@keyframes etpFadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}

/* ══ بطاقات الميزات والخطوات ══ */
#etp-ws .ets-ws-feature,
#etp-ws .ets-ws-step{
  background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));
  border:1px solid rgba(255,255,255,.08);border-radius:18px;
  padding:24px;transition:all .3s;
}
#etp-ws .ets-ws-feature:hover,#etp-ws .ets-ws-step:hover{
  border-color:rgba(0,195,255,.35);transform:translateY(-4px);
}
#etp-ws .ets-ws-feature h3,#etp-ws .ets-ws-step h3{
  font-size:13px !important;font-weight:700 !important;
  color:#fff !important;margin:0 0 8px !important;
}
#etp-ws .ets-ws-feature p,#etp-ws .ets-ws-step p{
  font-size:13px !important;line-height:1.8 !important;
  color:rgba(255,255,255,.7) !important;margin:0 !important;
}
#etp-ws .ets-ws-step-no{
  display:inline-block !important;font-size:26px !important;
  font-weight:800 !important;color:#00c3ff !important;margin-bottom:12px !important;
}

/* ══ قسم الختام ══ */
#etp-ws .ets-ws-trust-close{padding:60px 7% 80px;}
#etp-ws .ets-ws-trust-outer{
  display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:center;
  max-width:1160px;margin:0 auto;padding:64px 52px;border-radius:26px;
  background:linear-gradient(135deg,#071e3d,#0d2f5e,#0b2444);
  border:1px solid rgba(0,195,255,.14);position:relative;overflow:hidden;
}
#etp-ws .ets-ws-trust-outer::before{
  content:"";position:absolute;top:-30%;left:-8%;
  width:450px;height:450px;border-radius:50%;
  background:radial-gradient(circle,rgba(0,195,255,.10),transparent 65%);
  pointer-events:none;
}
#etp-ws .ets-ws-trust-copy{position:relative;z-index:1;}
#etp-ws .ets-ws-trust-headline{
  font-size:clamp(15px,2vw,22px) !important;
  line-height:1.4 !important;font-weight:700 !important;
  color:#fff !important;margin:10px 0 16px !important;
}
#etp-ws .ets-ws-highlight{color:#00c3ff !important;}
#etp-ws .ets-ws-trust-sub{
  font-size:13px !important;line-height:1.85 !important;
  color:rgba(255,255,255,.72) !important;margin:0 0 18px !important;
}
#etp-ws .ets-ws-list{list-style:none !important;padding:0 !important;margin:0 0 24px !important;}
#etp-ws .ets-ws-list li{
  position:relative;padding-right:22px !important;padding-left:0 !important;
  margin-bottom:9px !important;font-size:13px !important;
  line-height:1.75 !important;color:rgba(255,255,255,.8) !important;
}
#etp-ws .ets-ws-list li::before{
  content:"✓";position:absolute;right:0 !important;left:auto !important;
  color:#00c3ff !important;font-weight:700 !important;
}
#etp-ws .ets-ws-trust-proof{position:relative;z-index:1;}
#etp-ws .ets-ws-proof-card{
  background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.10);
  border-radius:20px;padding:26px;backdrop-filter:blur(8px);
}
#etp-ws .ets-ws-proof-header{display:flex;align-items:center;gap:14px;margin-bottom:4px;}
#etp-ws .ets-ws-proof-logo{
  width:42px;height:42px;border-radius:11px;
  background:linear-gradient(135deg,#00c3ff,#1a56db);
  display:flex;align-items:center;justify-content:center;
  font-size:18px !important;font-weight:900 !important;color:#fff !important;flex-shrink:0;
}
#etp-ws .ets-ws-proof-header strong{
  display:block !important;font-size:14px !important;
  color:#fff !important;margin-bottom:3px !important;
}
