#etp-ws .ets-ws-proof-divider{height:1px;background:rgba(255,255,255,.08);margin:16px 0;}
#etp-ws .ets-ws-proof-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:4px;}
#etp-ws .ets-ws-proof-stat{
  text-align:center;padding:13px 8px;
