#etp-ws .ets-ws-proof-markets span{
  font-size:11px !important;color:rgba(255,255,255,.5) !important;
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);
  border-radius:7px;padding:4px 10px;
}

/* ══ الأسئلة الشائعة ══ */
#etp-ws .ets-ws-faq-section{background:#04111f;}
#etp-ws .ets-ws-faq-list{max-width:820px;margin:0 auto;display:flex;flex-direction:column;gap:10px;}
#etp-ws .ets-ws-faq-item{
  background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.03));
  border:1px solid rgba(255,255,255,.08);border-radius:14px;overflow:hidden;
  transition:border-color .25s;
}
#etp-ws .ets-ws-faq-item.open{border-color:rgba(0,195,255,.35);}
#etp-ws .ets-ws-faq-q{
  width:100% !important;display:flex !important;
  justify-content:space-between;align-items:center;
  padding:18px 24px !important;background:none !important;border:none !important;
  cursor:pointer;color:#fff !important;font-size:14px !important;
  font-weight:600 !important;text-align:right !important;
  gap:12px;direction:rtl;
}
#etp-ws .ets-ws-faq-q:hover{color:#00c3ff !important;}
#etp-ws .ets-ws-faq-icon{
  flex-shrink:0;width:28px;height:28px;border-radius:50%;
  border:1px solid rgba(0,195,255,.4);display:flex;align-items:center;
  justify-content:center;font-size:17px !important;color:#00c3ff !important;
  transition:transform .3s;
}
