    document.querySelectorAll('.ets-ws-card').forEach(function(c){c.classList.remove('active');});
    if(!isActive){this.classList.add('active');}
  });
});
// الأسئلة الشائعة
document.querySelectorAll('.ets-ws-faq-q').forEach(function(btn){
