#etp-odoo .capabilities-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 80% 60% at 50% 50%,rgba(0,212,255,.06) 0%,transparent 60%),radial-gradient(ellipse 60% 50% at 100% 0%,rgba(0,255,179,.06) 0%,transparent 50%),radial-gradient(ellipse 50% 60% at 0% 100%,rgba(155,109,255,.08) 0%,transparent 50%),#02060c}
