#etp-odoo .apps-sidebar-label{font-family:'Cairo','Tajawal',sans-serif;font-size:.88rem;font-weight:600}
#etp-odoo .apps-panel{flex:1;min-width:0;background:var(--card);border:1px solid var(--border);border-radius:16px;padding:36px;min-height:480px;box-sizing:border-box;overflow:hidden}
#etp-odoo .apps-panel-header{display:flex;flex-direction:column;align-items:flex-start;gap:6px;margin-bottom:8px;width:100%}
#etp-odoo .apps-panel-top{display:flex;flex-direction:row;align-items:center;gap:14px}
#etp-odoo .apps-panel-icon{width:52px;height:52px;border-radius:14px;background:linear-gradient(135deg,rgba(0,198,255,.2),rgba(123,94,167,.2));display:flex;align-items:center;justify-content:center;font-size:28px;flex-shrink:0}
#etp-odoo .apps-panel-title{font-family:'Cairo','Tajawal',sans-serif;font-size:1.4rem;font-weight:700;color:#eaf0f6}
#etp-odoo .apps-panel-subtitle{color:#6a7a8a;font-size:.9rem;margin-bottom:24px;padding-right:0;text-align:right}
#etp-odoo .apps-panel-divider{height:1px;background:var(--border);margin-bottom:28px}
#etp-odoo .apps-panel-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px}
#etp-odoo .apps-panel-card{background:#02060c;border:1px solid var(--border);border-radius:10px;padding:16px 18px;transition:border-color .2s,transform .2s}
#etp-odoo .apps-panel-card:hover{border-color:rgba(0,198,255,.3);transform:translateY(-2px)}
#etp-odoo .apps-panel-card-name{font-family:'Cairo','Tajawal',sans-serif;font-size:.88rem;font-weight:600;color:#eaf0f6;margin-bottom:6px;display:flex;align-items:center;gap:8px}
#etp-odoo .apps-panel-card-name::before{content:'';width:6px;height:6px;border-radius:50%;background:#00d4ff;flex-shrink:0}
#etp-odoo .apps-panel-card-desc{font-size:.78rem;color:#6a7a8a;line-height:1.5}
#etp-odoo .solutions-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 100% 50% at 50% 0%,rgba(0,212,255,.08) 0%,transparent 55%),radial-gradient(ellipse 60% 70% at 0% 100%,rgba(155,109,255,.1) 0%,transparent 55%),radial-gradient(ellipse 50% 60% at 100% 50%,rgba(0,255,179,.05) 0%,transparent 50%),#0a1219}
#etp-odoo .solutions-section::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,212,255,.4),rgba(155,109,255,.4),transparent);pointer-events:none}
#etp-odoo .solutions-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px;margin-top:60px}
#etp-odoo .solution-card{background:linear-gradient(145deg,rgba(15,22,32,1),rgba(11,16,24,1));border:1px solid var(--border);border-radius:16px;padding:28px 24px;transition:border-color .3s,transform .3s,box-shadow .3s;position:relative;overflow:hidden;text-align:center;cursor:pointer}
#etp-odoo .solution-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,#00d4ff,#9b6dff);opacity:0;transition:opacity .3s}
#etp-odoo .solution-card:hover{border-color:rgba(0,212,255,.3);transform:translateY(-5px);box-shadow:0 24px 60px rgba(0,0,0,.5),0 0 0 1px rgba(0,212,255,.1),inset 0 1px 0 rgba(0,212,255,.15)}
#etp-odoo .solution-card:hover::before{opacity:1}
#etp-odoo .solution-card-img{width:100%;height:130px;margin:0 auto 18px;display:flex;align-items:center;justify-content:center;border-radius:14px;border:1px solid rgba(255,255,255,.06);padding:10px;transition:transform .4s,box-shadow .3s;overflow:hidden;position:relative}
#etp-odoo .sol-icon-main{font-size:56px;line-height:1;filter:drop-shadow(0 4px 16px rgba(0,0,0,.4));transition:transform .4s;position:relative;z-index:1}
#etp-odoo .sol-icon-glow{position:absolute;width:80px;height:80px;border-radius:50%;opacity:.18;transition:opacity .3s}
#etp-odoo .solution-card:hover .solution-card-img{transform:translateY(-3px);border-color:rgba(0,212,255,.2);box-shadow:0 8px 30px rgba(0,0,0,.3)}
#etp-odoo .solution-card:hover .sol-icon-main{transform:scale(1.12)}
#etp-odoo .solution-card:hover .sol-icon-glow{opacity:.28}
#etp-odoo .solution-card h3{font-size:1rem;font-weight:700;margin-bottom:16px;letter-spacing:0em;color:#eaf0f6}
#etp-odoo .solution-card ul{list-style:none;display:flex;flex-direction:column;gap:6px;text-align:right}
#etp-odoo .solution-card ul li{font-size:.82rem;color:#6a7a8a;padding-right:14px;position:relative;transition:color .2s}
#etp-odoo .solution-card ul li::before{content:'←';position:absolute;right:0;color:#00d4ff;font-size:.7rem}
#etp-odoo .solution-card ul li:hover{color:#eaf0f6}
#etp-odoo .solution-detail{display:none;background:#02060c;border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:80px 40px;scroll-margin-top:40px}
#etp-odoo .solution-detail.active{display:block}
#etp-odoo .solution-detail-inner{max-width:1200px;margin:0 auto;display:grid;grid-template-columns:1fr 340px;gap:60px;align-items:start}
#etp-odoo .solution-detail-title{font-size:clamp(1.6rem,3vw,2.4rem);font-weight:700;margin-bottom:16px}
#etp-odoo .solution-detail-desc{color:#6a7a8a;font-size:.95rem;line-height:1.8;margin-bottom:32px}
#etp-odoo .solution-detail-features{display:grid;grid-template-columns:1fr 1fr;gap:10px 24px;list-style:none}
#etp-odoo .solution-detail-features li{font-size:.85rem;color:#6a7a8a;padding-right:16px;position:relative;transition:color .2s}
#etp-odoo .solution-detail-features li::before{content:'›';position:absolute;right:0;color:#00d4ff;font-weight:700}
#etp-odoo .solution-detail-features li:hover{color:#eaf0f6}
#etp-odoo .solution-detail-sidebar{display:flex;flex-direction:column;gap:12px}
#etp-odoo .solution-gain-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:18px 20px;display:flex;align-items:flex-start;gap:14px;transition:border-color .2s}
#etp-odoo .solution-gain-card:hover{border-color:rgba(0,198,255,.25)}
#etp-odoo .solution-gain-icon{width:38px;height:38px;border-radius:10px;background:linear-gradient(135deg,rgba(0,198,255,.15),rgba(123,94,167,.15));display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0}
#etp-odoo .solution-gain-icon svg{width:18px;height:18px}
#etp-odoo .solution-gain-title{font-size:.88rem;font-weight:700;color:#eaf0f6;margin-bottom:3px}
#etp-odoo .solution-gain-sub{font-size:.76rem;color:#6a7a8a}
#etp-odoo .solution-detail-cta{display:block;text-align:center;background:linear-gradient(135deg,#00d4ff,#0080ff);color:#fff;padding:14px 24px;border-radius:10px;font-weight:700;font-size:.88rem;margin-top:4px;transition:opacity .2s,transform .2s;box-shadow:0 0 24px rgba(0,198,255,.2)}
#etp-odoo .solution-detail-cta:hover{opacity:.9;transform:translateY(-2px);color:#fff!important}
#etp-odoo .solution-detail-close{display:inline-flex;align-items:center;gap:6px;margin-top:32px;font-size:.82rem;color:#6a7a8a;cursor:pointer;background:none;border:1px solid var(--border);padding:8px 18px;border-radius:6px;font-family:'Cairo','Tajawal',sans-serif;transition:color .2s,border-color .2s}
#etp-odoo .solution-detail-close:hover{color:#eaf0f6;border-color:rgba(255,255,255,.2)}
#etp-odoo .capabilities-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 80% 60% at 50% 50%,rgba(0,212,255,.06) 0%,transparent 60%),radial-gradient(ellipse 60% 50% at 100% 0%,rgba(0,255,179,.06) 0%,transparent 50%),radial-gradient(ellipse 50% 60% at 0% 100%,rgba(155,109,255,.08) 0%,transparent 50%),#02060c}
#etp-odoo .capabilities-section::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle,rgba(255,255,255,.07) 1px,transparent 1px);background-size:30px 30px;mask-image:radial-gradient(ellipse 100% 100% at 50% 50%,black 10%,transparent 75%);pointer-events:none;opacity:.6}
#etp-odoo .capabilities-section::after{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,255,179,.4),rgba(0,212,255,.4),transparent);pointer-events:none}
#etp-odoo .cap-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px;margin-top:60px}
#etp-odoo .cap-card{background:linear-gradient(145deg,rgba(15,22,32,1),rgba(9,14,20,1));border:1px solid var(--border);border-radius:12px;padding:28px;transition:border-color .3s,background .3s,transform .3s,box-shadow .3s}
#etp-odoo .cap-card:hover{border-color:rgba(0,212,255,.3);background:linear-gradient(145deg,rgba(0,212,255,.05),rgba(9,14,20,1));transform:translateY(-3px);box-shadow:0 16px 48px rgba(0,0,0,.4),0 0 0 1px rgba(0,212,255,.08),inset 0 1px 0 rgba(0,212,255,.12)}
#etp-odoo .cap-card-icon{font-size:24px;margin-bottom:16px;display:flex;align-items:center}
#etp-odoo .cap-card-icon svg{width:28px;height:28px}
#etp-odoo .cap-card h4{font-size:.95rem;font-weight:700;margin-bottom:8px}
#etp-odoo .cap-card p{font-size:.83rem;color:#6a7a8a;line-height:1.6}
#etp-odoo .why-etriplesoft{position:relative;overflow:hidden;background:radial-gradient(ellipse 100% 60% at 50% 0%,rgba(155,109,255,.1) 0%,transparent 60%),radial-gradient(ellipse 60% 50% at 0% 100%,rgba(0,212,255,.08) 0%,transparent 55%),#0a1219;padding:100px 40px;box-sizing:border-box;width:100%}
#etp-odoo .why-etriplesoft::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(155,109,255,.5),rgba(0,212,255,.5),transparent);pointer-events:none}
#etp-odoo .why-et-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start;margin-top:48px;width:100%;box-sizing:border-box}
#etp-odoo .why-et-left{width:100%;box-sizing:border-box;overflow:hidden}
#etp-odoo .why-et-left h3{font-size:clamp(1.4rem,3vw,2.2rem);font-weight:700;margin-bottom:16px}
#etp-odoo .why-et-intro{color:#6a7a8a;font-size:.95rem;line-height:1.8;margin-bottom:32px}
#etp-odoo .why-et-table-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;width:100%;box-sizing:border-box}
#etp-odoo .why-et-table{width:100%;min-width:500px;border-collapse:collapse;font-size:.85rem}
#etp-odoo .why-et-table th{padding:12px 16px;text-align:right;color:#6a7a8a;font-weight:600;font-size:.78rem;letter-spacing:.02em;text-transform:uppercase;border-bottom:1px solid var(--border)}
#etp-odoo .why-et-table td{padding:12px 16px;border-bottom:1px solid var(--border);color:#6a7a8a;vertical-align:middle;text-align:right}
#etp-odoo .why-et-table td:first-child{color:#eaf0f6;font-weight:500}
#etp-odoo .why-et-table tr:last-child td{border-bottom:none}
#etp-odoo .why-et-table tr:hover td{background:rgba(0,212,255,.02)}
#etp-odoo .et-check{color:#00d4ff;font-weight:600}
#etp-odoo .et-cross{color:#ff4d6d}
#etp-odoo .why-et-cards{display:grid;grid-template-columns:1fr 1fr;gap:14px;width:100%;box-sizing:border-box}
#etp-odoo .why-et-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:22px 20px;transition:border-color .3s,transform .3s;box-sizing:border-box;width:100%;overflow:hidden;word-break:break-word}
#etp-odoo .why-et-card:hover{border-color:rgba(0,212,255,.3);transform:translateY(-3px)}
#etp-odoo .why-et-card-icon{font-size:1.6rem;margin-bottom:10px;display:block}
#etp-odoo .why-et-card h5{font-size:.9rem;font-weight:700;color:#eaf0f6;margin-bottom:6px}
#etp-odoo .why-et-card p{font-size:.8rem;color:#6a7a8a;line-height:1.6}
#etp-odoo .integrations-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 80% 60% at 50% 50%,rgba(0,212,255,.06) 0%,transparent 60%),#02060c;padding:100px 40px}
#etp-odoo .integrations-section::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,212,255,.4),transparent);pointer-events:none}
#etp-odoo .integrations-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:48px}
#etp-odoo .int-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:24px 20px;text-align:center;transition:border-color .3s,transform .3s}
#etp-odoo .int-card:hover{border-color:rgba(0,212,255,.3);transform:translateY(-3px)}
#etp-odoo .int-card-icon{font-size:2rem;margin-bottom:12px;display:block}
#etp-odoo .int-card h4{font-size:.9rem;font-weight:700;color:#eaf0f6;margin-bottom:6px}
#etp-odoo .int-card p{font-size:.8rem;color:#6a7a8a;line-height:1.5}
#etp-odoo .tax-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 80% 60% at 50% 0%,rgba(0,212,255,.08) 0%,transparent 55%),radial-gradient(ellipse 60% 50% at 100% 100%,rgba(155,109,255,.08) 0%,transparent 55%),#0a1219;padding:100px 40px}
#etp-odoo .tax-section::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,255,179,.4),rgba(0,212,255,.4),transparent);pointer-events:none}
#etp-odoo .tax-countries{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:48px}
#etp-odoo .tax-country-card{background:var(--card);border:1px solid var(--border);border-radius:16px;overflow:hidden;transition:border-color .3s,transform .3s}
#etp-odoo .tax-country-card:hover{border-color:rgba(0,212,255,.25);transform:translateY(-3px)}
#etp-odoo .tax-country-header{display:flex;align-items:center;gap:14px;padding:22px 22px 18px;border-bottom:1px solid var(--border)}
#etp-odoo .tax-flag{font-size:2rem;flex-shrink:0}
#etp-odoo .tax-country-name{font-size:1.1rem;font-weight:700;color:#eaf0f6;margin-bottom:2px}
#etp-odoo .tax-country-sub{font-size:.75rem;color:#6a7a8a}
#etp-odoo .tax-badge{margin-right:auto;padding:5px 12px;border-radius:100px;background:linear-gradient(135deg,rgba(0,212,255,.15),rgba(155,109,255,.12));border:1px solid rgba(0,212,255,.25);font-size:.75rem;font-weight:700;color:#00d4ff;letter-spacing:.02em;flex-shrink:0}
#etp-odoo .tax-items{padding:8px 0}
#etp-odoo .tax-item{display:flex;gap:12px;align-items:flex-start;padding:16px 22px;border-bottom:1px solid var(--border);transition:background .2s}
#etp-odoo .tax-item:last-child{border-bottom:none}
#etp-odoo .tax-item:hover{background:rgba(0,212,255,.03)}
#etp-odoo .tax-item-icon{font-size:1.2rem;flex-shrink:0;margin-top:2px}
#etp-odoo .tax-item-title{font-size:.88rem;font-weight:700;color:#eaf0f6;margin-bottom:4px}
#etp-odoo .tax-item-desc{font-size:.78rem;color:#6a7a8a;line-height:1.55}
#etp-odoo .tax-authority{display:flex;align-items:center;gap:8px;padding:14px 22px;border-top:1px solid var(--border);font-size:.78rem;color:#6a7a8a;background:rgba(0,212,255,.03)}
#etp-odoo .tax-authority strong{color:#eaf0f6}
#etp-odoo .gov-platforms-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 70% 60% at 50% 50%,rgba(155,109,255,.07) 0%,transparent 60%),#02060c;padding:100px 40px}
#etp-odoo .gov-platforms-section::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(155,109,255,.5),rgba(0,212,255,.5),transparent);pointer-events:none}
#etp-odoo .gov-platforms-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:48px}
#etp-odoo .gov-card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:24px 20px;position:relative;transition:border-color .3s,transform .3s}
#etp-odoo .gov-card:hover{border-color:rgba(0,212,255,.3);transform:translateY(-3px)}
#etp-odoo .gov-card-badge{position:absolute;top:14px;left:14px;padding:3px 10px;border-radius:100px;border:1px solid rgba(0,212,255,.25);background:rgba(0,212,255,.08);font-size:.68rem;font-weight:700;color:#00d4ff;letter-spacing:.02em}
#etp-odoo .gov-card-icon{width:48px;height:48px;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:1.5rem;margin-bottom:14px}
#etp-odoo .gov-card-name{font-size:.95rem;font-weight:700;color:#eaf0f6;margin-bottom:4px}
#etp-odoo .gov-card-name-ar{font-size:.75rem;color:#6a7a8a;margin-bottom:10px}
#etp-odoo .gov-card-desc{font-size:.78rem;color:#6a7a8a;line-height:1.55;margin-bottom:12px}
#etp-odoo .gov-card-url{font-size:.72rem;color:rgba(0,212,255,.6);font-weight:500}
#etp-odoo .gov-odoo-bar{margin-top:32px;display:flex;align-items:flex-start;gap:14px;background:linear-gradient(135deg,rgba(0,212,255,.06),rgba(155,109,255,.06));border:1px solid rgba(0,212,255,.15);border-radius:12px;padding:20px 24px;font-size:.88rem;color:#6a7a8a;line-height:1.6}
#etp-odoo .gov-odoo-bar-icon{font-size:1.3rem;flex-shrink:0;margin-top:2px}
#etp-odoo .gov-odoo-bar strong{color:#eaf0f6}
#etp-odoo .faq-section{position:relative;overflow:hidden;background:radial-gradient(ellipse 80% 80% at 50% 50%,rgba(155,109,255,.09) 0%,transparent 60%),#0a1219;padding:100px 40px}
#etp-odoo .faq-section::after{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(155,109,255,.5),transparent);pointer-events:none}
#etp-odoo .faq-list{margin-top:60px;display:flex;flex-direction:column;gap:2px;max-width:800px}
#etp-odoo .faq-item{border:1px solid var(--border);border-radius:10px;overflow:hidden;transition:border-color .2s}
#etp-odoo .faq-item:hover{border-color:rgba(0,198,255,.2)}
#etp-odoo .faq-q{padding:22px 28px;font-family:'Cairo','Tajawal',sans-serif;font-weight:600;font-size:.95rem;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;background:var(--card);transition:background .2s}
#etp-odoo .faq-q:hover{background:rgba(0,198,255,.04)}
#etp-odoo .faq-q::after{content:'+';font-size:1.3rem;color:#00d4ff;flex-shrink:0;transition:transform .3s}
#etp-odoo .faq-item.open .faq-q::after{transform:rotate(45deg)}
#etp-odoo .faq-a{display:none;padding:0 28px 22px;font-size:.88rem;color:#6a7a8a;line-height:1.7;background:var(--card)}
#etp-odoo .faq-item.open .faq-a{display:block}
#etp-odoo .cta-banner{background:radial-gradient(ellipse 80% 100% at 50% 50%,rgba(0,198,255,.08) 0%,transparent 70%),linear-gradient(135deg,rgba(0,198,255,.06),rgba(123,94,167,.08));border:1px solid rgba(0,198,255,.15);border-radius:20px;padding:64px 48px;text-align:center;max-width:1200px;margin:0 auto 100px;position:relative;overflow:hidden}
#etp-odoo .cta-banner::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle,rgba(255,255,255,.06) 1px,transparent 1px);background-size:28px 28px;mask-image:radial-gradient(ellipse 80% 80% at 50% 50%,black 0%,transparent 100%);pointer-events:none}
#etp-odoo .cta-banner::after{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,198,255,.5),rgba(123,94,167,.5),transparent)}
#etp-odoo .cta-banner h2{font-size:clamp(1.8rem,3vw,2.8rem);font-weight:700;margin-bottom:16px}
#etp-odoo .cta-banner p{color:#6a7a8a;max-width:500px;margin:0 auto 36px}
#etp-odoo .other-services{padding:80px 40px;background:#02060c}
#etp-odoo .other-services-grid{display:flex;gap:12px;flex-wrap:wrap;margin-top:40px}
#etp-odoo .other-service-link{padding:14px 24px;border:1px solid var(--border);border-radius:8px;font-size:.88rem;font-weight:500;color:#6a7a8a;transition:all .2s;display:flex;align-items:center;gap:8px}
#etp-odoo .other-service-link::before{content:'←';color:#00d4ff}
