 background: radial-gradient(circle, rgba(0,196,204,.15) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero .container { position: relative; z-index: 2; padding-top: 80px; padding-bottom: 72px; }
 .breadcrumb {
 font-size: .82rem;
 color: rgba(255,255,255,.5);
 margin-bottom: 28px;
 font-weight: 500;
 display: flex;
 gap: 0.5rem;
 flex-wrap: wrap;
 }
 .breadcrumb a { color: rgba(255,255,255,.6); }
 .breadcrumb a:hover { color: #fff; text-decoration: none; }
 .breadcrumb strong { color: rgba(255,255,255,.8); font-weight: 600; }
 .subtitle {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 background: rgba(0,196,204,.12);
 border: 1px solid rgba(0,196,204,.3);
 border-radius: 100px;
