 max-width: 680px;
 line-height: 1.7;
 margin-bottom: 36px;
 }
 .cta-group { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
 .btn {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 padding: 14px 28px;
 border-radius: 10px;
 font-weight: 700;
 font-size: .92rem;
