 cursor: pointer;
 transition: all .25s;
 text-decoration: none;
 font-family: inherit;
 }
 .btn-primary {
 background: var(--brand-gradient);
 color: #fff;
 box-shadow: 0 4px 16px rgba(27,111,228,.3);
 }
 .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(27,111,228,.4); text-decoration: none; }
 .btn-secondary {
 background: transparent;
 color: #fff;
 border: 1.5px solid rgba(255,255,255,.25);
 }
 .btn-secondary:hover { border-color: rgba(255,255,255,.5); background: rgba(255,255,255,.05); text-decoration: none; }

 /* Hero Stats */
 .stats {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
 gap: 20px;
 max-width: 720px;
 margin: 2.2rem 0;
