 .stat-card strong {
 font-family: 'Inter', sans-serif;
 font-size: 1.8rem;
 font-weight: 800;
 color: #00C4CC;
 display: block;
 line-height: 1.2;
 }
 .stat-card span { font-size: .78rem; color: rgba(255,255,255,.5); font-weight: 500; margin-top: 4px; display: block; letter-spacing: 0.025em; }
 .meta {
