 border-bottom: none;
 }

 /* ----- Main grid (TOC + content) ----- */
 .main-grid { display: grid; grid-template-columns: 200px 1fr; gap: 2.5rem; align-items: start; margin-top: 64px; }
 @media (max-width: 950px) { .main-grid { grid-template-columns: 1fr; } }
 /* TOC */
 .toc {
 position: sticky;
 top: 24px;
 z-index: 100;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 22px 16px;
 margin-bottom: 3rem;
 box-shadow: var(--shadow);
 max-height: calc(100vh - 48px);
 overflow-y: auto;
 margin-left: -32px;
 }
 .toc::-webkit-scrollbar { width: 3px; }
 .toc::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
 .toc h3 {
 font-family: 'Inter', sans-serif;
 font-weight: 800;
 font-size: 1rem;
 margin-bottom: 16px;
 color: #C8DEFF;
 display: flex;
 align-items: center;
 gap: 8px;
 text-transform: none;
 letter-spacing: normal;
 }
 .toc ul { list-style: none; padding-left: 0; }
 .toc li {
 margin-bottom: 0.8rem;
 border-left: 2px solid var(--border);
 padding-left: 1rem;
 transition: 0.2s;
 }
 .toc li:hover { border-left-color: var(--brand-secondary); }
 .toc a { color: var(--text-muted); font-size: 0.9rem; font-weight: 500; letter-spacing: 0.015em; }
 .toc a:hover { color: var(--brand-secondary); text-decoration: none; }

 /* Sections */
 section { margin-bottom: 5rem; scroll-margin-top: 2.5rem; }
 h2 {
 font-size: 2rem;
 margin-bottom: 1.5rem;
 position: relative;
 display: inline-block;
