[{"id":"dacfa27","elType":"container","settings":{"flex_direction":"column","boxed_width":{"unit":"px","size":1600,"sizes":[]}},"elements":[{"id":"fcb8c28","elType":"widget","settings":{"title":"<span style="font-family: Outfit, sans-serif; font-size: 54.4px; letter-spacing: -0.544px; white-space: normal;">Odoo Dashboard &amp; Insights</span>","header_size":"h1","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"blend_mode":"multiply"},"elements":[],"widgetType":"heading"}],"isInner":false},{"id":"b1017ba","elType":"container","settings":{"content_width":"full","boxed_width":{"unit":"px","size":1600,"sizes":[]},"width":{"unit":"%","size":104.302},"_flex_size":"none","_element_width":"initial"},"elements":[{"id":"d1b9615","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="en">
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <link rel="preconnect" href="https://fonts.googleapis.com">
 <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
 <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Outfit:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">

 <style>
 /* ----- Design system: light + blue gradient (matches Etriplesoft blog) ----- */
 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

 :root {
 --bg: #071020;
 --bg-alt: #0A1628;
 --bg-dark: #071020;
 --bg-dark-card: #0F1E35;
 --surface: #0F1E35;
 --surface-alt: #0A1628;
 --border: #1A3050;
 --border-light: #1A3050;
 --text: #E8F0FF;
 --text-secondary: #7A9DC8;
 --text-muted: #4A6FA0;
 --brand-primary: #1B6FE4;
 --brand-secondary: #00C4CC;
 --brand-accent: #00C4CC;
 --brand-light: rgba(27,111,228,.18);
 --brand-gradient: linear-gradient(135deg, #1B6FE4 0%, #00C4CC 100%);
 --green: #22C55E;
 --green-light: rgba(34,197,94,.15);
 --amber: #FB923C;
 --amber-light: rgba(251,146,60,.15);
 --rose: #F87171;
 --rose-light: rgba(248,113,113,.15);
 --purple: #875A7B;
 --purple-light: rgba(135,90,123,.15);
 --teal: #00C4CC;
 --teal-light: rgba(0,196,204,.12);
 --orange: #FB923C;
 --radius: 12px;
 --radius-lg: 18px;
 --radius-sm: 8px;
 --shadow-sm: 0 2px 20px rgba(0,0,0,.40);
 --shadow: 0 4px 28px rgba(0,0,0,.45);
 --shadow-lg: 0 8px 40px rgba(0,0,0,.50);
 --max-w: 820px;
 --max-w-wide: 1160px;
 }

 html { scroll-behavior: smooth; font-size: 16px; -webkit-font-smoothing: antialiased; }
 body { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; background: var(--bg); color: var(--text); line-height: 1.75; letter-spacing: 0.015em; }
 ::selection { background: var(--brand-secondary); color: #fff; }
 strong { color: #E8F0FF; }
 a { color: var(--brand-primary); text-decoration: none; transition: 0.2s; }
 a:hover { color: var(--brand-secondary); text-decoration: underline; }
 h1, h2, h3, h4 { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; font-weight: 700; color: #E8F0FF; line-height: 1.2; }
 h2 { font-size: 2rem; margin-bottom: 1.5rem; letter-spacing: -0.01em; }
 p { color: #7A9DC8; margin-bottom: 1.3rem; letter-spacing: 0.015em; }
 code { font-family: 'JetBrains Mono', monospace; background: #112B4E; padding: 2px 8px; border-radius: 4px; font-size: 0.88em; color: #00C4CC; }

 .container { max-width: var(--max-w-wide); margin: 0 auto; padding: 0 24px; }

 /* ----- Hero (dark) ----- */
 .hero {
 background: linear-gradient(135deg,#071020 0%,#0D2240 45%,#1A3A5C 80%,#1B5FC4 100%);
 color: #fff;
 position: relative;
 overflow: hidden;
 padding: 0;
 margin-bottom: 0;
 border-radius: 0;
 }
 .hero::before {
 content: '';
 position: absolute;
 top: -40%; right: -20%;
 width: 700px; height: 700px;
 background: radial-gradient(circle, rgba(27,111,228,.25) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero::after {
 content: '';
 position: absolute;
 bottom: -30%; left: -10%;
 width: 500px; height: 500px;
 background: radial-gradient(circle, rgba(0,196,204,.15) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero .container { position: relative; z-index: 2; padding-top: 80px; padding-bottom: 72px; }
 .breadcrumb {
 font-size: .82rem;
 color: rgba(255,255,255,.5);
 margin-bottom: 28px;
 font-weight: 500;
 display: flex;
 gap: 0.5rem;
 flex-wrap: wrap;
 }
 .breadcrumb a { color: rgba(255,255,255,.6); }
 .breadcrumb a:hover { color: #fff; text-decoration: none; }
 .breadcrumb strong { color: rgba(255,255,255,.8); font-weight: 600; }
 .subtitle {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 background: rgba(0,196,204,.12);
 border: 1px solid rgba(0,196,204,.3);
 border-radius: 100px;
 padding: 6px 18px 6px 12px;
 font-size: .78rem;
 font-weight: 600;
 color: #00C4CC;
 margin-bottom: 28px;
 letter-spacing: 1.5px;
 text-transform: uppercase;
 }
 h1 {
 font-family: 'Inter', sans-serif;
 font-size: clamp(2.2rem, 5vw, 3.4rem);
 font-weight: 800;
 line-height: 1.15;
 margin-bottom: 20px;
 letter-spacing: -0.01em;
 color: #ffffff;
 }
 .hero-desc {
 font-size: 1.15rem;
 color: #8AAFD8;
 max-width: 680px;
 line-height: 1.7;
 margin-bottom: 36px;
 }
 .cta-group { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
 .btn {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 padding: 14px 28px;
 border-radius: 10px;
 font-weight: 700;
 font-size: .92rem;
 border: none;
 cursor: pointer;
 transition: all .25s;
 text-decoration: none;
 font-family: inherit;
 }
 .btn-primary {
 background: var(--brand-gradient);
 color: #fff;
 box-shadow: 0 4px 16px rgba(27,111,228,.3);
 }
 .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(27,111,228,.4); text-decoration: none; }
 .btn-secondary {
 background: transparent;
 color: #fff;
 border: 1.5px solid rgba(255,255,255,.25);
 }
 .btn-secondary:hover { border-color: rgba(255,255,255,.5); background: rgba(255,255,255,.05); text-decoration: none; }

 /* Hero Stats */
 .stats {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
 gap: 20px;
 max-width: 720px;
 margin: 2.2rem 0;
 }
 .stat-card {
 text-align: center;
 padding: 20px 12px;
 background: rgba(255,255,255,.04);
 border: 1px solid rgba(255,255,255,.08);
 border-radius: var(--radius);
 backdrop-filter: blur(8px);
 }
 .stat-card strong {
 font-family: 'Inter', sans-serif;
 font-size: 1.8rem;
 font-weight: 800;
 color: #00C4CC;
 display: block;
 line-height: 1.2;
 }
 .stat-card span { font-size: .78rem; color: rgba(255,255,255,.5); font-weight: 500; margin-top: 4px; display: block; letter-spacing: 0.025em; }
 .meta {
 display: flex;
 gap: 2rem;
 flex-wrap: wrap;
 color: rgba(255,255,255,.5);
 font-size: 0.9rem;
 margin-bottom: 0;
 padding-bottom: 0;
 border-bottom: none;
 }

 /* ----- Main grid (TOC + content) ----- */
 .main-grid { display: grid; grid-template-columns: 200px 1fr; gap: 2.5rem; align-items: start; margin-top: 64px; }
 @media (max-width: 950px) { .main-grid { grid-template-columns: 1fr; } }
 /* TOC */
 .toc {
 position: sticky;
 top: 24px;
 z-index: 100;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 22px 16px;
 margin-bottom: 3rem;
 box-shadow: var(--shadow);
 max-height: calc(100vh - 48px);
 overflow-y: auto;
 margin-left: -32px;
 }
 .toc::-webkit-scrollbar { width: 3px; }
 .toc::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
 .toc h3 {
 font-family: 'Inter', sans-serif;
 font-weight: 800;
 font-size: 1rem;
 margin-bottom: 16px;
 color: #C8DEFF;
 display: flex;
 align-items: center;
 gap: 8px;
 text-transform: none;
 letter-spacing: normal;
 }
 .toc ul { list-style: none; padding-left: 0; }
 .toc li {
 margin-bottom: 0.8rem;
 border-left: 2px solid var(--border);
 padding-left: 1rem;
 transition: 0.2s;
 }
 .toc li:hover { border-left-color: var(--brand-secondary); }
 .toc a { color: var(--text-muted); font-size: 0.9rem; font-weight: 500; letter-spacing: 0.015em; }
 .toc a:hover { color: var(--brand-secondary); text-decoration: none; }

 /* Sections */
 section { margin-bottom: 5rem; scroll-margin-top: 2.5rem; }
 h2 {
 font-size: 2rem;
 margin-bottom: 1.5rem;
 position: relative;
 display: inline-block;
 letter-spacing: 0.01em;
 color: #E8F0FF;
 }
 h2::after {
 content: '';
 position: absolute;
 bottom: -10px;
 left: 0;
 width: 45px;
 height: 4px;
 background: var(--brand-secondary);
 border-radius: 2px;
 }
 h3 { font-size: 1.5rem; margin: 2.2rem 0 1.2rem; color: #E8F0FF; letter-spacing: 0.012em; }

 /* Card grids */
 .card-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
 gap: 20px;
 margin-top: 1.8rem;
 }
 .card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 28px 24px;
 transition: all .3s;
 box-shadow: var(--shadow-sm);
 }
 .card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .card-icon { font-size: 2rem; margin-bottom: 0.8rem; display: block; }
 .card h3 { margin-top: 0; font-size: 1.2rem; margin-bottom: 0.5rem; color: #E8F0FF; letter-spacing: 0.015em; }

 /* Workflow Phases */
 .workflow { position: relative; }
 .phase {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 1.8rem;
 margin-bottom: 1.2rem;
 border-left: 6px solid var(--brand-secondary);
 box-shadow: var(--shadow-sm);
 }
 .phase-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: 0.8rem;
 flex-wrap: wrap;
 gap: 0.8rem;
 }
 .phase-header strong { font-size: 1.2rem; color: #E8F0FF; font-family: 'Inter', sans-serif; letter-spacing: 0.015em; }
 .phase-num {
 background: rgba(27,111,228,.18);
 color: #00C4CC;
 padding: 0.4rem 1rem;
 border-radius: 40px;
 font-weight: 600;
 font-size: 0.85rem;
 border: 1px solid var(--border);
 letter-spacing: 0.025em;
 }
 .phase p { color: #7A9DC8; }

 /* Modules Bento */
 .bento-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
 gap: 24px;
 }
 .module-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 32px;
 transition: all .3s;
 position: relative;
 overflow: hidden;
 }
 .module-card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .module-card h3 {
 font-family: 'Inter', sans-serif;
 font-size: 1.2rem;
 font-weight: 700;
 margin: 0 0 10px;
 color: #E8F0FF;
 letter-spacing: 0.015em;
 font-size: 1rem;
 display: flex;
 align-items: center;
 gap: 8px;
 flex-wrap: nowrap;
 }
 .module-card ul { margin: 1.2rem 0 0 1.4rem; color: #7A9DC8; }
 .module-card li { margin-bottom: 0.7rem; font-size: 0.92rem; color: #7A9DC8; letter-spacing: 0.015em; }

 /* Charts showcase grid */
 .charts-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
 gap: 14px;
 margin-top: 1.8rem;
 }
 .chart-tile {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 20px 14px;
 text-align: center;
 transition: all .25s;
 box-shadow: var(--shadow-sm);
 }
 .chart-tile:hover {
 border-color: var(--brand-accent);
 transform: translateY(-3px);
 box-shadow: var(--shadow);
 }
 .chart-tile .ico { font-size: 1.8rem; display: block; margin-bottom: 6px; }
 .chart-tile strong { font-size: 0.9rem; color: #E8F0FF; font-family: 'Inter', sans-serif; display: block; letter-spacing: 0.02em; }
 .chart-tile span { font-size: 0.78rem; color: #4A6FA0; display: block; margin-top: 4px; letter-spacing: 0.025em; }

 /* Access layers matrix */
 .matrix-wrap {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 margin-top: 1.8rem;
 box-shadow: var(--shadow-sm);
 overflow-x: auto;
 }
 .layer-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
 gap: 10px;
 }
 .layer-cell {
 padding: 14px 12px;
 border-radius: var(--radius-sm);
 font-weight: 600;
 font-size: 0.88rem;
 border: 1px solid var(--border);
 background: #0A1628;
 color: #E8F0FF;
 display: flex;
 align-items: center;
 gap: 8px;
 letter-spacing: 0.02em;
 font-size: 0.9rem;
 }
 .layer-cell .dot {
 width: 8px; height: 8px; border-radius: 50%; background: #1B6FE4; flex-shrink: 0;
 }
 .layer-cell.accent .dot { background: var(--brand-accent); }
 .layer-cell.green .dot { background: var(--green); }
 .layer-cell.amber .dot { background: var(--amber); }
 .layer-cell.rose .dot { background: var(--rose); }
 .layer-cell.purple .dot { background: var(--purple); }

 /* Pipeline */
 .pipeline {
 display: flex;
 align-items: center;
 gap: 8px;
 flex-wrap: wrap;
 padding: 1.4rem;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 margin: 1.5rem 0;
 }
 .pipe-stage {
 background: var(--surface);
 border: 1px solid var(--border);
 padding: 8px 14px;
 border-radius: 8px;
 font-size: 0.85rem;
 font-weight: 600;
 color: var(--text);
 letter-spacing: 0.02em;
 }
 .pipe-stage.start { border-color: var(--brand-secondary); color: var(--brand-secondary); }
 .pipe-stage.hold { background: rgba(251,146,60,.15); border-color: #FB923C; color: #FB923C; }
 .pipe-stage.done { background: rgba(34,197,94,.15); border-color: #22C55E; color: #22C55E; }
 .pipe-stage.purple { background: rgba(135,90,123,.15); border-color: #C084FC; color: #C084FC; }
 .pipe-arrow { color: var(--text-muted); font-weight: 700; }

 /* Compliance / trust grid */
 .compliance-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .country-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 28px 20px;
 text-align: center;
 transition: all .3s;
 }
 .country-card:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .flag { font-size: 2rem; margin-bottom: 12px; display: block; }
 .country-card h3 { font-size: 1rem; margin: 0 0 8px; color: #E8F0FF; letter-spacing: 0.015em; }
 .country-card p { font-size: 0.85rem; color: #4A6FA0; letter-spacing: 0.015em; }

 /* Testimonials */
 .testimonial-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 gap: 1.8rem;
 margin-top: 2rem;
 }
 .testimonial {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 }
 .testimonial p { font-style: italic; font-size: 1.05rem; color: #7A9DC8; letter-spacing: 0.015em; }
 .testimonial-author { margin-top: 1.2rem; color: var(--brand-secondary); font-weight: 600; letter-spacing: 0.015em; }

 /* Results */
 .results-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .result-item {
 text-align: center;
 padding: 32px 20px;
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 transition: all .3s;
 }
 .result-item:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .result-item strong {
 font-family: 'Inter', sans-serif;
 font-size: 2.4rem;
 font-weight: 900;
 color: #00C4CC;
 display: block;
 margin-bottom: 8px;
 }
 .result-item p { font-weight: 700; color: #E8F0FF; margin-bottom: 6px; letter-spacing: 0.015em; }

 /* FAQ */
 .faq-item {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 margin-bottom: 1rem;
 overflow: hidden;
 transition: all .3s;
 }
 .faq-item:hover { border-color: var(--brand-secondary); background: #0F1E35; }
 .faq-q {
 padding: 20px 24px;
 cursor: pointer;
 font-weight: 700;
 display: flex;
 justify-content: space-between;
 align-items: center;
 color: #C8DEFF;
 font-size: 1rem;
 user-select: none;
 letter-spacing: 0.015em;
 }
 .faq-q::after {
 content: '+';
 font-family: 'Inter', sans-serif;
 font-size: 1.4rem;
 font-weight: 300;
 color: var(--brand-secondary);
 transition: transform .3s;
 }
 .faq-a {
 max-height: 0;
 overflow: hidden;
 transition: max-height .4s ease, padding .3s ease;
 padding: 0 24px;
 color: #7A9DC8;
 letter-spacing: 0.015em;
 }
 .faq-item.active .faq-a {
 max-height: 500px;
 padding-bottom: 20px;
 }
 .faq-item.active .faq-q::after { content: '−'; }

 /* CTA Section */
 .cta-section {
 background: var(--brand-gradient);
 border-radius: var(--radius-lg);
 padding: 48px 40px;
 text-align: center;
 color: #fff;
 margin: 56px 0;
 position: relative;
 overflow: hidden;
 }
 .cta-section::before {
 content: '';
 position: absolute;
 top: -50%; right: -20%;
 width: 400px; height: 400px;
 background: radial-gradient(circle, rgba(255,255,255,.1) 0%, transparent 70%);
 pointer-events: none;
 }
 .cta-section h2 {
 font-family: 'Inter', sans-serif;
 font-size: 1.8rem;
 font-weight: 800;
 margin-bottom: 12px;
 color: #fff;
 }
 .cta-section h2::after { display: none; }
 .cta-section p { color: rgba(255,255,255,.9); margin-bottom: 28px; font-size: 1.1rem; }
 .cta-section .btn {
 background: #fff;
 color: var(--brand-primary);
 font-weight: 700;
 padding: 1.1rem 2.5rem;
 }
 .cta-section .btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.15); }

 /* Case highlight */
 .case-highlight {
 background: var(--surface-alt);
 border-radius: var(--radius);
 padding: 2.2rem;
 border: 1px solid var(--border);
 margin: 2.5rem 0;
 }
 .case-highlight h3 { margin-top: 0; color: var(--brand-secondary); }

 /* RTL badge row */
 .badge-row {
 display: flex;
 flex-wrap: wrap;
 gap: 10px;
 margin-top: 1.4rem;
 }
 .badge-pill {
 display: inline-flex;
 align-items: center;
 gap: 6px;
 background: rgba(27,111,228,.18);
 color: #60A5FA;
 padding: 8px 16px;
 border-radius: 100px;
 font-size: 0.85rem;
 font-weight: 600;
 border: 1px solid rgba(27,111,228,.3);
 letter-spacing: 0.02em;
 }
 .badge-pill.accent { background: rgba(0,196,204,.12); color: #00C4CC; border-color: rgba(0,196,204,.3); }
 .badge-pill.green { background: rgba(34,197,94,.15); color: #22C55E; border-color: rgba(34,197,94,.3); }
 .badge-pill.amber { background: rgba(251,146,60,.15); color: #FB923C; border-color: rgba(251,146,60,.3); }
 .badge-pill.purple { background: rgba(135,90,123,.15); color: #C084FC; border-color: rgba(135,90,123,.3); }

 /* Arabic sample text block */
 .arabic-demo {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 2rem;
 margin-top: 1.8rem;
 direction: rtl;
 text-align: right;
 font-family: 'Plus Jakarta Sans', sans-serif;
 }
 .arabic-demo h4 {
 font-family: 'Inter', sans-serif;
 color: var(--brand-secondary);
 margin-bottom: 0.8rem;
 font-size: 1.1rem;
 }
 .arabic-demo p { margin-bottom: 0.6rem; color: #7A9DC8; font-size: 0.95rem; letter-spacing: 0.015em; }

 footer {
 text-align: center;
 padding: 3rem 0;
 border-top: 1px solid var(--border);
 margin-top: 4rem;
 color: #4A6FA0;
 background: var(--bg);
 }
 footer a { color: var(--brand-secondary); }
 .share-links {
 text-align: center;
 margin-top: 2.5rem;
 color: #4A6FA0;
 font-size: 0.95rem;
 }
 .share-links a { margin: 0 0.5rem; }

 @media (max-width: 600px) {
 .hero .container { padding-top: 48px; padding-bottom: 48px; }
 h1 { font-size: 2rem; }
 .stats { grid-template-columns: 1fr 1fr; }
 .toc { position: relative; top: 0; margin-bottom: 2rem; }
 }
 </style>
</head>
 <div class="hero">
 <div class="container">
 <nav class="breadcrumb" aria-label="Breadcrumb">
 <a href="https://etriplesoft.com/">Home</a> ›
 <a href="https://etriplesoft.com/blog/">Blog</a> ›
 <strong>Odoo Dashboard &amp; Insights Suite</strong>
