.main-hero{position:relative;overflow:hidden;background:radial-gradient(ellipse 160% 80% at 50% -10%,rgba(0,212,255,.15) 0%,transparent 50%),radial-gradient(ellipse 70% 60% at 90% 90%,rgba(155,109,255,.12) 0%,transparent 50%),var(--bg);padding:90px 40px 70px;text-align:center}
.main-hero::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle,rgba(255,255,255,.12) 1px,transparent 1px);background-size:38px 38px;mask-image:radial-gradient(ellipse 90% 80% at 50% 50%,black 0%,transparent 100%);pointer-events:none}
.main-hero::after{content:'';position:absolute;bottom:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(0,212,255,.4),rgba(155,109,255,.4),transparent)}
.main-eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:11px;font-weight:600;letter-spacing:.22em;text-transform:uppercase;color:var(--c1);border:1px solid rgba(0,212,255,.28);padding:6px 18px;border-radius:100px;margin-bottom:24px}
.main-eyebrow .dot{width:6px;height:6px;border-radius:50%;background:var(--c1)}
.main-hero h2.page-title{font-size:clamp(2.2rem,5.5vw,5rem);font-weight:800;letter-spacing:-.03em;line-height:1.06;margin-bottom:12px}
.main-hero h2.page-title em{font-style:normal;background:linear-gradient(135deg,#00d4ff,#9b6dff);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero-meta-desc{max-width:640px;margin:0 auto 28px;color:var(--muted);font-size:1rem;line-height:1.7}
.main-hero-steps{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-bottom:40px}
.mhs-pill{padding:7px 16px;border-radius:100px;font-size:.78rem;font-weight:600;border:1px solid var(--border);color:var(--muted);background:var(--card);transition:all .2s;display:inline-flex;align-items:center;gap:6px}
.mhs-pill:hover,.mhs-pill.active{color:#02060c;border-color:transparent}
.mhs-pill[data-step="1"].active,.mhs-pill[data-step="1"]:hover{background:var(--c1)}
.mhs-pill[data-step="2"].active,.mhs-pill[data-step="2"]:hover{background:var(--c2)}
.mhs-pill[data-step="3"].active,.mhs-pill[data-step="3"]:hover{background:var(--c3)}
.mhs-pill[data-step="4"].active,.mhs-pill[data-step="4"]:hover{background:var(--c4)}
.mhs-pill[data-step="5"].active,.mhs-pill[data-step="5"]:hover{background:linear-gradient(135deg,#00d4ff,#00ffb3)}
.hero-cta-row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
.btn-primary{display:inline-block;background:linear-gradient(135deg,#00d4ff,#0080ff);color:#fff;padding:13px 32px;border-radius:8px;font-weight:700;font-size:.88rem;letter-spacing:.04em;transition:transform .2s,box-shadow .2s;box-shadow:0 0 28px rgba(0,198,255,.2)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 0 44px rgba(0,198,255,.38)}
.btn-ghost{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.15);color:var(--text);padding:13px 32px;border-radius:8px;font-weight:600;font-size:.88rem;transition:all .2s;background:rgba(255,255,255,.04)}
.btn-ghost:hover{border-color:rgba(0,212,255,.4);color:var(--c1)}
.step-tracker{background:var(--card);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100;backdrop-filter:blur(16px)}
.step-tracker-inner{max-width:1300px;margin:0 auto;display:flex;overflow-x:auto}
.st-item{flex:1;min-width:150px;padding:16px 14px;text-align:center;border-right:1px solid var(--border);cursor:pointer;position:relative;transition:background .2s;display:block;color:inherit}
.st-item:last-child{border-right:none}
.st-item:hover{background:rgba(255,255,255,.03)}
.st-item.active{background:rgba(0,212,255,.05)}
.st-item::after{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;transform:scaleX(0);transition:transform .3s}
.st-item[data-step="1"]::after{background:var(--c1)}
.st-item[data-step="2"]::after{background:var(--c2)}
.st-item[data-step="3"]::after{background:var(--c3)}
.st-item[data-step="4"]::after{background:var(--c4)}
.st-item[data-step="5"]::after{background:linear-gradient(90deg,var(--c1),var(--c3))}
.st-item.active::after{transform:scaleX(1)}
.st-num{font-size:.68rem;color:var(--muted);letter-spacing:.1em;margin-bottom:3px}
.st-name{font-size:.76rem;font-weight:600;color:var(--muted);transition:color .2s}
.st-item.active .st-name,.st-item:hover .st-name{color:var(--c1)}
.st-item[data-step="2"].active .st-name{color:var(--c2)}
.st-item[data-step="3"].active .st-name{color:var(--c3)}
.st-item[data-step="4"].active .st-name{color:var(--c4)}
.step-section{padding:0;border-bottom:1px solid var(--border)}
.step-hero{position:relative;overflow:hidden;padding:72px 40px 56px;text-align:center}
.step-hero[data-accent="1"]{background:radial-gradient(ellipse 140% 80% at 50% -10%,rgba(0,212,255,.14) 0%,transparent 55%),var(--bg2)}
.step-hero[data-accent="2"]{background:radial-gradient(ellipse 140% 80% at 50% -10%,rgba(155,109,255,.16) 0%,transparent 55%),var(--bg2)}
.step-hero[data-accent="3"]{background:radial-gradient(ellipse 140% 80% at 50% -10%,rgba(0,255,179,.12) 0%,transparent 55%),var(--bg2)}
.step-hero[data-accent="4"]{background:radial-gradient(ellipse 140% 80% at 50% -10%,rgba(249,199,79,.1) 0%,transparent 55%),var(--bg2)}
.step-hero[data-accent="5"]{background:radial-gradient(ellipse 140% 80% at 50% -10%,rgba(0,212,255,.12) 0%,transparent 40%),radial-gradient(ellipse 80% 60% at 80% 100%,rgba(0,255,179,.1) 0%,transparent 50%),var(--bg2)}
.step-hero::before{content:'';position:absolute;inset:0;background-image:radial-gradient(circle,rgba(255,255,255,.09) 1px,transparent 1px);background-size:36px 36px;mask-image:radial-gradient(ellipse 85% 80% at 50% 50%,black 0%,transparent 100%);pointer-events:none}
.step-badge{display:inline-flex;align-items:center;gap:8px;font-size:10px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;padding:5px 16px;border-radius:100px;margin-bottom:20px}
.step-badge[data-accent="1"]{color:var(--c1);border:1px solid rgba(0,212,255,.3)}
.step-badge[data-accent="2"]{color:var(--c2);border:1px solid rgba(155,109,255,.35)}
.step-badge[data-accent="3"]{color:var(--c3);border:1px solid rgba(0,255,179,.3)}
.step-badge[data-accent="4"]{color:var(--c4);border:1px solid rgba(249,199,79,.3)}
.step-badge[data-accent="5"]{color:var(--c1);border:1px solid rgba(0,212,255,.3)}
.step-badge .dot{width:5px;height:5px;border-radius:50%;background:currentColor}
.step-hero h2{font-size:clamp(1.8rem,4vw,3.4rem);font-weight:800;letter-spacing:-.03em;line-height:1.08;margin-bottom:16px}
.step-hero h2 em{font-style:normal}
.step-hero h2 em[data-accent="1"]{background:linear-gradient(135deg,#00d4ff,#0080ff);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.step-hero h2 em[data-accent="2"]{background:linear-gradient(135deg,#9b6dff,#00d4ff);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.step-hero h2 em[data-accent="3"]{background:linear-gradient(135deg,#00ffb3,#00d4ff);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.step-hero h2 em[data-accent="4"]{background:linear-gradient(135deg,#f9c74f,#ff9f1c);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.step-hero h2 em[data-accent="5"]{background:linear-gradient(135deg,#00d4ff,#00ffb3);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.step-hero-sub{max-width:540px;margin:0 auto 24px;color:var(--muted);font-size:.98rem}
.step-meta{display:flex;align-items:center;justify-content:center;gap:20px;flex-wrap:wrap}
.step-meta-item{display:flex;align-items:center;gap:7px;font-size:.8rem;color:var(--muted);padding:6px 14px;background:var(--card);border:1px solid var(--border);border-radius:100px}
.step-img-wrap{max-width:980px;margin:40px auto 0;border-radius:14px;overflow:hidden;border:1px solid var(--border);position:relative;box-shadow:0 28px 72px rgba(0,0,0,.6)}
.step-img-wrap img{width:100%;display:block;filter:brightness(.82)}
.step-img-overlay{position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(2,6,12,.92) 100%)}
.step-img-caption{position:absolute;bottom:18px;left:22px;font-size:.78rem;color:rgba(255,255,255,.45)}
.content-grid{max-width:1300px;margin:0 auto;padding:72px 40px;display:grid;grid-template-columns:1fr 320px;gap:56px;align-items:start}
.article .intro-box{border-radius:12px;padding:22px 26px;margin-bottom:32px}
.article .intro-box[data-accent="1"]{background:linear-gradient(135deg,rgba(0,212,255,.07),rgba(155,109,255,.05));border:1px solid rgba(0,212,255,.2)}
.article .intro-box[data-accent="2"]{background:linear-gradient(135deg,rgba(155,109,255,.08),rgba(0,212,255,.05));border:1px solid rgba(155,109,255,.22)}
.article .intro-box[data-accent="3"]{background:linear-gradient(135deg,rgba(0,255,179,.07),rgba(0,212,255,.04));border:1px solid rgba(0,255,179,.2)}
.article .intro-box[data-accent="4"]{background:linear-gradient(135deg,rgba(249,199,79,.07),rgba(155,109,255,.04));border:1px solid rgba(249,199,79,.2)}
.article .intro-box[data-accent="5"]{background:linear-gradient(135deg,rgba(0,212,255,.07),rgba(0,255,179,.05));border:1px solid rgba(0,212,255,.2)}
.article .intro-box p{color:var(--text);font-size:.97rem;margin:0;line-height:1.75}
.article h3{font-size:1.12rem;font-weight:700;color:var(--text);margin:36px 0 11px;padding-left:15px;letter-spacing:-.01em;position:relative}
.article h3::before{content:'';position:absolute;left:0;top:3px;bottom:3px;width:3px;border-radius:2px}
.article h3[data-a="1"]::before{background:var(--c1)}
.article h3[data-a="2"]::before{background:var(--c2)}
.article h3[data-a="3"]::before{background:var(--c3)}
.article h3[data-a="4"]::before{background:var(--c4)}
.article h3[data-a="5"]::before{background:linear-gradient(180deg,var(--c1),var(--c3))}
.article p{color:var(--muted);font-size:.93rem;line-height:1.85;margin-bottom:14px}
.article ul{list-style:none;display:flex;flex-direction:column;gap:7px;margin:13px 0 20px}
.article ul li{font-size:.88rem;color:var(--muted);padding-left:18px;position:relative;line-height:1.7}
.article ul li::before{content:'→';position:absolute;left:0;font-size:.72rem;top:5px}
.ul1 li::before{color:var(--c1)}
.ul2 li::before{color:var(--c2)}
.ul3 li::before{color:var(--c3)}
.ul4 li::before{color:var(--c4)}
.ul5 li::before{color:var(--c1)}
.highlight-box{background:var(--card);border:1px solid var(--border);border-radius:11px;padding:20px 24px;margin:26px 0}
.highlight-box[data-a="1"]{border-left:3px solid var(--c2)}
.highlight-box[data-a="2"]{border-left:3px solid var(--c1)}
.highlight-box[data-a="3"]{border-left:3px solid var(--c2)}
.highlight-box[data-a="4"]{border-left:3px solid var(--c1)}
.highlight-box[data-a="5"]{border-left:3px solid var(--c2)}
.highlight-box p{margin:0;font-size:.88rem;color:var(--muted);line-height:1.7}
.ilink{color:var(--c1);font-weight:600;border-bottom:1px solid rgba(0,212,255,.3);transition:border-color .2s}
.ilink:hover{border-color:var(--c1)}
.mini-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:18px 0}
.mini-card{background:var(--card);border:1px solid var(--border);border-radius:9px;padding:16px 18px;transition:border-color .25s,transform .2s}
.mini-card:hover{transform:translateY(-2px)}
.mini-card[data-a="2"]:hover{border-color:rgba(155,109,255,.3)}
.mini-card[data-a="4"]:hover{border-color:rgba(249,199,79,.3)}
.mini-card-icon{font-size:1.3rem;margin-bottom:7px}
.mini-card-title{font-size:.86rem;font-weight:700;color:var(--text);margin-bottom:4px}
.mini-card-desc{font-size:.77rem;color:var(--muted);line-height:1.5}
.phase-list{display:flex;flex-direction:column;gap:2px;margin:18px 0}
.phase-row{display:flex;gap:14px;align-items:flex-start;padding:15px 18px;background:var(--card);border:1px solid var(--border);border-radius:9px;transition:border-color .2s}
.phase-row:hover{border-color:rgba(0,255,179,.25)}
.phase-num{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,rgba(0,255,179,.18),rgba(0,212,255,.12));display:flex;align-items:center;justify-content:center;font-size:.75rem;font-weight:800;color:var(--c3);flex-shrink:0}
.phase-body strong{font-size:.87rem;color:var(--text);display:block;margin-bottom:3px}
.phase-body p{font-size:.79rem;color:var(--muted);line-height:1.5;margin:0}
.support-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:18px 0}
.support-card{background:var(--card);border:1px solid var(--border);border-radius:9px;padding:16px 18px;transition:border-color .2s,transform .2s}
.support-card:hover{border-color:rgba(0,212,255,.28);transform:translateY(-2px)}
.support-card-top{display:flex;align-items:center;gap:8px;margin-bottom:7px}
.support-card-icon{font-size:1.2rem}
.support-card-title{font-size:.86rem;font-weight:700;color:var(--text)}
.support-card-desc{font-size:.77rem;color:var(--muted);line-height:1.5}
.journey-complete{background:linear-gradient(135deg,rgba(0,212,255,.08),rgba(155,109,255,.08));border:1px solid rgba(0,212,255,.2);border-radius:14px;padding:30px;text-align:center;margin-top:32px}
.journey-complete h3{font-size:1.2rem;font-weight:700;margin-bottom:10px;padding:0}
.journey-complete h3::before{display:none}
.journey-complete p{font-size:.88rem;color:var(--muted);margin-bottom:18px;max-width:420px;margin-left:auto;margin-right:auto}
.sc-pills{display:flex;gap:7px;justify-content:center;flex-wrap:wrap;margin-bottom:20px}
.sc-pill{padding:5px 12px;border:1px solid rgba(0,212,255,.2);border-radius:100px;font-size:.72rem;font-weight:600;color:var(--c1);background:rgba(0,212,255,.06)}
.btn-finish{display:inline-block;background:linear-gradient(135deg,#00d4ff,#00ffb3);color:#02060c;padding:12px 28px;border-radius:8px;font-weight:700;font-size:.85rem;transition:transform .2s,box-shadow .2s}
.btn-finish:hover{transform:translateY(-2px);box-shadow:0 0 32px rgba(0,212,255,.3)}
.sidebar{display:flex;flex-direction:column;gap:18px;position:sticky;top:56px}
.s-card{background:var(--card);border:1px solid var(--border);border-radius:13px;padding:22px}
.s-card h4{font-size:.86rem;font-weight:700;margin-bottom:14px;color:var(--text)}
.s-card .si{display:flex;align-items:flex-start;gap:11px;padding:9px 0;border-bottom:1px solid var(--border)}
.s-card .si:last-child{border-bottom:none;padding-bottom:0}
.si-icon{width:30px;height:30px;border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}
.si-icon[data-a="1"]{background:rgba(0,212,255,.1)}
.si-icon[data-a="2"]{background:rgba(155,109,255,.12)}
.si-icon[data-a="3"]{background:rgba(0,255,179,.1)}
.si-icon[data-a="4"]{background:rgba(249,199,79,.1)}
.si-icon[data-a="5"]{background:rgba(0,212,255,.1)}
.si-text{font-size:.79rem;color:var(--muted);line-height:1.45}
.si-text strong{color:var(--text);display:block;margin-bottom:1px;font-size:.82rem}
.cta-s{border-radius:13px;padding:24px;text-align:center}
.cta-s[data-a="1"]{background:linear-gradient(135deg,rgba(0,212,255,.1),rgba(155,109,255,.08));border:1px solid rgba(0,212,255,.25)}
.cta-s[data-a="2"]{background:linear-gradient(135deg,rgba(155,109,255,.12),rgba(0,212,255,.06));border:1px solid rgba(155,109,255,.28)}
.cta-s[data-a="3"]{background:linear-gradient(135deg,rgba(0,255,179,.08),rgba(0,212,255,.07));border:1px solid rgba(0,255,179,.22)}
.cta-s[data-a="4"]{background:linear-gradient(135deg,rgba(249,199,79,.09),rgba(155,109,255,.06));border:1px solid rgba(249,199,79,.22)}
.cta-s[data-a="5"]{background:linear-gradient(135deg,rgba(0,212,255,.1),rgba(0,255,179,.07));border:1px solid rgba(0,212,255,.25)}
.cta-s h4{font-size:.93rem;margin-bottom:8px}
.cta-s p{font-size:.8rem;color:var(--muted);margin-bottom:16px;line-height:1.55}
.btn-cta{display:inline-block;padding:11px 24px;border-radius:7px;font-weight:700;font-size:.82rem;transition:transform .2s}
.btn-cta:hover{transform:translateY(-2px)}
.btn-cta[data-a="1"]{background:linear-gradient(135deg,#00d4ff,#0080ff);color:#fff}
.btn-cta[data-a="2"]{background:linear-gradient(135deg,#9b6dff,#00d4ff);color:#fff}
.btn-cta[data-a="3"]{background:linear-gradient(135deg,#00ffb3,#00d4ff);color:#02060c}
.btn-cta[data-a="4"]{background:linear-gradient(135deg,#f9c74f,#ff9f1c);color:#02060c}
.btn-cta[data-a="5"]{background:linear-gradient(135deg,#00d4ff,#00ffb3);color:#02060c}
.step-nav{background:var(--card);border:1px solid var(--border);border-radius:13px;padding:18px}
.step-nav h4{font-size:.76rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.1em;margin-bottom:12px}
.sn-link{display:flex;align-items:center;gap:9px;padding:9px 10px;border-radius:7px;font-size:.8rem;color:var(--muted);transition:background .2s}
.sn-link:hover{background:rgba(255,255,255,.04);color:var(--text)}
.sn-link.active{font-weight:600}
.sn-link[data-step="1"].active{background:rgba(0,212,255,.08);color:var(--c1)}
.sn-link[data-step="2"].active{background:rgba(155,109,255,.08);color:var(--c2)}
.sn-link[data-step="3"].active{background:rgba(0,255,179,.07);color:var(--c3)}
.sn-link[data-step="4"].active{background:rgba(249,199,79,.06);color:var(--c4)}
.sn-link[data-step="5"].active{background:rgba(0,212,255,.08);color:var(--c1)}
.sn-num{width:20px;height:20px;border-radius:50%;background:rgba(255,255,255,.07);display:flex;align-items:center;justify-content:center;font-size:.65rem;font-weight:800;flex-shrink:0}
.sn-link[data-step="1"].active .sn-num{background:var(--c1);color:#02060c}
.sn-link[data-step="2"].active .sn-num{background:var(--c2);color:#fff}
.sn-link[data-step="3"].active .sn-num{background:var(--c3);color:#02060c}
.sn-link[data-step="4"].active .sn-num{background:var(--c4);color:#02060c}
.sn-link[data-step="5"].active .sn-num{background:var(--c1);color:#02060c}
.sn-link.done .sn-num{background:rgba(0,255,179,.18);color:var(--c3)}
.next-bar{background:var(--bg2);border-top:1px solid var(--border);padding:40px;display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.next-bar .nb-label{font-size:.72rem;color:var(--muted);text-transform:uppercase;letter-spacing:.12em;margin-bottom:5px}
.next-bar .nb-title{font-size:1.1rem;font-weight:700}
.next-bar .nb-desc{font-size:.83rem;color:var(--muted);margin-top:3px;max-width:380px}
.btn-next{display:inline-flex;align-items:center;gap:9px;border-radius:9px;padding:13px 26px;font-weight:700;font-size:.88rem;transition:all .3s;white-space:nowrap}
.btn-next:hover{transform:translateX(4px)}
.btn-next[data-a="1"]{background:linear-gradient(135deg,rgba(0,212,255,.12),rgba(155,109,255,.1));border:1px solid rgba(0,212,255,.3);color:var(--c1)}
.btn-next[data-a="2"]{background:linear-gradient(135deg,rgba(155,109,255,.12),rgba(0,212,255,.08));border:1px solid rgba(155,109,255,.3);color:var(--c2)}
.btn-next[data-a="3"]{background:linear-gradient(135deg,rgba(0,255,179,.1),rgba(0,212,255,.08));border:1px solid rgba(0,255,179,.28);color:var(--c3)}
.btn-next[data-a="4"]{background:linear-gradient(135deg,rgba(249,199,79,.1),rgba(155,109,255,.07));border:1px solid rgba(249,199,79,.28);color:var(--c4)}
.final-cta{background:radial-gradient(ellipse 80% 100% at 50% 50%,rgba(0,212,255,.07) 0%,transparent 70%),var(--bg2);border-top:1px solid var(--border);padding:80px 40px;text-align:center}
.final-cta-inner{max-width:640px;margin:0 auto}
.final-cta h2{font-size:clamp(1.8rem,3.5vw,2.8rem);font-weight:700;letter-spacing:-.02em;margin-bottom:14px}
.final-cta p{color:var(--muted);font-size:.98rem;margin-bottom:28px}
