.re-dashboard{background:#0A1628;border:1px solid #1A3050;padding:24px;font-size:12px}
.dash-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;flex-wrap:wrap;gap:10px}
.dash-title{font-size:14px;font-weight:700;color:#C8DEFF}
.dash-badge{background:rgba(34,197,94,.15);color:var(--green);border-radius:100px;padding:3px 10px;font-size:11px;font-weight:600;display:inline-flex;align-items:center;gap:5px}
.dash-badge::before{content:'';width:5px;height:5px;background:var(--green);border-radius:50%;animation:blink 1.5s infinite}
.kpi-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:10px;margin-bottom:20px}
.kpi-box{background:#0F1E35;border:1px solid #1A3050;border-radius:8px;padding:14px 12px;text-align:center}
.kpi-num{font-size:22px;font-weight:800;color:#fff;line-height:1;margin-bottom:3px}
.kpi-lbl{font-size:10px;color:#4A6FA0;line-height:1.3}
.kpi-badge{display:inline-block;font-size:9px;font-weight:700;padding:2px 7px;border-radius:100px;margin-top:4px}
.kpi-badge.up{background:rgba(34,197,94,.15);color:var(--green)}
.kpi-badge.warn{background:rgba(248,113,113,.15);color:var(--red)}
.re-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:16px}
.re-table th{background:#0A1628;color:#4A6FA0;padding:8px 10px;text-align:left;font-weight:600;border-bottom:1px solid #1A3050}
