<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1.0"/>
<title>Odoo for Real Estate | Property Management ERP – Etriplesoft</title>
<meta name="description" content="Manage properties, leases, sales pipelines, and finances in one platform. Odoo for Real Estate by Etriplesoft is the all-in-one ERP built for property businesses across UAE, Egypt, and Saudi Arabia."/>
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet"/>
<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js"></script>
<style>
:root{
 --bg: #0d1b2a;
 --bg-mid: #0f2233;
 --card: #122840;
 --card-deep: #0f2030;
 --border: #1e3d5c;
 --blue: #0ea5e9;
 --blue-dim: #0284c7;
 --blue-soft: #38bdf8;
 --blue-glow: rgba(14,165,233,0.14);
 --blue-glow2: rgba(14,165,233,0.25);
 --tag-bg: rgba(14,165,233,0.12);
 --tag-border: rgba(14,165,233,0.35);
 --white: #ffffff;
 --w80: rgba(255,255,255,0.80);
 --w55: rgba(255,255,255,0.55);
 --w20: rgba(255,255,255,0.08);
 --font: 'Inter',-apple-system,sans-serif;
 --r: 14px;
 --r-sm: 8px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--font);background:var(--bg);color:var(--white);line-height:1.7;font-size:16px;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}

.container{max-width:1080px;margin:0 auto;padding:0 28px}
.sec{padding:88px 28px}
.sec-bg{background:var(--bg)}
.sec-mid{background:var(--bg-mid)}

.tag{
 display:inline-flex;align-items:center;gap:7px;
 background:var(--tag-bg);border:1px solid var(--tag-border);
 color:var(--blue-soft);font-size:11px;font-weight:600;
 letter-spacing:.1em;text-transform:uppercase;
 padding:5px 14px;border-radius:100px;margin-bottom:18px;
}
.tag-dot{width:5px;height:5px;border-radius:50%;background:var(--blue-soft)}

h2{font-size:clamp(1.75rem,3.5vw,2.5rem);font-weight:800;color:var(--white);line-height:1.2;margin-bottom:18px;letter-spacing:-.02em}
h3{font-size:1.05rem;font-weight:700;color:var(--white);line-height:1.35;margin-bottom:10px;letter-spacing:.01em}
h4{font-size:.93rem;font-weight:600;color:var(--white);margin-bottom:7px;letter-spacing:.02em}
p{color:var(--w80);margin-bottom:14px;line-height:1.75;letter-spacing:.01em}
p:last-child{margin-bottom:0}
.lead{font-size:1.05rem;color:var(--w80);max-width:700px;line-height:1.8;letter-spacing:.01em}
strong{color:var(--white)}

.btn{display:inline-flex;align-items:center;gap:8px;padding:13px 28px;border-radius:var(--r-sm);font-size:.95rem;font-weight:600;cursor:pointer;transition:all .22s;border:none}
.btn-blue{background:var(--blue);color:#fff;box-shadow:0 4px 20px rgba(14,165,233,.35)}
.btn-blue:hover{background:var(--blue-soft);transform:translateY(-2px);box-shadow:0 8px 28px rgba(14,165,233,.45)}
.btn-ghost{background:transparent;color:var(--white);border:1.5px solid var(--border)}
.btn-ghost:hover{border-color:var(--blue);color:var(--blue-soft)}

/* ══════════════════════════════════════
 HERO
══════════════════════════════════════ */
.hero{
 background:linear-gradient(160deg,#07121e 0%,#0d1b2a 55%,#0f2233 100%);
 padding:92px 28px 0;text-align:center;
 position:relative;overflow:hidden;
}
.hero::before{
 content:'';position:absolute;inset:0;
 background:radial-gradient(ellipse 65% 55% at 50% 0%,rgba(14,165,233,.18) 0%,transparent 68%);
 pointer-events:none;
}
.hero-desc{
 font-size:clamp(1rem,2vw,1.15rem);
 color:var(--w55);max-width:640px;margin:0 auto 36px;line-height:1.85;
}
.hero-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-bottom:60px}

/* ── NEW Dashboard Shell ── */
.dash-wrap{
 max-width:1020px;margin:0 auto;
 background:#F4F3F0;border-radius:14px 14px 0 0;overflow:hidden;
 box-shadow:0 -6px 60px rgba(14,165,233,.12);
 border:1px solid rgba(255,255,255,0.07);
 border-bottom:none;
}
/* window chrome bar */
.dash-bar{
 background:#fff;padding:10px 16px;
 display:flex;align-items:center;gap:8px;
 border-bottom:0.5px solid #dddcd4;
}
.dot{width:10px;height:10px;border-radius:50%}
.dot-r{background:#ff5f57}.dot-y{background:#febc2e}.dot-g{background:#28c840}
.dash-bar-label{margin-left:8px;font-size:.77rem;color:#888780;flex:1;text-align:center;font-family:var(--font)}

/* inner odoo dashboard */
.db-inner{
 background:#F4F3F0;
 padding:16px;
 font-family:'Segoe UI',system-ui,-apple-system,sans-serif;
 color:#1a1a18;
}

/* odoo topbar */
.odb-topbar{
 display:flex;align-items:center;justify-content:space-between;
 margin-bottom:14px;padding-bottom:12px;
 border-bottom:0.5px solid #dddcd4;
 background:#fff;padding:10px 14px;
 border-radius:8px;
 margin-bottom:12px;
}
.odb-left{display:flex;align-items:center;gap:8px}
.odoo-badge{
 background:#714B67;color:#fff;
 font-size:10px;font-weight:600;padding:3px 10px;
 border-radius:5px;letter-spacing:.05em;
}
.odb-title{font-size:14px;font-weight:500;color:#1a1a18}
.odb-meta{font-size:11px;color:#888780}
.odb-right{display:flex;align-items:center;gap:6px}
.otab{
 font-size:11px;padding:4px 12px;border-radius:5px;
 border:0.5px solid #dddcd4;cursor:pointer;
 color:#5F5E5A;background:transparent;transition:all .15s;
}
.otab:hover{background:#F4F3F0}
.otab.active{background:#714B67;color:#fff;border-color:#714B67}

/* kpi grid */
.odb-kpi{
 display:grid;grid-template-columns:repeat(6,1fr);
 gap:8px;margin-bottom:10px;
}
.okpi{
 background:#fff;border:0.5px solid #dddcd4;border-radius:8px;
 padding:11px 13px;position:relative;overflow:hidden;
}
.okpi-accent{position:absolute;left:0;top:0;bottom:0;width:3px}
.okpi-label{font-size:9px;color:#888780;text-transform:uppercase;letter-spacing:.07em;margin-bottom:4px}
.okpi-val{font-size:20px;font-weight:500;color:#1a1a18;line-height:1.1}
.okpi-sub{font-size:10px;margin-top:4px}
.kup{color:#3B6D11}.kdn{color:#A32D2D}.knu{color:#888780}

/* mid grid */
.odb-mid{display:grid;grid-template-columns:2fr 1fr;gap:8px;margin-bottom:10px}
.opanel{background:#fff;border:0.5px solid #dddcd4;border-radius:8px;padding:13px 15px}
.opanel-title{font-size:10px;font-weight:500;color:#888780;text-transform:uppercase;letter-spacing:.07em;margin-bottom:10px}

/* chart legend */
.ochart-legend{display:flex;gap:12px;margin-bottom:8px}
.olegend-item{display:flex;align-items:center;gap:4px;font-size:10px;color:#888780}
.olegend-sw{width:9px;height:9px;border-radius:2px}

/* donut */
.odonut-wrap{display:flex;align-items:center;gap:12px}
.odonut-legend{display:flex;flex-direction:column;gap:6px;flex:1}
.odonut-row{display:flex;align-items:center;font-size:11px}
.odonut-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}
.odonut-name{color:#5F5E5A;margin-left:5px;flex:1}
.odonut-pct{font-weight:500;color:#1a1a18}

/* pipeline */
.opipeline{display:flex;gap:5px;align-items:flex-end;height:68px;margin-top:4px}
.ostage-wrap{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px}
.ostage-bar{width:100%;border-radius:3px 3px 0 0}
.ostage-lbl{font-size:9px;color:#888780;text-align:center}
.ostage-cnt{font-size:10px;font-weight:500;color:#1a1a18}

/* bottom grid */
.odb-bottom{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}

/* listings */
.olisting-rows{display:flex;flex-direction:column;gap:8px}
.olisting-row{display:flex;align-items:center;gap:8px}
.olisting-icon{width:28px;height:28px;border-radius:6px;display:flex;align-items:center;justify-content:center;font-size:13px;flex-shrink:0}
.olisting-meta{flex:1}
.olisting-name{font-size:11px;font-weight:500;color:#1a1a18}
.olisting-loc{font-size:10px;color:#888780}
.obadge{font-size:9px;padding:2px 7px;border-radius:20px;font-weight:500;white-space:nowrap}
.ob-av{background:#EAF3DE;color:#3B6D11}
.ob-rt{background:#E6F1FB;color:#185FA5}
.ob-sl{background:#EEEDFE;color:#534AB7}
.ob-mn{background:#FAEEDA;color:#854F0B}

/* agents */
.oagent-rows{display:flex;flex-direction:column;gap:8px}
.oagent-hdr{display:flex;font-size:9px;color:#888780;border-bottom:0.5px solid #dddcd4;padding-bottom:5px;margin-bottom:2px}
.oagent-row{display:flex;align-items:center;gap:8px}
.oagent-av{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:500;flex-shrink:0}
.oagent-name{font-size:11px;font-weight:500;color:#1a1a18;flex:1}
.oagent-deals{font-size:10px;color:#888780;width:44px;text-align:right;margin-right:6px}
.oprog-wrap{width:52px;height:4px;background:#F4F3F0;border-radius:3px;overflow:hidden}
.oprog-fill{height:100%;border-radius:3px}

/* contracts */
.ocontract-rows{display:flex;flex-direction:column;gap:6px}
.ocontract-row{display:flex;align-items:center;gap:8px;padding:7px 8px;background:#F9F8F5;border-radius:6px}
.ocontract-dot{width:7px;height:7px;border-radius:50%;flex-shrink:0}
.ocontract-name{font-size:11px;color:#1a1a18;flex:1}
.ocontract-date{font-size:10px;color:#888780;display:block}
.ocontract-amt{font-size:11px;font-weight:500;color:#1a1a18}

/* stats strip */
.strip{
 background:var(--bg-mid);
 border-top:1px solid var(--border);border-bottom:1px solid var(--border);
 padding:38px 28px;
}
.strip-grid{
 max-width:960px;margin:0 auto;
 display:grid;grid-template-columns:repeat(4,1fr);text-align:center;
}
.sg{padding:0 20px;border-right:1px solid var(--border)}
.sg:last-child{border-right:none}
.sg-num{font-size:2.3rem;font-weight:800;color:var(--blue-soft);line-height:1;margin-bottom:5px}
.sg-lbl{font-size:.8rem;color:var(--w55);text-transform:uppercase;letter-spacing:.06em}

/* overview */
.ov-grid{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:start}
.mini-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.mini{background:var(--card);border:1px solid var(--border);border-radius:var(--r-sm);padding:18px;transition:border-color .2s,transform .2s}
.mini:hover{border-color:var(--blue);transform:translateY(-2px)}
.mini .ic{font-size:1.55rem;margin-bottom:8px}
.mini h4{font-size:.86rem;margin-bottom:3px;letter-spacing:.04em;text-transform:uppercase;color:var(--blue-soft)}
.mini p{font-size:.81rem;color:var(--w55);margin:0;line-height:1.5;letter-spacing:.01em}
.cta-row{margin-top:26px;display:flex;gap:14px;flex-wrap:wrap;align-items:center}

/* problem cards */
.p-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:40px}
.p-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:26px 22px;position:relative;overflow:hidden;transition:border-color .22s,transform .22s}
.p-card::after{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,var(--blue-dim),var(--blue-soft));transform:scaleX(0);transform-origin:left;transition:transform .3s}
.p-card:hover{border-color:var(--blue);transform:translateY(-3px)}
.p-card:hover::after{transform:scaleX(1)}
.p-ic{font-size:2rem;margin-bottom:14px}
.p-card h3{font-size:.98rem;margin-bottom:8px;letter-spacing:.02em}
.p-card p{font-size:.87rem;color:var(--w55);margin:0;line-height:1.6;letter-spacing:.01em}

/* module cards */
.m-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:40px}
.m-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:26px 22px;transition:border-color .22s,transform .22s}
.m-card:hover{border-color:var(--blue);transform:translateY(-3px)}
.m-ic{width:42px;height:42px;border-radius:10px;background:var(--blue-glow);border:1px solid var(--tag-border);display:flex;align-items:center;justify-content:center;font-size:1.3rem;margin-bottom:16px}
.m-card h3{font-size:.98rem;margin-bottom:12px;letter-spacing:.02em}
.m-card ul{list-style:none;padding:0;display:flex;flex-direction:column;gap:7px}
.m-card li{font-size:.84rem;color:var(--w55);display:flex;align-items:flex-start;gap:8px;line-height:1.5;letter-spacing:.01em}
.m-card li::before{content:'›';color:var(--blue-soft);font-size:1rem;line-height:1.4;flex-shrink:0}

/* visual cards */
.v-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:40px}
.v-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r);overflow:hidden}
.img-real{position:relative;overflow:hidden;aspect-ratio:16/9;border-bottom:1px solid var(--border);background:var(--card-deep)}
.img-real-wide{aspect-ratio:21/7}
.img-real img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s ease;filter:brightness(.85) saturate(.9)}
.v-card:hover .img-real img,.v-wide:hover .img-real img{transform:scale(1.04);filter:brightness(.95) saturate(1)}
.v-body{padding:20px 22px}
.v-body h4{font-size:.93rem;margin-bottom:5px;letter-spacing:.02em}
.v-body p{font-size:.83rem;color:var(--w55);margin:0;line-height:1.55;letter-spacing:.01em}
.vtag{display:inline-block;margin-top:12px;font-size:.71rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--blue-soft);background:var(--tag-bg);border:1px solid var(--tag-border);padding:3px 10px;border-radius:100px}
.v-wide{grid-column:1/-1;background:var(--card);border:1px solid var(--border);border-radius:var(--r);overflow:hidden}

/* results */
.r-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:40px}
.r-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:32px 20px;text-align:center;transition:border-color .22s,transform .22s}
.r-card:hover{border-color:var(--blue);transform:translateY(-3px)}
.r-num{font-size:2.6rem;font-weight:800;color:var(--blue-soft);line-height:1;margin-bottom:10px}
.r-card h3{font-size:.88rem;margin-bottom:8px;letter-spacing:.03em;text-transform:uppercase}
.r-card p{font-size:.81rem;color:var(--w55);margin:0;line-height:1.55;letter-spacing:.01em}

/* steps */
.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:0;margin-top:50px;position:relative}
.steps::before{content:'';position:absolute;top:37px;left:10%;right:10%;height:2px;background:linear-gradient(90deg,var(--blue-dim),var(--blue-soft));z-index:0}
.step{display:flex;flex-direction:column;align-items:center;text-align:center;position:relative;z-index:1;padding:0 8px}
.step-bubble{width:74px;height:74px;border-radius:50%;background:var(--card);border:2px solid var(--blue);display:flex;align-items:center;justify-content:center;flex-direction:column;margin-bottom:16px;box-shadow:0 0 20px rgba(14,165,233,.25)}
.step-n{font-size:.68rem;font-weight:700;color:var(--blue-soft);letter-spacing:.1em}
.step-ic{font-size:1.4rem}
.step h3{font-size:.88rem;margin-bottom:5px;letter-spacing:.02em}
.step p{font-size:.79rem;color:var(--w55);line-height:1.5;letter-spacing:.01em}

/* who is it for */
.types{display:flex;flex-wrap:wrap;gap:10px;margin-top:34px}
.tpill{background:var(--card);border:1px solid var(--border);border-radius:100px;padding:9px 20px;font-size:.88rem;font-weight:500;color:var(--w80);transition:border-color .2s,color .2s,background .2s;cursor:default}
.tpill:hover{border-color:var(--blue);color:var(--blue-soft);background:var(--blue-glow)}

/* why etriplesoft */
.w-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:40px}
.w-card{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:28px 22px;transition:border-color .22s,transform .22s}
.w-card:hover{border-color:var(--blue);transform:translateY(-3px)}
.w-num{font-size:2.8rem;font-weight:800;color:var(--blue);line-height:1;margin-bottom:12px}
.w-card h3{font-size:.93rem;margin-bottom:8px;letter-spacing:.02em}
.w-card p{font-size:.84rem;color:var(--w55);margin:0;line-height:1.6;letter-spacing:.01em}
.rel-box{background:var(--card);border:1px solid var(--border);border-radius:var(--r);padding:28px 30px;margin-top:40px}
.rel-box h3{margin-bottom:5px}
.rel-box > p{font-size:.87rem;color:var(--w55);margin-bottom:16px}
.links-row{display:flex;flex-wrap:wrap;gap:10px}
.lpill{display:inline-flex;align-items:center;gap:7px;background:var(--w20);border:1px solid var(--border);color:var(--w80);padding:8px 18px;border-radius:100px;font-size:.84rem;font-weight:500;transition:all .2s}
.lpill:hover{background:var(--blue-glow);border-color:var(--blue);color:var(--blue-soft)}

/* faq */
.faq-list{margin-top:40px;display:flex;flex-direction:column;gap:11px}
.faq-item{background:var(--card);border:1px solid var(--border);border-radius:var(--r);overflow:hidden;transition:border-color .2s}
.faq-item:hover{border-color:var(--blue)}
.faq-q{padding:19px 26px;font-size:.96rem;font-weight:600;color:var(--white);cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:16px;user-select:none}
.faq-ic{width:26px;height:26px;flex-shrink:0;border-radius:50%;background:var(--blue-glow);border:1px solid var(--tag-border);display:flex;align-items:center;justify-content:center;font-size:.9rem;color:var(--blue-soft);transition:transform .25s}
.faq-item.open .faq-ic{transform:rotate(45deg)}
.faq-a{display:none;padding:0 26px 20px;font-size:.89rem;color:var(--w55);line-height:1.75}
.faq-item.open .faq-a{display:block}

/* cta */
.cta{background:linear-gradient(160deg,#07121e 0%,#0d1b2a 60%,#0f2233 100%);border-top:1px solid var(--border);text-align:center;padding:96px 28px;position:relative;overflow:hidden}
.cta::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse 55% 65% at 50% 50%,rgba(14,165,233,.16) 0%,transparent 68%);pointer-events:none}
.cta h2{font-size:clamp(1.8rem,3.5vw,2.8rem);max-width:700px;margin:0 auto 16px;position:relative}
.cta > p{max-width:520px;margin:0 auto 36px;font-size:1.05rem;color:var(--w55);position:relative}
.cta-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;position:relative}
.btn-cta{display:inline-flex;align-items:center;gap:10px;background:var(--blue);color:#fff;padding:16px 38px;border-radius:var(--r-sm);font-size:1.05rem;font-weight:700;box-shadow:0 6px 28px rgba(14,165,233,.4);transition:all .22s}
.btn-cta:hover{background:var(--blue-soft);transform:translateY(-2px);box-shadow:0 10px 36px rgba(14,165,233,.5)}

.sec-head{text-align:center;max-width:660px;margin:0 auto}

@media(max-width:900px){
 .ov-grid,.v-grid,.r-grid,.w-grid{grid-template-columns:1fr 1fr}
 .m-grid,.p-grid{grid-template-columns:1fr 1fr}
 .steps{grid-template-columns:1fr 1fr;gap:22px}
 .steps::before{display:none}
 .strip-grid{grid-template-columns:repeat(2,1fr);gap:20px}
 .sg{border-right:none;border-bottom:1px solid var(--border);padding-bottom:20px}
 .sg:last-child{border-bottom:none}
 .odb-kpi{grid-template-columns:repeat(3,1fr)}
 .odb-mid{grid-template-columns:1fr}
 .odb-bottom{grid-template-columns:1fr}
}
@media(max-width:600px){
 .sec{padding:60px 18px}
 .ov-grid,.v-grid,.r-grid,.w-grid,.m-grid,.p-grid{grid-template-columns:1fr}
 .mini-grid{grid-template-columns:1fr 1fr}
 .img-real-wide{aspect-ratio:16/9}
 h2{font-size:1.65rem}
 .odb-kpi{grid-template-columns:repeat(2,1fr)}
}
</style>
