 --border: #1A3050;
 --border-light: #1A3050;
 --text: #E8F0FF;
 --text-secondary: #7A9DC8;
 --text-muted: #4A6FA0;
 --brand-primary: #1B6FE4;
 --brand-secondary: #00C4CC;
 --brand-accent: #00C4CC;
 --brand-light: rgba(27,111,228,.18);
 --brand-gradient: linear-gradient(135deg, #1B6FE4 0%, #00C4CC 100%);
 --green: #22C55E;
 --green-light: rgba(34,197,94,.15);
 --amber: #FB923C;
 --amber-light: rgba(251,146,60,.15);
 --rose: #F87171;
 --rose-light: rgba(248,113,113,.15);
 --purple: #875A7B;
