 html { scroll-behavior: smooth; font-size: 16px; -webkit-font-smoothing: antialiased; }
 body { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; background: var(--bg); color: var(--text); line-height: 1.75; letter-spacing: 0.013em; }
 ::selection { background: var(--brand-secondary); color: #fff; }
 strong { color: #E8F0FF; }
 a { color: var(--brand-primary); text-decoration: none; transition: 0.2s; }
 a:hover { color: var(--brand-secondary); text-decoration: underline; }
 h1, h2, h3, h4 { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; font-weight: 700; color: #E8F0FF; line-height: 1.2; }
 h2 { font-size: 2rem; margin-bottom: 1.5rem; letter-spacing: 0.03em; }
 p { color: #7A9DC8; margin-bottom: 1.3rem; letter-spacing: 0.025em; word-spacing: 0.02em; }

 .container { max-width: var(--max-w-wide); margin: 0 auto; padding: 0 24px; }

 .hero {
