 .hero h2.hero-title { font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 800; line-height: 1.15; margin-bottom: 20px; letter-spacing: 0.01em; color: #ffffff; }
 @media (max-width: 950px) { .toc { position: relative; top: 0; max-height: none; overflow-y: visible; margin-bottom: 2rem; z-index: auto; } }
 @media (max-width: 600px) { .hero .container { padding-top: 48px; padding-bottom: 48px; } h1 { font-size: 2rem; } .stats { grid-template-columns: 1fr 1fr; } }

 /* ============================================================
 EMBEDDED MOCKUP STYLES
 ============================================================ */
 .mockup-frame { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-lg); background: #f5f6f8; margin: 2rem 0 1rem; }
 .mockup-caption { font-size: 0.82rem; color: var(--text-muted); margin-top: 0.6rem; font-style: italic; text-align: center; letter-spacing: 0.04em; }
 .browser-bar { background: #e8e9ed; padding: 8px 12px; display: flex; align-items: center; gap: 10px; border-bottom: 1px solid #dfdfe3; }
 .browser-dots { display: flex; gap: 5px; }
 .browser-dots span { width: 10px; height: 10px; border-radius: 50%; display: block; }
 .browser-dots span:nth-child(1) { background: #ff5f57; }
 .browser-dots span:nth-child(2) { background: #febc2e; }
 .browser-dots span:nth-child(3) { background: #28c840; }
 .browser-url { flex: 1; background: #fff; border-radius: 5px; padding: 4px 10px; font-size: 0.7rem; color: #6c757d; font-family: 'JetBrains Mono', monospace; border: 1px solid #d0d1d5; letter-spacing: 0.04em; }

 .odoo-nav { background: #714b67; color: #fff; padding: 0 14px; display: flex; align-items: center; height: 40px; font-size: 12px; letter-spacing: 0.04em; }
 .odoo-apps-icon { display: flex; align-items: center; gap: 6px; padding: 0 12px; height: 100%; font-weight: 500; letter-spacing: 0.04em; border-right: 1px solid rgba(255,255,255,.08); }
 .odoo-apps-icon svg { width: 14px; height: 14px; fill: #fff; }
 .odoo-breadcrumb { display: flex; align-items: center; gap: 8px; padding: 0 14px; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-breadcrumb .active { font-weight: 600; }
 .odoo-breadcrumb .sep { color: rgba(255,255,255,.4); }
 .odoo-nav-right { margin-left: auto; display: flex; align-items: center; gap: 14px; }
 .odoo-nav-right .icon { opacity: 0.85; font-size: 13px; }
 .odoo-avatar { width: 26px; height: 26px; border-radius: 50%; background: linear-gradient(135deg, #a78bfa, #7c3aed); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 10px; letter-spacing: 0.04em; }

 .odoo-submenu { background: #fff; border-bottom: 1px solid #dfdfe3; padding: 0 16px; display: flex; align-items: center; gap: 2px; height: 36px; font-size: 12px; overflow-x: auto; white-space: nowrap; letter-spacing: 0.04em; }
 .odoo-submenu-item { padding: 7px 12px; color: #212529; border-bottom: 2px solid transparent; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-submenu-item.active { color: #714b67; border-bottom-color: #714b67; font-weight: 600; }
 .odoo-submenu-item:hover { background: #f9f9fb; }

 .odoo-body { background: #f5f6f8; }
 .odoo-control-panel { background: #fff; border-bottom: 1px solid #dfdfe3; padding: 8px 16px; display: flex; align-items: center; gap: 10px; font-size: 12px; flex-wrap: wrap; letter-spacing: 0.04em; }
 .odoo-btn { background: #714b67; color: #fff !important; border: none; padding: 5px 12px; border-radius: 4px; font-size: 12px; font-weight: 500; cursor: pointer; font-family: inherit; text-decoration: none !important; display: inline-block; letter-spacing: 0.04em; }
 .odoo-btn-secondary { background: #fff; color: #212529 !important; border: 1px solid #c5c5cc; }
 .odoo-record-count { color: #6c757d; font-size: 11px; margin-left: auto; letter-spacing: 0.04em; }
 .odoo-search { flex: 1; min-width: 150px; max-width: 340px; background: #fff; border: 1px solid #dfdfe3; border-radius: 4px; padding: 5px 10px; display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: #6c757d; letter-spacing: 0.04em; }
 .odoo-filter-tag { background: #e5f5f6; color: #017e84; padding: 2px 7px; border-radius: 3px; font-size: 10px; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-view-switcher { display: flex; gap: 2px; background: #f0f0f3; border-radius: 4px; padding: 2px; }
 .odoo-view-btn { padding: 3px 8px; font-size: 11px; color: #6c757d; border-radius: 3px; letter-spacing: 0.04em; }
 .odoo-view-btn.active { background: #fff; color: #714b67; box-shadow: 0 1px 2px rgba(0,0,0,.1); font-weight: 600; }

 .kanban-wrap { padding: 14px; display: flex; gap: 10px; overflow-x: auto; min-height: 400px; background: #f5f6f8; }
 .kanban-column { min-width: 220px; max-width: 220px; display: flex; flex-direction: column; }
 .kanban-col-header { padding: 6px 8px 8px; font-size: 11px; font-weight: 600; color: #212529; text-transform: uppercase; letter-spacing: 0.04em; display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #714b67; margin-bottom: 8px; }
 .kanban-col-header .count { background: #714b67; color: #fff; padding: 1px 7px; border-radius: 10px; font-size: 9px; font-weight: 700; letter-spacing: 0.04em; }
 .kanban-card { background: #fff; border: 1px solid #dfdfe3; border-radius: 4px; padding: 8px 10px; margin-bottom: 6px; font-size: 11px; border-left: 3px solid transparent; letter-spacing: 0.04em; }
 .kanban-card.critical { border-left-color: #dc3545; }
 .kanban-card.high { border-left-color: #fd7e14; }
 .kanban-card.medium { border-left-color: #e8a33d; }
 .kanban-card.low { border-left-color: #28a745; }
 .kanban-card.breached { background: #fff5f5; border-color: #dc3545; border-left-width: 4px; }
 .kanban-card .ref { font-family: 'JetBrains Mono', monospace; font-size: 9.5px; color: #017e84; font-weight: 600; letter-spacing: 0.04em; }
 .kanban-card .title { font-weight: 600; color: #212529; letter-spacing: 0.04em; word-spacing: 0.03em; margin: 3px 0 6px; line-height: 1.3; }
 .kanban-card .meta { display: flex; justify-content: space-between; align-items: center; margin-top: 6px; padding-top: 6px; border-top: 1px solid var(--border-light); }
 .kanban-card .stars { color: #f39c12; letter-spacing: -1px; font-size: 10.5px; }
 .kanban-card .assignee { width: 20px; height: 20px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 8px; color: #fff; font-weight: 700; }
 .kanban-card .badge { padding: 1px 5px; border-radius: 3px; font-size: 8.5px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; }
 .badge-inc { background: #fee2e2; color: #F87171; }
 .badge-sr { background: #dbeafe; color: #1e40af; }
 .badge-sla-ok { background: #d1fae5; color: #22C55E; letter-spacing: 0.04em; }
 .badge-sla-risk { background: #fef3c7; color: #FB923C; letter-spacing: 0.04em; }
 .badge-sla-breach { background: #fee2e2; color: #F87171; letter-spacing: 0.04em; }
 .badge-sla-met { background: #d1fae5; color: #22C55E; letter-spacing: 0.04em; }

 .av-1 { background: #8e44ad; }
 .av-2 { background: #27ae60; }
 .av-3 { background: #e67e22; }
 .av-4 { background: #2980b9; }
 .av-5 { background: #c0392b; }
 .av-6 { background: #16a085; }

 .form-wrap { background: #f5f6f8; padding: 14px; }
 .form-container { background: #fff; border: 1px solid #dfdfe3; position: relative; }
 .form-statusbar { background: #fafafa; border-bottom: 1px solid #dfdfe3; padding: 10px 16px; display: flex; align-items: center; gap: 0; flex-wrap: wrap; }
 .stage-pill { background: #fff; border: 1px solid #c5c5cc; padding: 4px 10px; font-size: 10px; font-weight: 600; color: #6c757d; margin-right: -1px; clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%, 6px 50%); padding-left: 14px; padding-right: 16px; letter-spacing: 0.04em; }
 .stage-pill:first-child { clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%); padding-left: 10px; }
 .stage-pill.active { background: #714b67; color: #fff; border-color: #714b67; }
 .stage-pill.passed { background: #e8e0e4; color: #5a3c52; }

 .smart-buttons { padding: 14px 16px 0; display: flex; gap: 0; border-bottom: 1px solid #dfdfe3; flex-wrap: wrap; }
 .smart-btn { border: 1px solid #dfdfe3; padding: 8px 14px; display: flex; flex-direction: column; align-items: center; background: #fff; min-width: 95px; border-right-width: 0; margin-bottom: -1px; }
 .smart-btn:last-child { border-right-width: 1px; }
 .smart-btn .count { font-size: 16px; font-weight: 700; color: #212529; letter-spacing: 0.04em; }
 .smart-btn .label { font-size: 10px; color: #6c757d; margin-top: 2px; letter-spacing: 0.04em; }

 .form-inner { padding: 16px 20px; position: relative; }
 .form-title { font-size: 10px; color: #6c757d; font-weight: 500; margin-bottom: 3px; text-transform: uppercase; letter-spacing: 0.04em; }
 .form-h1 { font-size: 22px; font-weight: 500; color: #212529; margin-bottom: 4px; font-family: inherit; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .form-h1 .name-prefix { color: #6c757d; font-weight: 400; margin-right: 6px; }
 .form-subtitle { font-size: 12px; color: #6c757d; margin-bottom: 16px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; letter-spacing: 0.04em; word-spacing: 0.03em; }

 .form-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 8px; }
 @media (max-width: 600px) { .form-cols { grid-template-columns: 1fr; gap: 12px; } }
 .form-group { margin-bottom: 10px; }
 .form-label { font-size: 11px; color: #6c757d; font-weight: 500; letter-spacing: 0.04em; display: block; margin-bottom: 3px; }
 .form-value { font-size: 12px; color: #212529; padding: 2px 0; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .form-value.link { color: #017e84; text-decoration: underline; }
 .form-value .stars { color: #f39c12; letter-spacing: -1px; }

 .form-tabs { margin-top: 22px; border-bottom: 1px solid #dfdfe3; display: flex; gap: 0; overflow-x: auto; white-space: nowrap; }
 .form-tab { padding: 8px 14px; font-size: 12px; font-weight: 500; letter-spacing: 0.04em; color: #6c757d; border-bottom: 2px solid transparent; }
 .form-tab.active { color: #714b67; border-bottom-color: #714b67; font-weight: 600; }
 .form-tab-content { padding: 14px 0; font-size: 12px; color: #212529; line-height: 1.6; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .form-tab-content h4 { font-size: 12px; font-weight: 700; margin: 10px 0 4px; color: #212529; font-family: inherit; letter-spacing: 0.04em; }
 .form-tab-content ol, .form-tab-content ul { padding-left: 18px; }
 .form-tab-content li { margin-bottom: 2px; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .form-tab-content p { color: #212529; margin-bottom: 0.6rem; letter-spacing: 0.04em; word-spacing: 0.03em; }

 .chatter { background: #f9f9fb; border-top: 1px solid #dfdfe3; padding: 12px 20px; }
 .chatter-tabs { display: flex; gap: 0; margin-bottom: 10px; border-bottom: 1px solid #dfdfe3; overflow-x: auto; white-space: nowrap; }
 .chatter-tab { padding: 5px 12px 6px; font-size: 11px; color: #6c757d; font-weight: 500; border-bottom: 2px solid transparent; letter-spacing: 0.04em; }
 .chatter-tab.active { color: #714b67; border-bottom-color: #714b67; font-weight: 600; }
 .chatter-msg { display: flex; gap: 8px; padding: 6px 0; }
 .chatter-msg .avatar { width: 28px; height: 28px; border-radius: 50%; background: linear-gradient(135deg, #a78bfa, #7c3aed); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 10px; flex-shrink: 0; }
 .chatter-msg .body { flex: 1; font-size: 11.5px; color: #212529; background: #fff; padding: 7px 10px; border: 1px solid var(--border-light); border-radius: 4px; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .chatter-msg .body .author { font-weight: 600; margin-bottom: 2px; display: flex; justify-content: space-between; }
 .chatter-msg .body .time { font-size: 9.5px; color: #6c757d; font-weight: 500; letter-spacing: 0.04em; }
 .chatter-msg .body .note-label { display: inline-block; background: #fff5d6; color: #8a6d0d; padding: 1px 5px; border-radius: 2px; font-size: 9px; font-weight: 600; margin-right: 4px; letter-spacing: 0.04em; }

 .sla-badge { display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 100px; font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; }
 .sla-badge.on-track { background: #d1fae5; color: #22C55E; }
 .sla-badge.at-risk { background: #fef3c7; color: #FB923C; }
 .sla-badge.breached { background: #fee2e2; color: #F87171; }
 .sla-badge.met { background: #d1fae5; color: #22C55E; }
 .sla-badge::before { content: '●'; font-size: 12px; line-height: 1; }

 .odoo-list { background: #fff; overflow-x: auto; }
 .odoo-list table { width: 100%; border-collapse: collapse; font-size: 11.5px; }
 .odoo-list th { text-align: left; padding: 7px 10px; font-weight: 600; color: #212529; background: #f9f9fb; border-bottom: 1px solid #dfdfe3; font-size: 11px; letter-spacing: 0.04em; }
 .odoo-list td { padding: 8px 10px; border-bottom: 1px solid var(--border-light); color: #212529; vertical-align: middle; letter-spacing: 0.04em; }
 .odoo-list .ref-cell { font-family: 'JetBrains Mono', monospace; font-size: 10.5px; font-weight: 600; color: #017e84; letter-spacing: 0.04em; }
 .odoo-list .tag-chip { display: inline-block; padding: 1px 6px; border-radius: 3px; font-size: 9.5px; font-weight: 500; letter-spacing: 0.04em; }
 .chip-network { background: #dbeafe; color: #1e40af; }
 .chip-security { background: #fee2e2; color: #F87171; }
 .chip-database { background: #ede9fe; color: #6b21a8; }
 .chip-email { background: #fef3c7; color: #FB923C; }
 .chip-hardware { background: #d1fae5; color: #22C55E; }
 .chip-software { background: #fce7f3; color: #9f1239; }
 .chip-access { background: #e0e7ff; color: #3730a3; }
 .chip-erp { background: #ccfbf1; color: #115e59; }
 .chip-deployed { background: #d1fae5; color: #22C55E; }
 .chip-stock { background: #dbeafe; color: #1e40af; }
 .chip-maint { background: #fef3c7; color: #FB923C; }
 .chip-crit { background: #fee2e2; color: #F87171; letter-spacing: 0.04em; }
 .chip-high { background: #ffedd5; color: #9a3412; letter-spacing: 0.04em; }
 .chip-med { background: #fef3c7; color: #FB923C; letter-spacing: 0.04em; }
 .chip-low { background: #d1fae5; color: #22C55E; letter-spacing: 0.04em; }

 .dash-wrap { padding: 16px; }
 .kpi-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
 @media (max-width: 720px) { .kpi-grid { grid-template-columns: repeat(2, 1fr); } }
 .kpi-card { background: #fff; border: 1px solid #dfdfe3; border-radius: 6px; padding: 12px 14px; position: relative; }
 .kpi-label { font-size: 10px; color: #6c757d; text-transform: uppercase; letter-spacing: 0.04em; font-weight: 600; margin-bottom: 6px; }
 .kpi-value { font-family: 'Inter', sans-serif; font-size: 26px; letter-spacing: -0.01em; font-weight: 700; color: #212529; line-height: 1; }
 .kpi-trend { font-size: 10px; margin-top: 6px; display: flex; align-items: center; gap: 3px; font-weight: 600; letter-spacing: 0.04em; }
 .kpi-trend.up { color: #28a745; }
 .kpi-trend.down { color: #dc3545; }
 .kpi-icon { position: absolute; top: 12px; right: 12px; width: 28px; height: 28px; border-radius: 6px; background: var(--brand-light); color: var(--brand-primary); display: flex; align-items: center; justify-content: center; font-size: 14px; }
 .kpi-icon.crit { background: #fee2e2; color: #F87171; }
 .kpi-icon.warn { background: #fef3c7; color: #FB923C; }
 .kpi-icon.ok { background: #d1fae5; color: #22C55E; }

 .dash-charts { display: grid; grid-template-columns: 1.3fr 1fr; gap: 10px; margin-bottom: 14px; }
 @media (max-width: 720px) { .dash-charts, .dash-bottom { grid-template-columns: 1fr !important; } }
 .dash-card { background: #fff; border: 1px solid #dfdfe3; border-radius: 6px; padding: 14px 16px; }
 .dash-card-title { font-size: 12px; font-weight: 600; color: #212529; margin-bottom: 12px; display: flex; justify-content: space-between; align-items: center; letter-spacing: 0.04em; }
 .dash-card-title .sub { font-size: 10px; color: #6c757d; font-weight: 500; }

 .stacked-bars { display: flex; flex-direction: column; gap: 10px; }
 .stacked-row { display: grid; grid-template-columns: 72px 1fr 52px; gap: 8px; align-items: center; font-size: 10px; }
 .stacked-label { color: #212529; font-weight: 500; letter-spacing: 0.04em; }
 .stacked-bar { height: 16px; border-radius: 3px; display: flex; overflow: hidden; background: #f7f8fb; }
 .stacked-seg { height: 100%; font-size: 9px; font-weight: 700; color: #fff; display: flex; align-items: center; justify-content: center; letter-spacing: 0.04em; }
 .seg-met { background: #28a745; }
 .seg-track { background: #34d399; }
 .seg-risk { background: #e8a33d; }
 .seg-breach { background: #dc3545; }
 .stacked-total { text-align: right; color: #212529; font-weight: 600; letter-spacing: 0.04em; }

 .donut-wrap { display: flex; align-items: center; gap: 18px; }
 .donut { width: 110px; height: 110px; border-radius: 50%; background: conic-gradient(#28a745 0% 62%, #e8a33d 62% 78%, #dc3545 78% 88%, #e5e7eb 88% 100%); position: relative; flex-shrink: 0; }
 .donut::after { content: ''; position: absolute; inset: 18px; border-radius: 50%; background: #fff; }
 .donut-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; z-index: 1; }
 .donut-center strong { font-size: 22px; font-weight: 700; color: #212529; font-family: 'Inter', sans-serif; line-height: 1; letter-spacing: 0.04em; }
 .donut-center span { font-size: 9px; color: #6c757d; margin-top: 2px; text-transform: uppercase; letter-spacing: 0.04em; }
 .donut-legend { flex: 1; font-size: 11px; }
 .donut-legend .legend-item { display: flex; align-items: center; gap: 6px; padding: 4px 0; border-bottom: 1px solid var(--border-light); }
 .donut-legend .legend-item:last-child { border: none; }
 .donut-legend .dot { width: 9px; height: 9px; border-radius: 2px; }
 .donut-legend .legend-label { flex: 1; color: #212529; letter-spacing: 0.04em; }
 .donut-legend .legend-val { font-weight: 700; color: #212529; letter-spacing: 0.04em; }

 .dash-bottom { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }

 .priority-grid-mini { display: grid; grid-template-columns: 80px repeat(3, 1fr); gap: 3px; background: #fff; border: 1px solid #dfdfe3; border-radius: 6px; padding: 10px; margin-top: 8px; }
 .priority-grid-mini .pg-cell { padding: 6px 3px; text-align: center; font-size: 9.5px; font-weight: 600; border-radius: 3px; letter-spacing: 0.04em; }
 .priority-grid-mini .pg-hdr { background: #f9f9fb; color: #212529; font-weight: 700; }
 .priority-grid-mini .pg-row-hdr { background: #f9f9fb; color: #212529; font-weight: 700; text-align: left; padding-left: 8px; }
 .priority-grid-mini .pg-crit { background: #fee2e2; color: #F87171; }
 .priority-grid-mini .pg-high { background: #ffedd5; color: #9a3412; }
 .priority-grid-mini .pg-med { background: #fef3c7; color: #FB923C; }
 .priority-grid-mini .pg-low { background: #d1fae5; color: #22C55E; }
 .priority-grid-mini .pg-cell.selected { box-shadow: 0 0 0 2px #714b67; position: relative; z-index: 1; }

 .sla-cards-wrap { padding: 14px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
 @media (max-width: 600px) { .sla-cards-wrap { grid-template-columns: 1fr; } }
 .sla-policy-card { background: #fff; border: 1px solid #dfdfe3; border-radius: 6px; padding: 14px 16px; position: relative; }
 .sla-policy-card .priority-bar { position: absolute; left: 0; top: 0; bottom: 0; width: 4px; border-radius: 6px 0 0 6px; }
 .sla-policy-card.crit .priority-bar { background: #dc3545; }
 .sla-policy-card.high .priority-bar { background: #fd7e14; }
 .sla-policy-card.med .priority-bar { background: #e8a33d; }
 .sla-policy-card.low .priority-bar { background: #28a745; }
 .sla-policy-card h3 { font-size: 13px; font-weight: 700; color: #212529; margin-bottom: 3px; font-family: inherit; display: flex; align-items: center; gap: 6px; letter-spacing: 0.04em; }
 .sla-policy-card .stars { color: #f39c12; letter-spacing: -1px; font-size: 12px; }
 .sla-policy-card .policy-meta { font-size: 11px; color: #6c757d; margin-bottom: 10px; letter-spacing: 0.04em; }
 .sla-times { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
 .sla-time-item .time-label { font-size: 10px; color: #6c757d; text-transform: uppercase; font-weight: 600; letter-spacing: 0.04em; margin-bottom: 3px; }
 .sla-time-item .time-value { font-size: 18px; font-weight: 700; color: #212529; font-family: 'Inter', sans-serif; letter-spacing: 0.04em; }
 .sla-time-item .time-unit { font-size: 11px; color: #6c757d; font-weight: 500; margin-left: 3px; letter-spacing: 0.04em; }
 .sla-usage { display: flex; justify-content: space-between; align-items: center; margin-top: 10px; padding-top: 9px; border-top: 1px solid var(--border-light); font-size: 11px; }
 .sla-usage .usage-label { color: #6c757d; letter-spacing: 0.04em; }
 .sla-usage .usage-val { color: #017e84; font-weight: 600; letter-spacing: 0.04em; }

 .kb-grid-wrap { padding: 14px; }
 .kb-filters { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }
 .kb-filter-pill { padding: 4px 10px; border-radius: 100px; font-size: 10.5px; font-weight: 500; background: #fff; border: 1px solid #dfdfe3; color: #6c757d; letter-spacing: 0.04em; }
 .kb-filter-pill.active { background: #714b67; color: #fff; border-color: #714b67; }
 .kb-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
