 <a href="https://etriplesoft.com/odoo-for-accounting/" style="display:inline-flex;align-items:center;gap:6px;background:#112B4E;border:1px solid var(--border);border-radius:100px;padding:8px 18px;font-size:13px;font-weight:500;color:#60A5FA;text-decoration:none;letter-spacing:0.04em;transition:all .2s;" onmouseover="this.style.background='var(--brand-primary)';this.style.color='#fff'" onmouseout="this.style.background='#112B4E';this.style.color='#60A5FA'">💰 Odoo for Accounting</a>
 <a href="https://etriplesoft.com/odoo-for-restaurants/" style="display:inline-flex;align-items:center;gap:6px;background:#112B4E;border:1px solid var(--border);border-radius:100px;padding:8px 18px;font-size:13px;font-weight:500;color:#60A5FA;text-decoration:none;letter-spacing:0.04em;transition:all .2s;" onmouseover="this.style.background='var(--brand-primary)';this.style.color='#fff'" onmouseout="this.style.background='#112B4E';this.style.color='#60A5FA'">🍽️ Odoo for Restaurants</a>
 <a href="https://etriplesoft.com/odoo-for-real-estate/" style="display:inline-flex;align-items:center;gap:6px;background:#112B4E;border:1px solid var(--border);border-radius:100px;padding:8px 18px;font-size:13px;font-weight:500;color:#60A5FA;text-decoration:none;letter-spacing:0.04em;transition:all .2s;" onmouseover="this.style.background='var(--brand-primary)';this.style.color='#fff'" onmouseout="this.style.background='#112B4E';this.style.color='#60A5FA'">🏠 Odoo for Real Estate</a>
