[{"id":"2df1629","elType":"container","settings":{"content_width":"full","boxed_width":{"unit":"px","size":1600,"sizes":[]}},"elements":[{"id":"0f9b5e8","elType":"widget","settings":{"html":"<html lang="en">
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <!-- Fonts matching the E-TripleSoft brand -->
 <link rel="preconnect" href="https://fonts.googleapis.com">
 <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
 <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">

 <style>
 /* ----- Design system: light + blue gradient (matches E-TripleSoft blog) ----- */
 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

 :root {
 --bg: #071020;
 --bg-alt: #0A1628;
 --bg-dark: #071020;
 --bg-dark-card: #0F1E35;
 --surface: #0F1E35;
 --surface-alt: #0A1628;
 --border: #1A3050;
 --border-light: #1A3050;
 --text: #E8F0FF;
 --text-secondary: #7A9DC8;
 --text-muted: #4A6FA0;
 --brand-primary: #1B6FE4;
 --brand-secondary: #00C4CC;
 --brand-accent: #00C4CC;
 --brand-light: rgba(27,111,228,.18);
 --brand-gradient: linear-gradient(135deg, #1B6FE4 0%, #00C4CC 100%);
 --green: #22C55E;
 --green-light: rgba(34,197,94,.15);
 --amber: #FB923C;
 --amber-light: rgba(251,146,60,.15);
 --rose: #F87171;
 --rose-light: rgba(248,113,113,.15);
 --purple: #875A7B;
 --purple-light: rgba(135,90,123,.15);
 --teal: #00C4CC;
 --teal-light: rgba(0,196,204,.12);
 --orange: #FB923C;
 --radius: 12px;
 --radius-lg: 18px;
 --radius-sm: 8px;
 --shadow-sm: 0 2px 20px rgba(0,0,0,.40);
 --shadow: 0 4px 28px rgba(0,0,0,.45);
 --shadow-lg: 0 8px 40px rgba(0,0,0,.50);
 --max-w: 820px;
 --max-w-wide: 1160px;
 }

 html { scroll-behavior: smooth; font-size: 16px; -webkit-font-smoothing: antialiased; }
 body { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; background: var(--bg); color: var(--text); line-height: 1.75; }
 ::selection { background: var(--brand-secondary); color: #fff; }
 strong { color: #E8F0FF; }
 a { color: var(--brand-primary); text-decoration: none; transition: 0.2s; }
 a:hover { color: var(--brand-secondary); text-decoration: underline; }
 h1, h2, h3, h4 { font-family: 'Inter', 'Plus Jakarta Sans', sans-serif; font-weight: 700; color: #E8F0FF; line-height: 1.2; }
 h2 { font-size: 2rem; margin-bottom: 1.5rem; letter-spacing: -0.01em; }
 p { color: #7A9DC8; margin-bottom: 1.3rem; }

 .container { max-width: var(--max-w-wide); margin: 0 auto; padding: 0 24px; }

 /* ----- Hero (dark) ----- */
 .hero {
 background: linear-gradient(135deg,#071020 0%,#0D2240 45%,#1A3A5C 80%,#1B5FC4 100%);
 color: #fff;
 position: relative;
 overflow: hidden;
 padding: 0;
 margin-bottom: 0;
 border-radius: 0;
 }
 .hero::before {
 content: '';
 position: absolute;
 top: -40%; right: -20%;
 width: 700px; height: 700px;
 background: radial-gradient(circle, rgba(27,111,228,.25) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero::after {
 content: '';
 position: absolute;
 bottom: -30%; left: -10%;
 width: 500px; height: 500px;
 background: radial-gradient(circle, rgba(0,196,204,.15) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero .container { position: relative; z-index: 2; padding-top: 80px; padding-bottom: 72px; }
 .breadcrumb {
 font-size: .82rem;
 color: rgba(255,255,255,.5);
 margin-bottom: 28px;
 font-weight: 500;
 display: flex;
 gap: 0.5rem;
 flex-wrap: wrap;
 }
 .breadcrumb a { color: rgba(255,255,255,.6); }
 .breadcrumb a:hover { color: #fff; text-decoration: none; }
 .breadcrumb strong { color: rgba(255,255,255,.8); font-weight: 600; }
 .subtitle {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 background: rgba(0,196,204,.12);
 border: 1px solid rgba(0,196,204,.3);
 border-radius: 100px;
 padding: 6px 18px 6px 12px;
 font-size: .78rem;
 font-weight: 600;
 color: #00C4CC;
 margin-bottom: 28px;
 letter-spacing: .3px;
 text-transform: uppercase;
 }
 .hero h1 {
 font-family: 'Inter', sans-serif;
 font-size: clamp(35px, 2.2vw, 25px);
 font-weight: 800;
 line-height: 1.15;
 margin-bottom: 20px;
 letter-spacing: -.02em;
 color: #fff;
 }
 .hero-desc {
 font-size: 1.15rem;
 color: #8AAFD8;
 max-width: 620px;
 line-height: 1.7;
 margin-bottom: 36px;
 }
 .cta-group { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
 .btn {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 padding: 14px 28px;
 border-radius: 10px;
 font-weight: 700;
 font-size: .92rem;
 border: none;
 cursor: pointer;
 transition: all .25s;
 text-decoration: none;
 font-family: inherit;
 }
 .btn-primary {
 background: var(--brand-gradient);
 color: #fff;
 box-shadow: 0 4px 16px rgba(27,111,228,.3);
 }
 .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(27,111,228,.4); text-decoration: none; }
 .btn-secondary {
 background: transparent;
 color: #fff;
 border: 1.5px solid rgba(255,255,255,.25);
 }
 .btn-secondary:hover { border-color: rgba(255,255,255,.5); background: rgba(255,255,255,.05); text-decoration: none; }

 /* Hero Stats */
 .stats {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
 gap: 20px;
 max-width: 700px;
 margin: 2.2rem 0;
 }
 .stat-card {
 text-align: center;
 padding: 20px 12px;
 background: rgba(255,255,255,.04);
 border: 1px solid rgba(255,255,255,.08);
 border-radius: var(--radius);
 backdrop-filter: blur(8px);
 }
 .stat-card strong {
 font-family: 'Inter', sans-serif;
 font-size: 1.8rem;
 font-weight: 800;
 color: #00C4CC;
 display: block;
 line-height: 1.2;
 }
 .stat-card span { font-size: .78rem; color: rgba(255,255,255,.5); font-weight: 500; margin-top: 4px; display: block; }
 .meta {
 display: flex;
 gap: 2rem;
 flex-wrap: wrap;
 color: rgba(255,255,255,.5);
 font-size: 0.9rem;
 margin-bottom: 0;
 padding-bottom: 0;
 border-bottom: none;
 }

 /* ----- Main grid (TOC + content) ----- */
 .main-grid { display: grid; grid-template-columns: 260px 1fr; gap: 3.5rem; align-items: start; margin-top: 64px; }
 @media (max-width: 950px) { .main-grid { grid-template-columns: 1fr; } }

 /* TOC */
 .toc {
 position: sticky;
 top: 2rem;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 28px 24px;
 margin-bottom: 3rem;
 box-shadow: var(--shadow);
 }
 .toc h3 {
 font-family: 'Inter', sans-serif;
 font-weight: 800;
 font-size: 1rem;
 margin-bottom: 16px;
 color: #C8DEFF;
 display: flex;
 align-items: center;
 gap: 8px;
 text-transform: none;
 letter-spacing: 0.02em;
 }
 .toc ul { list-style: none; padding-left: 0; }
 .toc li {
 margin-bottom: 0.8rem;
 border-left: 2px solid var(--border);
 padding-left: 1rem;
 transition: 0.2s;
 }
 .toc li:hover { border-left-color: var(--brand-secondary); }
 .toc a { color: var(--text-muted); font-size: 0.9rem; font-weight: 500; }
 .toc a:hover { color: var(--brand-secondary); text-decoration: none; }

 /* Sections */
 section { margin-bottom: 5rem; scroll-margin-top: 2.5rem; }
 h2 {
 font-size: 2rem;
 margin-bottom: 1.5rem;
 position: relative;
 display: inline-block;
 letter-spacing: -0.01em;
 color: #E8F0FF;
 }
 h2::after {
 content: '';
 position: absolute;
 bottom: -10px;
 left: 0;
 width: 45px;
 height: 4px;
 background: var(--brand-secondary);
 border-radius: 2px;
 }
 h3 { font-size: 1.5rem; margin: 2.2rem 0 1.2rem; color: #E8F0FF; letter-spacing: 0.02em; }

 /* Card grids */
 .card-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
 gap: 20px;
 margin-top: 1.8rem;
 }
 .card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 28px 24px;
 transition: all .3s;
 box-shadow: var(--shadow-sm);
 }
 .card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .card-icon { font-size: 2rem; margin-bottom: 0.8rem; display: block; }
 .card h3 { margin-top: 0; font-size: 1.2rem; margin-bottom: 0.5rem; color: #E8F0FF; letter-spacing: 0.02em; word-spacing: 0.05em; }

 /* Workflow Phases */
 .workflow { position: relative; }
 .phase {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 1.8rem;
 margin-bottom: 1.2rem;
 border-left: 6px solid var(--brand-secondary);
 box-shadow: var(--shadow-sm);
 }
 .phase-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: 0.8rem;
 flex-wrap: wrap;
 gap: 0.8rem;
 }
 .phase-header strong { font-size: 1.2rem; color: #E8F0FF; font-family: 'Inter', sans-serif; letter-spacing: 0.02em; word-spacing: 0.05em; }
 .phase-num {
 background: rgba(27,111,228,.18);
 color: #00C4CC;
 padding: 0.4rem 1rem;
 border-radius: 40px;
 font-weight: 600;
 font-size: 0.85rem;
 border: 1px solid var(--border);
 }
 .phase p { color: #7A9DC8; }

 /* Modules Bento */
 .bento-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
 gap: 24px;
 }
 .module-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 32px;
 transition: all .3s;
 position: relative;
 overflow: hidden;
 }
 .module-card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .module-card h3 {
 font-family: 'Inter', sans-serif;
 font-size: 1.2rem;
 font-weight: 700;
 margin: 0 0 10px;
 color: #E8F0FF;
 display: flex;
 align-items: center;
 gap: 8px;
 letter-spacing: 0.02em;
 word-spacing: 0.05em;
 }
 .module-card ul { margin: 1.2rem 0 0 1.4rem; color: var(--text-secondary); }
 .module-card li { margin-bottom: 0.7rem; font-size: 0.92rem; color: #7A9DC8; }

 /* Role matrix */
 .matrix-wrap {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 margin-top: 1.8rem;
 box-shadow: var(--shadow-sm);
 overflow-x: auto;
 }
 .role-matrix {
 display: grid;
 grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr;
 gap: 8px;
 min-width: 620px;
 }
 .role-matrix .cell {
 padding: 14px 10px;
 text-align: center;
 border-radius: var(--radius-sm);
 font-weight: 600;
 font-size: 0.9rem;
 }
 .role-matrix .hdr { background: #112B4E; color: #E8F0FF; font-weight: 700; border: 1px solid #1A3050; }
 .role-matrix .row-hdr { background: #0F1E35; color: #C8DEFF; font-weight: 700; text-align: left; padding-left: 16px; border: 1px solid #1A3050; }
 .role-matrix .yes { background: var(--green-light); color: #22C55E; border: 1px solid #a7f3d0; }
 .role-matrix .partial { background: var(--amber-light); color: #FB923C; border: 1px solid #fde68a; }
 .role-matrix .no { background: #fee2e2; color: #F87171; border: 1px solid #fecaca; }

 /* Pipeline */
 .pipeline {
 display: flex;
 align-items: center;
 gap: 8px;
 flex-wrap: wrap;
 padding: 1.4rem;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 margin: 1.5rem 0;
 }
 .pipe-stage {
 background: var(--surface);
 border: 1px solid var(--border);
 padding: 8px 14px;
 border-radius: 8px;
 font-size: 0.85rem;
 font-weight: 600;
 color: var(--text);
 }
 .pipe-stage.start { border-color: var(--brand-secondary); color: var(--brand-secondary); }
 .pipe-stage.hold { background: var(--amber-light); border-color: var(--amber); color: var(--amber); }
 .pipe-stage.done { background: var(--green-light); border-color: var(--green); color: var(--green); }
 .pipe-arrow { color: var(--text-muted); font-weight: 700; }

 /* Compliance / trust grid */
 .compliance-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .country-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 28px 20px;
 text-align: center;
 transition: all .3s;
 }
 .country-card:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .flag { font-size: 2rem; margin-bottom: 12px; display: block; }
 .country-card h3 { font-size: 1rem; margin: 0 0 8px; color: #E8F0FF; }
 .country-card p { font-size: 0.85rem; color: #4A6FA0; }

 /* Testimonials */
 .testimonial-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 gap: 1.8rem;
 margin-top: 2rem;
 }
 .testimonial {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 }
 .testimonial p { font-style: italic; font-size: 1.05rem; color: #7A9DC8; }
 .testimonial-author { margin-top: 1.2rem; color: var(--brand-secondary); font-weight: 600; }

 /* Results */
 .results-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .result-item {
 text-align: center;
 padding: 32px 20px;
