 .hero {
 background: linear-gradient(135deg,#071020 0%,#0D2240 45%,#1A3A5C 80%,#1B5FC4 100%);
 color: #fff; position: relative; overflow: hidden; padding: 0; margin-bottom: 0; border-radius: 0;
 }
 .hero::before { content: ''; position: absolute; top: -40%; right: -20%; width: 700px; height: 700px; background: radial-gradient(circle, rgba(27,111,228,.25) 0%, transparent 70%); pointer-events: none; }
 .hero::after { content: ''; position: absolute; bottom: -30%; left: -10%; width: 500px; height: 500px; background: radial-gradient(circle, rgba(0,196,204,.15) 0%, transparent 70%); pointer-events: none; }
 .hero .container { position: relative; z-index: 2; padding-top: 80px; padding-bottom: 72px; }
 .breadcrumb { font-size: .82rem; color: rgba(255,255,255,.5); margin-bottom: 28px; font-weight: 500; display: flex; gap: 0.5rem; flex-wrap: wrap; letter-spacing: 0.04em; }
 .breadcrumb a { color: rgba(255,255,255,.6); }
 .breadcrumb a:hover { color: #fff; text-decoration: none; }
 .breadcrumb strong { color: rgba(255,255,255,.8); font-weight: 600; }
 .subtitle { display: inline-flex; align-items: center; gap: 8px; background: rgba(0,196,204,.12); border: 1px solid rgba(0,196,204,.3); border-radius: 100px; padding: 6px 18px 6px 12px; font-size: .78rem; font-weight: 600; color: #00C4CC; margin-bottom: 28px; letter-spacing: 1.2px; text-transform: uppercase; }
 h1 { font-family: 'Inter', sans-serif; font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 800; line-height: 1.15; margin-bottom: 20px; letter-spacing: -.02em; color: #ffffff; }
 .hero-desc { font-size: 1.15rem; color: #8AAFD8; max-width: 620px; line-height: 1.7; margin-bottom: 36px; letter-spacing: 0.025em; word-spacing: 0.02em; }
 .cta-group { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
 .btn { display: inline-flex; align-items: center; gap: 8px; padding: 14px 28px; border-radius: 10px; font-weight: 700; font-size: .92rem; border: none; cursor: pointer; transition: all .25s; text-decoration: none; font-family: inherit; letter-spacing: 0.04em; }
 .btn-primary { background: var(--brand-gradient); color: #fff; box-shadow: 0 4px 16px rgba(27,111,228,.3); }
 .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(27,111,228,.4); text-decoration: none; }
 .btn-secondary { background: transparent; color: #fff; border: 1.5px solid rgba(255,255,255,.25); }
 .btn-secondary:hover { border-color: rgba(255,255,255,.5); background: rgba(255,255,255,.05); text-decoration: none; }

 .stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 20px; max-width: 700px; margin: 2.2rem 0; }
 .stat-card { text-align: center; padding: 20px 12px; background: rgba(255,255,255,.04); border: 1px solid rgba(255,255,255,.08); border-radius: var(--radius); backdrop-filter: blur(8px); }
 .stat-card strong { font-family: 'Inter', sans-serif; font-size: 1.8rem; font-weight: 800; color: #00C4CC; display: block; line-height: 1.2; }
 .stat-card span { font-size: .78rem; color: rgba(255,255,255,.5); font-weight: 500; margin-top: 4px; display: block; letter-spacing: 0.04em; }
 .meta { display: flex; gap: 2rem; flex-wrap: wrap; color: rgba(255,255,255,.5); font-size: 0.9rem; margin-bottom: 0; padding-bottom: 0; border-bottom: none; letter-spacing: 0.04em; }

 .main-grid { display: grid; grid-template-columns: 240px 1fr; gap: 2.5rem; align-items: start; margin-top: 64px; max-width: 1160px; margin-left: auto; margin-right: auto; }
 @media (max-width: 950px) { .main-grid { grid-template-columns: 1fr; } }

 .toc { position: sticky; top: 24px; z-index: 100; background: var(--surface-alt); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 24px 20px; margin-bottom: 3rem; box-shadow: var(--shadow); margin-left: -24px; max-height: calc(100vh - 48px); overflow-y: auto; }
 .toc::-webkit-scrollbar { width: 4px; }
 .toc::-webkit-scrollbar-track { background: transparent; }
 .toc::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
 .toc::-webkit-scrollbar-thumb:hover { background: var(--brand-secondary); }
 .toc h3 { font-family: 'Inter', sans-serif; font-weight: 800; font-size: 1rem; margin-bottom: 16px; color: #C8DEFF; display: flex; align-items: center; gap: 8px; }
 .toc ul { list-style: none; padding-left: 0; }
 .toc li { margin-bottom: 0.8rem; border-left: 2px solid var(--border); padding-left: 1rem; transition: 0.2s; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .toc li:hover { border-left-color: var(--brand-secondary); }
 .toc a { color: var(--text-muted); font-size: 0.9rem; font-weight: 500; letter-spacing: 0.04em; }
 .toc a:hover { color: var(--brand-secondary); text-decoration: none; }

 section { margin-bottom: 5rem; scroll-margin-top: 2.5rem; }
 h2 { font-size: 2rem; margin-bottom: 1.5rem; position: relative; display: inline-block; letter-spacing: 0.03em; color: #E8F0FF; }
 h2::after { content: ''; position: absolute; bottom: -10px; left: 0; width: 45px; height: 4px; background: var(--brand-secondary); border-radius: 2px; }
 h3 { font-size: 1.5rem; margin: 2.2rem 0 1.2rem; color: #E8F0FF; letter-spacing: 0.03em; }

 .card-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(270px, 1fr)); gap: 20px; margin-top: 1.8rem; }
 .card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 28px 24px; transition: all .3s; box-shadow: var(--shadow-sm); letter-spacing: 0.04em; word-spacing: 0.03em; }
 .card:hover { border-color: var(--brand-accent); box-shadow: var(--shadow-lg); transform: translateY(-4px); }
 .card-icon { font-size: 2rem; margin-bottom: 0.8rem; display: block; }
 .card h3 { margin-top: 0; font-size: 1.2rem; margin-bottom: 0.5rem; color: #E8F0FF; letter-spacing: 0.04em; }
 .card p { letter-spacing: 0.04em; word-spacing: 0.03em; }

 .workflow { position: relative; }
 .phase { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.8rem; margin-bottom: 1.2rem; border-left: 6px solid var(--brand-secondary); box-shadow: var(--shadow-sm); }
 .phase-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.8rem; flex-wrap: wrap; gap: 0.8rem; }
 .phase-header strong { font-size: 1.2rem; color: #E8F0FF; font-family: 'Inter', sans-serif; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .phase-num { background: rgba(27,111,228,.18); color: #00C4CC; padding: 0.4rem 1rem; border-radius: 40px; font-weight: 600; font-size: 0.85rem; border: 1px solid var(--border); letter-spacing: 0.04em; }
 .phase p { color: #7A9DC8; letter-spacing: 0.04em; word-spacing: 0.03em; }

 .bento-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 24px; }
 .module-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 32px; transition: all .3s; position: relative; overflow: hidden; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .module-card:hover { border-color: var(--brand-accent); box-shadow: var(--shadow-lg); transform: translateY(-4px); }
 .module-card h3 { font-family: 'Inter', sans-serif; font-size: 1.2rem; font-weight: 700; margin: 0 0 10px; color: #E8F0FF; display: flex; align-items: center; gap: 8px; letter-spacing: 0.04em; }
 .module-card ul { margin: 1.2rem 0 0 1.4rem; color: #7A9DC8; }
 .module-card li { margin-bottom: 0.7rem; font-size: 0.92rem; color: #7A9DC8; letter-spacing: 0.04em; word-spacing: 0.03em; }

 .matrix-wrap { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 2rem; margin-top: 1.8rem; box-shadow: var(--shadow-sm); overflow-x: auto; }
 .matrix { display: grid; grid-template-columns: 1.1fr 1fr 1fr 1fr; gap: 8px; min-width: 520px; }
 .matrix .cell { padding: 16px 10px; text-align: center; border-radius: var(--radius-sm); font-weight: 600; font-size: 0.92rem; letter-spacing: 0.04em; }
 .matrix .hdr { background: #112B4E; color: #E8F0FF; font-weight: 700; border: 1px solid #1A3050; }
 .matrix .row-hdr { background: #0F1E35; color: #C8DEFF; font-weight: 700; text-align: left; padding-left: 16px; border: 1px solid #1A3050; }
 .matrix .p-crit { background: rgba(248,113,113,.18); color: #F87171; border: 1px solid rgba(248,113,113,.3); }
 .matrix .p-high { background: rgba(251,146,60,.15); color: #FB923C; border: 1px solid rgba(251,146,60,.3); }
 .matrix .p-med { background: rgba(252,211,77,.12); color: #FCD34D; border: 1px solid rgba(252,211,77,.25); }
 .matrix .p-low { background: rgba(34,197,94,.15); color: #22C55E; border: 1px solid rgba(34,197,94,.3); }

 .pipeline { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; padding: 1.4rem; background: var(--surface-alt); border: 1px solid var(--border); border-radius: var(--radius); margin: 1.5rem 0; }
 .pipe-stage { background: var(--surface); border: 1px solid var(--border); padding: 8px 14px; border-radius: 8px; font-size: 0.85rem; font-weight: 600; color: var(--text); letter-spacing: 0.04em; word-spacing: 0.03em; }
 .pipe-stage.start { border-color: var(--brand-secondary); color: var(--brand-secondary); }
 .pipe-stage.hold { background: rgba(251,146,60,.15); border-color: #FB923C; color: #FB923C; }
 .pipe-stage.done { background: rgba(34,197,94,.15); border-color: #22C55E; color: #22C55E; }
 .pipe-arrow { color: var(--text-muted); font-weight: 700; }

 .compliance-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; margin-top: 2rem; }
 .country-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 28px 20px; text-align: center; transition: all .3s; }
 .country-card:hover { border-color: var(--brand-secondary); box-shadow: var(--shadow); }
 .flag { font-size: 2rem; margin-bottom: 12px; display: block; }
 .country-card h3 { font-size: 1rem; margin: 0 0 8px; color: #E8F0FF; letter-spacing: 0.04em; }
 .country-card p { font-size: 0.85rem; color: #4A6FA0; letter-spacing: 0.04em; }

 .testimonial-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 1.8rem; margin-top: 2rem; }
 .testimonial { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 2rem; }
 .testimonial p { font-style: italic; font-size: 1.05rem; color: #7A9DC8; letter-spacing: 0.04em; word-spacing: 0.03em; line-height: 1.8; }
 .testimonial-author { margin-top: 1.2rem; color: var(--brand-secondary); font-weight: 600; letter-spacing: 0.04em; }

 .results-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; margin-top: 2rem; }
 .result-item { text-align: center; padding: 32px 20px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); transition: all .3s; }
 .result-item:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .result-item strong { font-family: 'Inter', sans-serif; font-size: 2.4rem; font-weight: 900; color: #00C4CC; display: block; margin-bottom: 8px; }
 .result-item p { font-weight: 700; color: #E8F0FF; margin-bottom: 6px; letter-spacing: 0.04em; }

 .faq-item { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); margin-bottom: 1rem; overflow: hidden; transition: all .3s; }
 .faq-item:hover { border-color: var(--brand-secondary); background: #0F1E35; }
 .faq-q { padding: 20px 24px; cursor: pointer; font-weight: 700; display: flex; justify-content: space-between; align-items: center; color: #C8DEFF; font-size: 1rem; user-select: none; letter-spacing: 0.04em; word-spacing: 0.03em; background: #0F1E35; }
 .faq-q::after { content: '+'; font-family: 'Inter', sans-serif; font-size: 1.4rem; font-weight: 300; color: var(--brand-secondary); transition: transform .3s; }
 .faq-a { max-height: 0; overflow: hidden; transition: max-height .4s ease, padding .3s ease; padding: 0 24px; color: #7A9DC8; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .faq-item.active .faq-a { max-height: 400px; padding-bottom: 20px; }
 .faq-item.active .faq-q::after { content: '−'; }
 .faq-item.active .faq-q { background: #112B4E; }

 .cta-section { background: var(--brand-gradient); border-radius: var(--radius-lg); padding: 48px 40px; text-align: center; color: #fff; margin: 56px 0; position: relative; overflow: hidden; }
 .cta-section::before { content: ''; position: absolute; top: -50%; right: -20%; width: 400px; height: 400px; background: radial-gradient(circle, rgba(255,255,255,.1) 0%, transparent 70%); pointer-events: none; }
 .cta-section h2 { font-family: 'Inter', sans-serif; font-size: 1.8rem; font-weight: 800; margin-bottom: 12px; color: #fff; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .cta-section h2::after { display: none; }
 .cta-section p { color: rgba(255,255,255,.9); margin-bottom: 28px; font-size: 1.1rem; letter-spacing: 0.04em; word-spacing: 0.03em; }
 .cta-section .btn { background: #fff; color: var(--brand-primary); font-weight: 700; padding: 1.1rem 2.5rem; }
 .cta-section .btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.15); }

 .case-highlight { background: var(--surface-alt); border-radius: var(--radius); padding: 2.2rem; border: 1px solid var(--border); margin: 2.5rem 0; }
 .case-highlight h3 { margin-top: 0; color: var(--brand-secondary); letter-spacing: 0.04em; word-spacing: 0.03em; }
 .case-highlight p { letter-spacing: 0.04em; word-spacing: 0.03em; }

 footer { text-align: center; padding: 3rem 0; border-top: 1px solid var(--border); margin-top: 4rem; color: #4A6FA0; background: var(--bg); }
 footer a { color: var(--brand-secondary); }
 .share-links { text-align: center; margin-top: 2.5rem; color: #4A6FA0; font-size: 0.95rem; letter-spacing: 0.04em; }
 .share-links a { margin: 0 0.5rem; }

 .hero h2.hero-title { font-size: clamp(2.2rem, 5vw, 3.4rem); font-weight: 800; line-height: 1.15; margin-bottom: 20px; letter-spacing: 0.01em; color: #ffffff; }
 @media (max-width: 950px) { .toc { position: relative; top: 0; max-height: none; overflow-y: visible; margin-bottom: 2rem; z-index: auto; } }
 @media (max-width: 600px) { .hero .container { padding-top: 48px; padding-bottom: 48px; } h1 { font-size: 2rem; } .stats { grid-template-columns: 1fr 1fr; } }

 /* ============================================================
 EMBEDDED MOCKUP STYLES
 ============================================================ */
 .mockup-frame { border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-lg); background: #f5f6f8; margin: 2rem 0 1rem; }
 .mockup-caption { font-size: 0.82rem; color: var(--text-muted); margin-top: 0.6rem; font-style: italic; text-align: center; letter-spacing: 0.04em; }
 .browser-bar { background: #e8e9ed; padding: 8px 12px; display: flex; align-items: center; gap: 10px; border-bottom: 1px solid #dfdfe3; }
 .browser-dots { display: flex; gap: 5px; }
 .browser-dots span { width: 10px; height: 10px; border-radius: 50%; display: block; }
 .browser-dots span:nth-child(1) { background: #ff5f57; }
 .browser-dots span:nth-child(2) { background: #febc2e; }
 .browser-dots span:nth-child(3) { background: #28c840; }
 .browser-url { flex: 1; background: #fff; border-radius: 5px; padding: 4px 10px; font-size: 0.7rem; color: #6c757d; font-family: 'JetBrains Mono', monospace; border: 1px solid #d0d1d5; letter-spacing: 0.04em; }

 .odoo-nav { background: #714b67; color: #fff; padding: 0 14px; display: flex; align-items: center; height: 40px; font-size: 12px; letter-spacing: 0.04em; }
 .odoo-apps-icon { display: flex; align-items: center; gap: 6px; padding: 0 12px; height: 100%; font-weight: 500; letter-spacing: 0.04em; border-right: 1px solid rgba(255,255,255,.08); }
 .odoo-apps-icon svg { width: 14px; height: 14px; fill: #fff; }
 .odoo-breadcrumb { display: flex; align-items: center; gap: 8px; padding: 0 14px; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-breadcrumb .active { font-weight: 600; }
 .odoo-breadcrumb .sep { color: rgba(255,255,255,.4); }
 .odoo-nav-right { margin-left: auto; display: flex; align-items: center; gap: 14px; }
 .odoo-nav-right .icon { opacity: 0.85; font-size: 13px; }
 .odoo-avatar { width: 26px; height: 26px; border-radius: 50%; background: linear-gradient(135deg, #a78bfa, #7c3aed); color: #fff; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 10px; letter-spacing: 0.04em; }

 .odoo-submenu { background: #fff; border-bottom: 1px solid #dfdfe3; padding: 0 16px; display: flex; align-items: center; gap: 2px; height: 36px; font-size: 12px; overflow-x: auto; white-space: nowrap; letter-spacing: 0.04em; }
 .odoo-submenu-item { padding: 7px 12px; color: #212529; border-bottom: 2px solid transparent; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-submenu-item.active { color: #714b67; border-bottom-color: #714b67; font-weight: 600; }
 .odoo-submenu-item:hover { background: #f9f9fb; }

 .odoo-body { background: #f5f6f8; }
 .odoo-control-panel { background: #fff; border-bottom: 1px solid #dfdfe3; padding: 8px 16px; display: flex; align-items: center; gap: 10px; font-size: 12px; flex-wrap: wrap; letter-spacing: 0.04em; }
 .odoo-btn { background: #714b67; color: #fff !important; border: none; padding: 5px 12px; border-radius: 4px; font-size: 12px; font-weight: 500; cursor: pointer; font-family: inherit; text-decoration: none !important; display: inline-block; letter-spacing: 0.04em; }
 .odoo-btn-secondary { background: #fff; color: #212529 !important; border: 1px solid #c5c5cc; }
 .odoo-record-count { color: #6c757d; font-size: 11px; margin-left: auto; letter-spacing: 0.04em; }
 .odoo-search { flex: 1; min-width: 150px; max-width: 340px; background: #fff; border: 1px solid #dfdfe3; border-radius: 4px; padding: 5px 10px; display: flex; align-items: center; gap: 6px; font-size: 11.5px; color: #6c757d; letter-spacing: 0.04em; }
 .odoo-filter-tag { background: #e5f5f6; color: #017e84; padding: 2px 7px; border-radius: 3px; font-size: 10px; font-weight: 500; letter-spacing: 0.04em; }
 .odoo-view-switcher { display: flex; gap: 2px; background: #f0f0f3; border-radius: 4px; padding: 2px; }
 .odoo-view-btn { padding: 3px 8px; font-size: 11px; color: #6c757d; border-radius: 3px; letter-spacing: 0.04em; }
 .odoo-view-btn.active { background: #fff; color: #714b67; box-shadow: 0 1px 2px rgba(0,0,0,.1); font-weight: 600; }

 .kanban-wrap { padding: 14px; display: flex; gap: 10px; overflow-x: auto; min-height: 400px; background: #f5f6f8; }
 .kanban-column { min-width: 220px; max-width: 220px; display: flex; flex-direction: column; }
 .kanban-col-header { padding: 6px 8px 8px; font-size: 11px; font-weight: 600; color: #212529; text-transform: uppercase; letter-spacing: 0.04em; display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #714b67; margin-bottom: 8px; }
 .kanban-col-header .count { background: #714b67; color: #fff; padding: 1px 7px; border-radius: 10px; font-size: 9px; font-weight: 700; letter-spacing: 0.04em; }
 .kanban-card { background: #fff; border: 1px solid #dfdfe3; border-radius: 4px; padding: 8px 10px; margin-bottom: 6px; font-size: 11px; border-left: 3px solid transparent; letter-spacing: 0.04em; }
 .kanban-card.critical { border-left-color: #dc3545; }
 .kanban-card.high { border-left-color: #fd7e14; }
 .kanban-card.medium { border-left-color: #e8a33d; }
 .kanban-card.low { border-left-color: #28a745; }
 .kanban-card.breached { background: #fff5f5; border-color: #dc3545; border-left-width: 4px; }
 .kanban-card .ref { font-family: 'JetBrains Mono', monospace; font-size: 9.5px; color: #017e84; font-weight: 600; letter-spacing: 0.04em; }
 .kanban-card .title { font-weight: 600; color: #212529; letter-spacing: 0.04em; word-spacing: 0.03em; margin: 3px 0 6px; line-height: 1.3; }
 .kanban-card .meta { display: flex; justify-content: space-between; align-items: center; margin-top: 6px; padding-top: 6px; border-top: 1px solid var(--border-light); }
 .kanban-card .stars { color: #f39c12; letter-spacing: -1px; font-size: 10.5px; }
 .kanban-card .assignee { width: 20px; height: 20px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 8px; color: #fff; font-weight: 700; }
 .kanban-card .badge { padding: 1px 5px; border-radius: 3px; font-size: 8.5px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; }
 .badge-inc { background: #fee2e2; color: #F87171; }
 .badge-sr { background: #dbeafe; color: #1e40af; }
 .badge-sla-ok { background: #d1fae5; color: #22C55E; letter-spacing: 0.04em; }
 .badge-sla-risk { background: #fef3c7; color: #FB923C; letter-spacing: 0.04em; }
 .badge-sla-breach { background: #fee2e2; color: #F87171; letter-spacing: 0.04em; }
 .badge-sla-met { background: #d1fae5; color: #22C55E; letter-spacing: 0.04em; }

 .av-1 { background: #8e44ad; }
 .av-2 { background: #27ae60; }
 .av-3 { background: #e67e22; }
 .av-4 { background: #2980b9; }
 .av-5 { background: #c0392b; }
 .av-6 { background: #16a085; }

 .form-wrap { background: #f5f6f8; padding: 14px; }
 .form-container { background: #fff; border: 1px solid #dfdfe3; position: relative; }
 .form-statusbar { background: #fafafa; border-bottom: 1px solid #dfdfe3; padding: 10px 16px; display: flex; align-items: center; gap: 0; flex-wrap: wrap; }
 .stage-pill { background: #fff; border: 1px solid #c5c5cc; padding: 4px 10px; font-size: 10px; font-weight: 600; color: #6c757d; margin-right: -1px; clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%, 6px 50%); padding-left: 14px; padding-right: 16px; letter-spacing: 0.04em; }
 .stage-pill:first-child { clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%); padding-left: 10px; }
