 }

 html { scroll-behavior: smooth; font-size: 16px; -webkit-font-smoothing: antialiased; }
 body {
 font-family: 'Cairo', 'Tajawal', sans-serif;
 background: var(--bg); color: var(--text);
 line-height: 1.75;
 direction: rtl;
 text-align: right;
 }
 body * { font-family: 'Cairo', 'Tajawal', sans-serif !important; }
 ::selection { background: var(--brand-secondary); color: #fff; }
 strong { color: #E8F0FF; }
 a { color: var(--brand-primary); text-decoration: none; transition: 0.2s; }
 a:hover { color: var(--brand-secondary); text-decoration: underline; }
 h1, h2, h3, h4 { font-family: 'Cairo', 'Tajawal', sans-serif !important; font-weight: 700; color: #E8F0FF; line-height: 1.3; }
 h2 { font-size: 1.7rem; margin-bottom: 1.3rem; letter-spacing: 0; }
 p { color: #7A9DC8; margin-bottom: 1.3rem; }

 .container { max-width: var(--max-w-wide); margin: 0 auto; padding: 0 24px; }

 /* الهيرو */
 .hero {
 background: linear-gradient(135deg,#071020 0%,#0D2240 45%,#1A3A5C 80%,#1B5FC4 100%);
 color: #fff;
 position: relative;
 overflow: hidden;
 padding: 0;
 margin-bottom: 0;
 border-radius: 0;
 }
 .hero::before {
 content: '';
 position: absolute;
 top: -40%; left: -20%;
 width: 700px; height: 700px;
 background: radial-gradient(circle, rgba(27,111,228,.25) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero::after {
 content: '';
 position: absolute;
 bottom: -30%; right: -10%;
 width: 500px; height: 500px;
 background: radial-gradient(circle, rgba(0,196,204,.15) 0%, transparent 70%);
 pointer-events: none;
 }
 .hero .container { position: relative; z-index: 2; padding-top: 80px; padding-bottom: 72px; }
 .breadcrumb {
 font-size: .82rem;
 color: rgba(255,255,255,.5);
 margin-bottom: 28px;
 font-weight: 500;
 display: flex;
 gap: 0.5rem;
 flex-wrap: wrap;
 }
 .breadcrumb a { color: rgba(255,255,255,.6); }
 .breadcrumb a:hover { color: #fff; text-decoration: none; }
 .breadcrumb strong { color: rgba(255,255,255,.8); font-weight: 600; }
 .subtitle {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 background: rgba(0,196,204,.12);
 border: 1px solid rgba(0,196,204,.3);
 border-radius: 100px;
 padding: 6px 18px 6px 12px;
 font-size: .78rem;
 font-weight: 600;
 color: #00C4CC;
 margin-bottom: 28px;
 letter-spacing: .3px;
 }
 h1 {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: clamp(1.8rem, 4vw, 2.8rem);
 font-weight: 800;
 line-height: 1.3;
 margin-bottom: 20px;
 letter-spacing: -.01em;
 color: #fff;
 }
 .hero-desc {
 font-size: 1.05rem;
 color: #8AAFD8;
 max-width: 620px;
 line-height: 1.75;
 margin-bottom: 36px;
 }
 .cta-group { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }
 .btn {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 padding: 14px 28px;
 border-radius: 10px;
 font-weight: 700;
 font-size: .92rem;
 border: none;
 cursor: pointer;
 transition: all .25s;
 text-decoration: none;
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 }
 .btn-primary {
 background: var(--brand-gradient);
 color: #fff;
 box-shadow: 0 4px 16px rgba(27,111,228,.3);
 }
 .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 28px rgba(27,111,228,.4); text-decoration: none; }
 .btn-secondary {
 background: transparent;
 color: #fff;
 border: 1.5px solid rgba(255,255,255,.25);
 }
 .btn-secondary:hover { border-color: rgba(255,255,255,.5); background: rgba(255,255,255,.05); text-decoration: none; }

 .stats {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
 gap: 20px;
 max-width: 700px;
 margin: 2.2rem 0;
 }
 .stat-card {
 text-align: center;
 padding: 20px 12px;
 background: rgba(255,255,255,.04);
 border: 1px solid rgba(255,255,255,.08);
 border-radius: var(--radius);
 backdrop-filter: blur(8px);
 }
 .stat-card strong {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 1.7rem;
 font-weight: 800;
 color: #00C4CC;
 display: block;
 line-height: 1.2;
 }
 .stat-card span { font-size: .78rem; color: rgba(255,255,255,.5); font-weight: 500; margin-top: 4px; display: block; }
 .meta {
 display: flex;
 gap: 2rem;
 flex-wrap: wrap;
 color: rgba(255,255,255,.5);
 font-size: 0.9rem;
 margin-bottom: 0;
 }

 /* الشبكة الرئيسية */
 .main-grid { display: grid; grid-template-columns: 260px 1fr; gap: 3.5rem; align-items: start; margin-top: 64px; }
 @media (max-width: 950px) { .main-grid { grid-template-columns: 1fr; } }

 /* فهرس المحتوى */
 .toc {
 position: sticky;
 top: 2rem;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 28px 24px;
 margin-bottom: 3rem;
 box-shadow: var(--shadow);
 }
 .toc h3 {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-weight: 800;
 font-size: .95rem;
 margin-bottom: 16px;
 color: #C8DEFF;
 display: flex;
 align-items: center;
 gap: 8px;
 }
 .toc ul { list-style: none; padding-right: 0; padding-left: 0; }
 .toc li {
 margin-bottom: 0.8rem;
 border-right: 2px solid var(--border);
 border-left: none;
 padding-right: 1rem;
 padding-left: 0;
 transition: 0.2s;
 }
 .toc li:hover { border-right-color: var(--brand-secondary); }
 .toc a { color: var(--text-muted); font-size: 0.88rem; font-weight: 500; }
 .toc a:hover { color: var(--brand-secondary); text-decoration: none; }

 /* الأقسام */
 section { margin-bottom: 5rem; scroll-margin-top: 2.5rem; }
 h2 {
 font-size: 1.7rem;
 margin-bottom: 1.3rem;
 position: relative;
 display: inline-block;
 letter-spacing: 0;
 color: #E8F0FF;
 }
 h2::after {
 content: '';
 position: absolute;
 bottom: -10px;
 right: 0;
 left: auto;
 width: 45px;
 height: 4px;
 background: var(--brand-secondary);
 border-radius: 2px;
 }
 h3 { font-size: 1.3rem; margin: 2rem 0 1rem; color: #E8F0FF; }

 /* شبكة البطاقات */
 .card-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
 gap: 20px;
 margin-top: 1.8rem;
 }
 .card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 28px 24px;
 transition: all .3s;
 box-shadow: var(--shadow-sm);
 }
 .card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .card-icon { font-size: 2rem; margin-bottom: 0.8rem; display: block; }
 .card h3 { margin-top: 0; font-size: 1.1rem; margin-bottom: 0.5rem; color: #E8F0FF; }

 /* مراحل سير العمل */
 .workflow { position: relative; }
 .phase {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 1.8rem;
 margin-bottom: 1.2rem;
 border-right: 6px solid var(--brand-secondary);
 border-left: 1px solid var(--border);
 box-shadow: var(--shadow-sm);
 }
 .phase-header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 margin-bottom: 0.8rem;
 flex-wrap: wrap;
 gap: 0.8rem;
 }
 .phase-header strong { font-size: 1.1rem; color: #E8F0FF; font-family: 'Cairo', 'Tajawal', sans-serif !important; }
 .phase-num {
 background: rgba(27,111,228,.18);
 color: #00C4CC;
 padding: 0.4rem 1rem;
 border-radius: 40px;
 font-weight: 600;
 font-size: 0.85rem;
 border: 1px solid var(--border);
 }
 .phase p { color: #7A9DC8; }

 /* شبكة الوحدات */
 .bento-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
 gap: 24px;
 }
 .module-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 32px;
 transition: all .3s;
 position: relative;
 overflow: hidden;
 }
 .module-card:hover {
 border-color: var(--brand-accent);
 box-shadow: var(--shadow-lg);
 transform: translateY(-4px);
 }
 .module-card h3 {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 1.1rem;
 font-weight: 700;
 margin: 0 0 10px;
 color: #E8F0FF;
 display: flex;
 align-items: center;
 gap: 8px;
 }
 .module-card ul { margin: 1.2rem 0 0 0; padding-right: 1.4rem; padding-left: 0; color: var(--text-secondary); }
 .module-card li { margin-bottom: 0.7rem; font-size: 0.92rem; color: #7A9DC8; }

 /* مصفوفة الأدوار */
 .matrix-wrap {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 margin-top: 1.8rem;
 box-shadow: var(--shadow-sm);
 overflow-x: auto;
 }
 .role-matrix {
 display: grid;
 grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr;
 gap: 8px;
 min-width: 620px;
 }
 .role-matrix .cell {
 padding: 14px 10px;
 text-align: center;
 border-radius: var(--radius-sm);
 font-weight: 600;
 font-size: 0.88rem;
 }
 .role-matrix .hdr { background: #112B4E; color: #E8F0FF; font-weight: 700; border: 1px solid #1A3050; }
 .role-matrix .row-hdr { background: #0F1E35; color: #C8DEFF; font-weight: 700; text-align: right; padding-right: 16px; padding-left: 4px; border: 1px solid #1A3050; }
 .role-matrix .yes { background: var(--green-light); color: #22C55E; border: 1px solid #a7f3d0; }
 .role-matrix .partial { background: var(--amber-light); color: #FB923C; border: 1px solid #fde68a; }
 .role-matrix .no { background: #fee2e2; color: #F87171; border: 1px solid #fecaca; }

 /* خط الأنابيب */
 .pipeline {
 display: flex;
 align-items: center;
 gap: 8px;
 flex-wrap: wrap;
 padding: 1.4rem;
 background: var(--surface-alt);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 margin: 1.5rem 0;
 }
 .pipe-stage {
 background: var(--surface);
 border: 1px solid var(--border);
 padding: 8px 14px;
 border-radius: 8px;
 font-size: 0.85rem;
 font-weight: 600;
 color: var(--text);
 }
 .pipe-stage.start { border-color: var(--brand-secondary); color: var(--brand-secondary); }
 .pipe-stage.hold { background: var(--amber-light); border-color: var(--amber); color: var(--amber); }
 .pipe-stage.done { background: var(--green-light); border-color: var(--green); color: var(--green); }
 .pipe-arrow { color: var(--text-muted); font-weight: 700; }

 /* بطاقات الامتثال */
 .compliance-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .country-card {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 padding: 28px 20px;
 text-align: center;
 transition: all .3s;
 }
 .country-card:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .flag { font-size: 2rem; margin-bottom: 12px; display: block; }
 .country-card h3 { font-size: 1rem; margin: 0 0 8px; color: #E8F0FF; }
 .country-card p { font-size: 0.85rem; color: #4A6FA0; }

 /* الشهادات */
 .testimonial-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
 gap: 1.8rem;
 margin-top: 2rem;
 }
 .testimonial {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2rem;
 }
 .testimonial p { font-style: italic; font-size: 1rem; color: #7A9DC8; }
 .testimonial-author { margin-top: 1.2rem; color: var(--brand-secondary); font-weight: 600; }

 /* النتائج */
 .results-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
 gap: 20px;
 margin-top: 2rem;
 }
 .result-item {
 text-align: center;
 padding: 32px 20px;
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 transition: all .3s;
 }
 .result-item:hover { border-color: var(--brand-accent); box-shadow: var(--shadow); }
 .result-item strong {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 2.4rem;
 font-weight: 900;
 color: #00C4CC;
 display: block;
 margin-bottom: 8px;
 }
 .result-item p { font-weight: 700; color: #C8DEFF; margin-bottom: 6px; }

 /* الأسئلة الشائعة */
 .faq-item {
 background: var(--surface);
 border: 1px solid var(--border);
 border-radius: var(--radius);
 margin-bottom: 1rem;
 overflow: hidden;
 transition: all .3s;
 }
 .faq-item:hover { border-color: var(--brand-secondary); background: #0F1E35; }
 .faq-q {
 padding: 20px 24px;
 cursor: pointer;
 font-weight: 700;
 display: flex;
 justify-content: space-between;
 align-items: center;
 color: #C8DEFF;
 font-size: .95rem;
 user-select: none;
 text-align: right;
 direction: rtl;
 }
 .faq-q::after {
 content: '+';
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 1.4rem;
 font-weight: 300;
 color: var(--brand-secondary);
 transition: transform .3s;
 flex-shrink: 0;
 }
 .faq-q { background: #0F1E35; }
 .faq-item.active .faq-q { background: #112B4E; }
 .faq-a {
 max-height: 0;
 overflow: hidden;
 transition: max-height .4s ease, padding .3s ease;
 padding: 0 24px;
 color: #7A9DC8;
 }
 .faq-item.active .faq-a {
 max-height: 500px;
 padding-bottom: 20px;
 }
 .faq-item.active .faq-q::after { content: '−'; }

 /* قسم دعوة للعمل */
 .cta-section {
 background: var(--brand-gradient);
 border-radius: var(--radius-lg);
 padding: 48px 40px;
 text-align: center;
 color: #fff;
 margin: 56px 0;
 position: relative;
 overflow: hidden;
 }
 .cta-section::before {
 content: '';
 position: absolute;
 top: -50%; left: -20%;
 width: 400px; height: 400px;
 background: radial-gradient(circle, rgba(255,255,255,.1) 0%, transparent 70%);
 pointer-events: none;
 }
 .cta-section h2 {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 1.6rem;
 font-weight: 800;
 margin-bottom: 12px;
 color: #fff;
 }
 .cta-section h2::after { display: none; }
 .cta-section p { color: rgba(255,255,255,.9); margin-bottom: 28px; font-size: 1.05rem; }
 .cta-section .btn {
 background: #fff;
 color: var(--brand-primary);
 font-weight: 700;
 padding: 1.1rem 2.5rem;
 }
 .cta-section .btn:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,.15); }

 /* تمييز الحالة */
 .case-highlight {
 background: var(--surface-alt);
 border-radius: var(--radius);
 padding: 2.2rem;
 border: 1px solid var(--border);
 margin: 2.5rem 0;
 }
 .case-highlight h3 { margin-top: 0; color: var(--brand-secondary); }

 /* قسم اللغة العربية */
 .arabic-callout {
 background: linear-gradient(135deg, rgba(0,196,204,.08) 0%, rgba(27,111,228,.08) 100%);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 padding: 2.5rem;
 margin-top: 2rem;
 }
 .arabic-callout h3 { margin-top: 0; }
 .ar-text {
 font-family: 'Cairo', 'Tajawal', sans-serif !important;
 font-size: 1.1rem;
 color: var(--text);
 direction: rtl;
 text-align: right;
 padding: 1.2rem 1.4rem;
 background: var(--surface);
 border-radius: var(--radius);
 border: 1px solid var(--border);
 margin-top: 1rem;
 line-height: 1.9;
 }

 footer {
 text-align: center;
 padding: 3rem 0;
 border-top: 1px solid var(--border);
 margin-top: 4rem;
 color: #4A6FA0;
 background: var(--bg);
 }
 footer a { color: var(--brand-secondary); }
 .share-links {
 text-align: center;
 margin-top: 2.5rem;
 color: #4A6FA0;
 font-size: 0.95rem;
 }
 .share-links a { margin: 0 0.5rem; }

 @media (max-width: 600px) {
 .hero .container { padding-top: 48px; padding-bottom: 48px; }
 h1 { font-size: 1.8rem; }
 .stats { grid-template-columns: 1fr 1fr; }
 .toc { position: relative; top: 0; margin-bottom: 2rem; }
 }
 </style>
</head>
