var sections=['step1','step2','step3','step4','step5'];
function onScroll(){
 var scrollY=window.pageYOffset,offset=80,current=1;
 sections.forEach(function(id,i){
 var el=document.getElementById(id);
 if(el&&el.getBoundingClientRect().top+scrollY-offset<=scrollY)current=i+1;
 });
 document.querySelectorAll('.st-item').forEach(function(el){el.classList.remove('active')});
 var a=document.querySelector('.st-item[data-step="'+current+'"]');
 if(a)a.classList.add('active');
 document.querySelectorAll('.mhs-pill').forEach(function(p){p.classList.remove('active')});
 var p=document.querySelector('.mhs-pill[data-step="'+current+'"]');
 if(p)p.classList.add('active');
}
window.addEventListener('scroll',onScroll,{passive:true});
